WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[84649] = { title = "Marran Trollbane", description = "I am Colonel Veronica Nials, and I am in command of Stromgarde in Lord Trollbane's absence.\n\nI'm sure while aiding our people you've heard the name \"Marran\" in Stromgarde. Lady Marran Trollbane is Danath's niece. She was briefly regent while Lord Danath Trollbane campaigned for troops for Khaz Algar. \n\nHer actions during his absence led him to imprison her when he returned.\n\nThat said, Lord Trollbane felt Faerin should speak to her. Perhaps to get... perspective. I can take you to her if you wish.", objectives = "" }
WordHunterWoW_QuestEN[84650] = { title = "Finding Refuge at Refuge Pointe", description = "If you want to find Lord Trollbane and tell him your theory about Lady Marran, the missive called him to Hammerfall, far to the east of here.\n\nHe may have stopped at Refuge Pointe on the way--it's a Stromic encampment about halfway to the orc town. Because of the frequent bandit attacks in the area, I believe he meant to stop and check in with our people there.\n\nYou might catch up with him there.", objectives = "" }
WordHunterWoW_QuestEN[84651] = { title = "A Familiar Face", description = "Early on, these attacks on our settlements seemed to be pockets of bandits competing for resources.\n\nNow they are better coordinated. As if they are working together as a group. \n\nThat's bad news for everyone.\n\nBut rivals don't come together without a strong leader. And without them, they will fall.\n\nIf you're willing, find the leader of this attack on Refuge Pointe and eliminate them.", objectives = "" }
WordHunterWoW_QuestEN[84652] = { title = "Supply Run", description = "Stromgarde's troops are in Khaz Algar and it cannot protect its outlying settlements. \n\nHammerfall does what it can to help, but we too fight in Khaz Algar.\n\nWe've taken many injured Stromic refugees to Hammerfall, but feeding them all has strained our resources.\n\nBut there may be a way to help more people.\n\nVikki told me Refuge Pointe is a supply depot for nearby settlements. If we can get our hands on some supplies, we can care for more refugees in Hammerfall.", objectives = "" }
WordHunterWoW_QuestEN[84656] = { title = "Onward to Hammerfall", description = "First an attack on Newstead Farm by Defias, now an attack on Refuge Pointe by these Scarlet Crusaders. \n\nDifferent groups of bandits, but both speak of this \"Red Dawn\" and carry the same emblem. \n\nAlso, Joseph is directly involved.\n\nThis all seems connected... and it leads back to Marran.\n\nDanath needs to know what's going on. If he's not here, he should already be at Hammerfall. \n\nWe should head there as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[84657] = { title = "Return to Stromgarde", description = "Eitrigg was right. The Red Dawn are trying to start a conflict between the Horde and the Alliance.\n\nWe need to get back to Stromgarde and tell Colonel Nials that Danath has been kidnapped. She will surely commit all her resources to a search!\n\nCome, {name}. There's no time to waste!", objectives = "" }
WordHunterWoW_QuestEN[84658] = { title = "Finding Family", description = "Where's my mama? My papa?\n\nEllie?\n\n<Maggie looks around with tears in her eyes.>\n\nI was followin' Mr. Gresham and Clarabelle when we saw the bandits. He grabbed me up and we ran here.\n\nI don't know where Mama and Papa and Ellie are.\n\nCan you find them for us? Clarabelle is starting to get worried...\n\n<Maggie sniffles.>", objectives = "" }
WordHunterWoW_QuestEN[84659] = { title = "The Search for Faerin", description = "I saw Faerin being taken away, but couldn't follow without them seeing me. She's probably being held in another building.\n\nGo find her. Hopefully, she's still alive...\n\nAnd see if you can find any more information on the Red Dawn. There's no way we should have been overwhelmed so quickly. Colonel Nials and Lady Trollbane must have installed their cronies everywhere.\n\nThe more information we have, the more we can use against them when we fight back.", objectives = "" }
WordHunterWoW_QuestEN[84664] = { title = "Making the Underworld Go Round", description = "Hey there, 'Overcrawler.' You're lookin' more than a little out of your element there. You get run over by an airship or something?\n\nWhatever. Doesn't matter. Take it from one outsider to another, if you're going to survive down here you're gonna need to learn the rules of the road. Gold's all well and good where you came from, but down here you're gonna need Kej, and lots of it.\n\nNow here. Consider this a token of good will from Lady Pedipalps up there. Go get yourself something nice.", objectives = "" }
WordHunterWoW_QuestEN[84667] = { title = "The G.O.L.E.M. of Progress", description = "The citizens of Undermine cry out for help! They need protection! They need joy! They need to get by!\n\nAs an inventor, I've spent my life building somethin' that'll solve our people's problems, and it's just about ready for a test run. I'm calling it my Goblin Optimal Livability Enhancement Machine, or G.O.L.E.M. for short!\n\nFind some problems and take it out for a spin- and take my son with you! Pitz doesn't have an inventor's bone in his body, but certainly he can yak it up with the neighbors.", objectives = "" }
WordHunterWoW_QuestEN[84672] = { title = "Garbage Day", description = "My old man's got all these crazy ideas about helping the world... I dunno. It's all a bit over my head, but I guess that's why I was never the inventor he wanted me to be.\n\nStill, I've got some thoughts on how to solve problems around here. Like those dang rodents getting litter all over the streets!\n\nIt might not revitalize the spirit of the community or whatever, but I bet people would be happier if we cleaned up the streets.", objectives = "" }
WordHunterWoW_QuestEN[84673] = { title = "World's Okayest Inventor", description = "I'm... not the inventor my old man is. Or much of an inventor at all, really. My masterwork is over by the wall there, but to be honest, there's a lot of work that still needs to be done to get it to do... anything.\n\nBut this! This could be my big chance to prove to Pops that I've got what it takes to make him proud!\n\nAll we need to do is actually, uh, figure out how to repair this thing. How hard could it be?", objectives = "" }
WordHunterWoW_QuestEN[84674] = { title = "The G.O.L.E.M. Goes Berserk!", description = "The G.O.L.E.M.'s gone berserk! Haywire! Bonkers!\n\nI gotta go chase it down--who knows what kinda trouble an invention that powerful could cause! Plus, imagine how mad my old man would be if we lost it!\n\nI hate to ask you to clean up my messes, but someone's gotta hang back and get everything in order again. Could you do that?", objectives = "" }
WordHunterWoW_QuestEN[84675] = { title = "Showdown in the Attic", description = "I've been so blind! Everything's falling apart!\n\nThe neighborhood is worse off than ever, and the G.O.L.E.M.'s to blame! And my boy, my dear Pitz...\n\nHe ran into this building to try and stop the contraption. I was so hard on him, and now I might never see him again...\n\nYou gotta find him. And stop that thing once and for all.", objectives = "" }
WordHunterWoW_QuestEN[84680] = { title = "Rock 'n Stone Revival", description = "The attacking vrykul harness salt and brine elementals, turning them against their foes.\n\nTo counter their assault, we can harness them as well.\n\nUse this Rock Reviver to unleash the elementals residing within nearby stones, transforming them into powerful allies. With their help, we can defeat this vrykul threat.", objectives = "" }
WordHunterWoW_QuestEN[84682] = { title = "Of Pacts and Patrons", description = "The Severed Threads is ready for you and your allies. You will be a lit torch to Ansurek's webs.\n\nThe General, the Vizier, and, myself, the Weaver, each have differing methods of combating our foes... and different benefits of aiding our accomplices. You may prefer to prioritize one, or perhaps to dabble with all three instead.\n\nMeet with our representatives, and inform yourself on our varying practices. Then you may forge your first Pact.\n\nDon't worry, little morsel, no choice is ever permanent.", objectives = "" }
WordHunterWoW_QuestEN[84683] = { title = "Into the Gutter", description = "What're you doing here? Sabotagin'?\n\nI can understand that. Things are way out of hand. But if we explode this pipe here, it'll get even worse. Black Blood everywhere. Maybe together we could come up with somethin' real to do.\n\nMeet me in Gutterville. We'll talk more, away from these awful slimes!", objectives = "" }
WordHunterWoW_QuestEN[84684] = { title = "Ratts' Race", description = "I saw a vulpera acting very suspicious. She seemed... on edge. I think I saw a knife at her side and a look of dark magic in her eyes.\n\nShe noticed me staring and immediately fled. Is she a wanted criminal?\n\nShe... dropped this. Here.", objectives = "" }
WordHunterWoW_QuestEN[84687] = { title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "" }
WordHunterWoW_QuestEN[84688] = { title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "" }
WordHunterWoW_QuestEN[84693] = { title = "Weaver's Lair Profession Table", description = "Present this token to Ak'itaz in the Weaver's Lair to have your own personal profession table constructed.", objectives = "" }
WordHunterWoW_QuestEN[84700] = { title = "Pacts Below", description = "This weave-rat carries a note upon its body. It's addressed to you, from the Widow Arak'nai.\n\n\"Dearest morsel,\n \nMyself and the other members of our Severed Threads triumvirate request your presence. Azj-Kahet itself is on the precipice of an evolution, but we'll need your... unique methods if we're to see it through.\n\nAnd, as always, the rewards to you and your cause will be quite magnificent.\"", objectives = "" }
WordHunterWoW_QuestEN[84701] = { title = "The Speaker", description = "So there is someone else who has experienced something close to what I experienced. Yet it is not the same.\n\nI must speak with him.", objectives = "" }
WordHunterWoW_QuestEN[84704] = { title = "A Different Point of View", description = "Danath is not here. \n\nFaerin says he journeyed to Hammerfall because we requested a meeting. I sent no such message to him nor anyone else. \n\nI will dispatch outriders immediately to search for him. \n\nWhile we wait for their return... You and Karga's quick thinking may have saved our human refugees. We had just run out of food to give them.\n\nDistribute the crates directly to them. I'm sure they will be grateful for the food inside.", objectives = "" }
WordHunterWoW_QuestEN[84705] = { title = "Withering the Witherbark", description = "The Witherbark have always been an annoyance since I have been here. But now?\n\nSomething has stoked their ire. They are attacking human settlements. Perhaps the Red Dawn is again to blame.\n\nEitrigg has ordered us to try to help the humans they attack. We have stepped up our patrols and welcomed refugees. \n\nBut we need someone to go to their village and bloody the Witherbark's noses. They're overconfident. They think they can get away with attacking our outriders!\n\nMake them think twice about that.", objectives = "" }
WordHunterWoW_QuestEN[84706] = { title = "Crime Family", description = "This Syndicate human came to us hoping to trade information for a rescue mission. The Syndicate is a recent thorn in our side, so I had half a mind to cut him down where he stood. \n\nBut he claims to have vital information, and with this news of Danath's disappearance... it might be worth the risk to do as he asks.\n\nHe has three brothers being held captive inside Witherbark Village. Go in, find them, and if they're alive, extract them.", objectives = "" }
WordHunterWoW_QuestEN[84707] = { title = "To See a Troll", description = "There's no word from the outriders yet, but Eitrigg has not told Geya'rah of Danath's disappearance. \n\nI have told him we would go and give her the news.\n\nShe's at Go'Shek Farm dealing with a Witherbark troll attack. Eitrigg says they've become increasingly aggressive recently. \n\nI can't help but think of the history there--of the Troll Wars and Arathi battles. But I admit I see them differently now after learning more about the Horde.\n\nLet's go. We can look for Danath while we're out there.", objectives = "" }
WordHunterWoW_QuestEN[84708] = { title = "The Syndicate Strikes Back", description = "This human is claiming the Syndicate scum are going to attack Hammerfall! Another day I would not be concerned. But with the outriders dealing with the Witherbark and searching for Danath, Hammerfall is undefended!\n\nLet's go {name}. We must defend our home!", objectives = "" }
WordHunterWoW_QuestEN[84709] = { title = "Hammerfall Down", description = "<Eitrigg growls in frustration.>\n\nI was such a fool!\n\nI should not have sent away those outriders. Without them, the Syndicate have overrun Hammerfall.\n\nAnd were it not for my fool heart... The \"refugees\" turned out to be Syndicate spies, curse their greasy hides...\n\nBut now you're here. Now, we can force the Syndicate out. Eliminate their soldiers and save any trapped civilians. \n\nThose spies have had enough of my open hand. Now they'll suffer my fists!", objectives = "" }
WordHunterWoW_QuestEN[84710] = { title = "Once Bitten Twice Shy", description = "I caught a glimpse of who was leading the attack.\n\nIt looks like Joseph the Enlightened may be less full of hot air than we thought he was.\n\nIs he now part of the Syndicate? I thought he was part of the \"Crusade.\" I suppose it doesn't matter. If we want to stop the attack, we'll have to take him out.", objectives = "" }
WordHunterWoW_QuestEN[84711] = { title = "Danath's Disappearance", description = "My outriders discovered a destroyed caravan on the road. \n\nAround it were the bodies of Stromic soldiers.\n\nIt could be Danath's escort. Or it could be another hapless group.\n\nEither way, we must investigate. Let us hope Danath is not among the dead.", objectives = "" }
WordHunterWoW_QuestEN[84712] = { title = "False Flag", description = "This was not done by simple bandits. This spot was chosen specifically for an ambush. And these troops were taken down quickly and efficiently.\n\nIf Danath was heading to Hammerfall, this road is the most direct route. That makes it predictable.\n\n<Geya'rah grimaces.>\n\nWe must search for Danath among the dead and find out what happened here. Leave no stone left unturned.", objectives = "" }
WordHunterWoW_QuestEN[84713] = { title = "Fallen Fortress", description = "If Danath's kidnappers want to keep him from prying eyes, Ar'gorok is the perfect place. \n\nIt's been abandoned for years, but its buildings still stand. All the \"Red Dawn\" could be there and no one would be the wiser.\n\nWe must find Danath quickly, {name}. Hammerfall is vulnerable and tensions are high. A missing leader is just the excuse Marran needs to start a war.", objectives = "" }
WordHunterWoW_QuestEN[84714] = { title = "From Ironforge With Love", description = "This \"Red Dawn\" is occupying the fortress of Ar'gorok. Bandits of all types and bands have taken refuge here under their banner.\n\nAnd I'm sure they've brought their spoils with them.\n\nIt may help calm tensions if we recover the goods they've stolen and return them to their rightful owners in the Arathi Highlands.\n\nSee if they are carrying anything with them.", objectives = "" }
WordHunterWoW_QuestEN[84715] = { title = "The Search for Danath", description = "Using Ar'gorok as a base was clever. Very clever.\n\nIt looks like the bulk of their forces are here. If Danath is alive, I'm certain they would keep him here.\n\nSearch the buildings for him. And look for any information on this Red Dawn that you can. Anything might be helpful in taking them down. \n\nLet's hope Danath is alive. If he isn't, a long and bloody conflict is ahead of us.", objectives = "" }
WordHunterWoW_QuestEN[84716] = { title = "Returning to Stromgarde", description = "While feigning sleep, I heard the guards brag about the Red Dawn's plans for Stromgarde.\n\nMy kidnapping was just the start.\n\nColonel Nials--after all these years! She will be the one to turn the key and free Marran, my niece, to do as she wishes and start a coup!\n\nMarran will lead Stromgarde's army and the Red Dawn to Hammerfall to secure the Highlands for \"Strom.\"\n\n<Danath's face is red with fury, but his eyes water with tears.>\n\nWe must gather our allies... and confront these traitors!", objectives = "" }
WordHunterWoW_QuestEN[84717] = { title = "Rise of the Red Dawn", description = "Danath and Eitrigg ran ahead to confront Marran. They hope if they stop her, they can end the coup--and the bloodshed.\n\nBut after seeing Joseph the Enlightened's handiwork first hand... \n\nDespite how unorthodox he may be, he's still a danger. And I hate to say it, but I would relish the chance to finally take that underhanded cretin down.\n\nHe's blocking our path up ahead at city hall. Let's take him down and then help Danath and Eitrigg end this war.", objectives = "" }
WordHunterWoW_QuestEN[84719] = { title = "The Expedition Awaits", description = "Greetings, {name}! Are you here to answer the Siren Isle's call to adventure?\n\nRecently, a goblin salvage team discovered an isle with a strange \"singing crystal\" at its center.\n\nLike the goblins, the Arathi of Hallowfall have taken a keen interest in this crystal--as have we. We've been preparing an expedition to the isle!\n\nMost of the expedition has gone ahead, but the goblins last vessel is set to leave momentarily.\n\nIf you hurry, you can catch them before they leave and join us!", objectives = "" }
WordHunterWoW_QuestEN[84720] = { title = "To the Siren Isle!", description = "The Siren Isle is a myst'ry. A potentially profitable one.\n\nMy crew thought they hit it big when they found a deserted island with some strange, singin' crystal...\n\nTurns out, everyone in Dornogal is interested in unclaimed \"strange singin' crystals.\" Both the Arathi and earthen scrambled quick an' were off before we could even charter a zeppelin!\n\nFortunately for us, Ricket and crew have gone ahead to set up.\n\nWe're the last to depart, an' I'm itchin' to go. What're we waitin' on?", objectives = "" }
WordHunterWoW_QuestEN[84721] = { title = "To Scan a Crystal", description = "In order to understand the \"singing crystal\" at the heart of the island, we will need some special machinery.\n\nWe have forged a device to scan its exposed facets, but the crystal's energies are far too complex to read. It has a highly unusual energy signature.\n\nThe goblins and Arathi seem keen to contribute, so let us proceed with their help.\n\nTake my toolbox and retrieve the prototype and the components the Arathi and goblins have prepared.", objectives = "" }
WordHunterWoW_QuestEN[84722] = { title = "Facet-nating Signals", description = "Intriguing! \n\nThese radiant remnants from the Arathi seemed to have given our device the necessary focus it needed. All that remains is to attune it properly to its size.\n\nIn order to attune to the signal, we'll need to set up some pylons around the site.\n\nThere is testing to initiate, {name}. Follow me if you would like to assist me.", objectives = "" }
WordHunterWoW_QuestEN[84723] = { title = "Buried Secrets", description = "These ruins are... quite old. Well, old by most outlanders' standards.\n\nWhich begs the question: was finding this chamber the unfriendly outlanders' directive, or was it finding the tablet?\n\nOne clue is that my readings suggest energy is flowing through the tablet as a conduit rather than originating from it.\n\nShall we take a closer look?\n\nPerhaps investigation will yield some answers--and the source of the energy readings.", objectives = "" }
WordHunterWoW_QuestEN[84724] = { title = "The Radiant Vault", description = "This vault... this crystal...\n\nWho made this place? Who lived here? And who is this \"Cyrce\" we keep seeing mentioned on the tablets?\n\nWhen we set off to learn about the crystal, I did not anticipate discovering the remnants of an ancient civilization far beneath the earth.\n\n<Bargus ruffles his wiry moustache before glancing at you.>\n\nThis bears closer examination, don't you think?", objectives = "" }
WordHunterWoW_QuestEN[84725] = { title = "The Circlet Calls", description = "<Angorla peers at you from over her spectacles with excitement.>\n\nCan you hear it, {name}?\n\nThis small, humble citrine is calling out to the circlet... just as the Siren Crystal called out to you and to all of us.\n\nI am uncertain what will happen when you reunify them... but there's only one way to find out.\n\nPlace the circlet upon your finger and socket the citrine into the setting.", objectives = "" }
WordHunterWoW_QuestEN[84726] = { title = "Uncovered Mysteries", description = "<Angorla takes your hand in hers and examines the crystal-embedded circlet closely.>\n\nCan you feel the energy humming through it, {name}? The circlet feels... awake. \n\nPerhaps more secrets lie around the isle, waiting for you to uncover them.\n\nDawn encouraged us to explore and learn about this isle, but I've got my work cut out for me here.\n\nWhy don't you see what other secrets you can find?", objectives = "" }
WordHunterWoW_QuestEN[84727] = { title = "The Second Signal", description = "An unexpected development.\n\nThe energy signature appears to have a secondary source--and it is just north of here.\n\nCuriosity activated.\n\nJudging from the estimated size of the crystal, I theorize it might be a secondary exposed facet.\n\nFurther investigation is required. Follow me.", objectives = "" }
WordHunterWoW_QuestEN[84728] = { title = "Reforged Anew", description = "The cracked citrine you found seems to be a perfect fit for one of the sockets found in the ring, yet...\n\n<As Angorla sockets the shard into the ring, the citrine wiggles loose and pops out.>\n\nThe ring appears to be rejecting the piece. If we can repair the citrine and stabilize the energy within the shard, perhaps the ring will accept it?\n\nSince you've been so helpful with Bargus, care to lend another hand?", objectives = "" }
WordHunterWoW_QuestEN[84730] = { title = "An Armored Charge", description = "The inorganic material of this island is peculiar. The effects of salt water and years of storm erosion have enriched the minerals of this place.\n\nAnd enriched minerals are exactly the type of material an Ordinant seeks to infuse into new armaments.\n\nBring me a considerable amount of storm-flecked debris from the isle's myriad of creatures. I would like to see if they are suitable for my craft.", objectives = "" }
WordHunterWoW_QuestEN[84731] = { title = "Storm Breadcrumb", description = "", objectives = "" }
WordHunterWoW_QuestEN[84735] = { title = "Truth of the Dark Irons", description = "Few know the truth of the Dark Iron clan. Even fewer have seen it for themselves.\n\nThe Timewalkers have agreed to take us back. They will send us to the time when our clan lost its emperor. And in doing so, I hope I can show you everything that came from that defeat. The good. The bad...\n\nWill you see the truth for yourself?", objectives = "" }
WordHunterWoW_QuestEN[84740] = { title = "Bridge to Nowhere", description = "Are you heading to the dunes? I'm looking for my sister, Shahata. I don't know if she's alive, but I have to find her.\n\nThe only place I can think to start the search is our village. K'aresh is nothing like I remember. I need landmarks--anything I can recognize to navigate by.\n\nTake this echo surveyor. It will reveal traces of the past--hopefully enough for me to orient us.", objectives = "" }
WordHunterWoW_QuestEN[84741] = { title = "Signs in the Sands", description = "Things are starting to feel familiar. I think I know the way back to my village.\n\nI should tell you... I'm not just looking for my sister. Our mother died when I was studying in the cities. Shahata buried her under her favorite tree, but I wasn't there. I swore I would come home to conduct the funeral rites, but I didn't make it in time.\n\nI have left my oath unfulfilled for far too long. I owe it to mother to at least try now. Come--let's search the village.", objectives = "" }
WordHunterWoW_QuestEN[84755] = { title = "The Final Toy", description = "Maru discovered that one of her toys is now missing!\n\nCould this be related to the other missing toys that you previously helped her friends with?", objectives = "" }
WordHunterWoW_QuestEN[84756] = { title = "The Toy Thief", description = "My toy! It's been stolen!\n\nWe have to figure out da culprit before they take more toys!", objectives = "" }
WordHunterWoW_QuestEN[84759] = { title = "Ill-met in Starlight", description = "I used to practice what I would say when I saw my brother again. Then I stopped believing I would...\n\nHe's been away all this time, and now he comes to ask for heirlooms? I dug our mother's grave beside her favorite tree. Alone. He should have come back then, I don't have time to help him ease his conscience now.\n\nIf you two are so set on talking, at least have the sense not to do it in the open. Come to my camp--we'll speak there.", objectives = "" }
WordHunterWoW_QuestEN[84760] = { title = "A Friendly Warning", description = "Before the Devouring, the Sufaadi were priests. There were customs of courtesy and charity. Those were erased with the rest of K'aresh. If the Wastelanders think I won't retaliate, they'll never stop targeting me.\n\nI think you understand the value of a show of force. Kill their leaders--let it be a warning for the others.", objectives = "" }
WordHunterWoW_QuestEN[84761] = { title = "Toil and Trespass", description = "Fennad picked a poor time to ask for my help. I'm leaving as soon as I recover my supplies from the Sufaadi. \n\nI was passing through when they attacked, and they could have killed me if Ruya hadn't carried me off. I followed them back to Sufaad, but there are too many for me to deal with. \n\nIf you help me recover my supplies, I'll see what I can do to help Fennad.", objectives = "" }
WordHunterWoW_QuestEN[84762] = { title = "We Are Our Words", description = "I had a necklace that our mother beaded. The Sufaadi took it when they robbed me. Things from old K'aresh are rare. If the Sufaadi haven't traded it, it'll be with their other valuables.\n\nI was planning to leave it behind. Sentimentality isn't worth risking your life, but you kept your word--which is more than I can say for my brother. Help me recover the necklace and it's yours.", objectives = "" }
WordHunterWoW_QuestEN[84765] = { title = "Of Bonds and Boughs", description = "All that time in Tazavesh, all I could think about was coming home. Now it's only brought more grief. Even if the surveyor wasn't damaged, I still have nothing to trace back to our mother's grave.\n\n<Om'fennad glances around the cave.>\n\nSee these markings? This was a shrine to the Exchange. I guess it's a fitting place to finally say goodbye. Would you be willing to help one last time? Nothing dangerous--just light some incense.", objectives = "" }
WordHunterWoW_QuestEN[84767] = { title = "Charred Celebration Crate", description = "<The crate is charred from fire, but the insides might be salvageable. Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[84773] = { title = "Crystalized Celebration Crate", description = "<The crate is crystallized and can't be pried open easily. Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[84779] = { title = "Lorewalking: The Blade's Gambit", description = "Though now only a blade of little power, Xal'atath was not idle. In the aftermath of the Legion invasion, tensions between the Horde and the Alliance erupted into the Fourth War. \n\nXal'atath took advantage of the many forces at play in the war in a gambit to restore her power...", objectives = "" }
WordHunterWoW_QuestEN[84781] = { title = "Master of Secrets", description = "", objectives = "" }
WordHunterWoW_QuestEN[84782] = { title = "Lorewalking: The Blade's Past", description = "Many years ago, a stone tablet from Stormsong Valley made its way into my library. \n\nIt took years to break the cipher and translate the fragments of runes etched into it. \n\nI will tell you what we have pieced together. A tale of yet more treachery...", objectives = "" }
WordHunterWoW_QuestEN[84784] = { title = "Lorewalking: The Blade's Nemeses", description = "Lord N'Zoth calls now upon his brethren to aid in Xal'atath's defeat. You have been chosen to make the way for them to arrive.\n\nYou know what to do.", objectives = "" }
WordHunterWoW_QuestEN[84789] = { title = "Lorewalking: The Blade's Downfall", description = "They are ready. \n\nThe Lords hold Xal'atath within the keep. You are the pebble to trigger the avalanche of their power. To end Xal'atath. \n\nGo. Join them.", objectives = "" }
WordHunterWoW_QuestEN[84820] = { title = "By Oath and Blood", description = "After the Devouring, I didn't think I'd see Fennad again. At first, it was easier to stay angry at him for leaving than to grieve. Then it was easier to forget, to only focus on surviving the next day. Seeing him again brought everything back.\n\nOath-breaker... He had forsaken his oath to come home, but family is the first oath we're born to. What would it make me if I abandoned him now?\n\nHe's my brother--by oath and by blood. I won't leave him to the Sufaadi.", objectives = "" }
WordHunterWoW_QuestEN[84821] = { title = "Biological Quintainment", description = "Have earned spurs, now time use them!\n\nSlimes run off with joust dummies, but that just make for moving target. Better practice!\n\nMount noble mole steed by gate, get eye with lance, ride down slime.\n\nImportant skill for any knight, yes.", objectives = "" }
WordHunterWoW_QuestEN[84822] = { title = "To Iskaara", description = "Let's get these kids back to Iskaara, eh?\n\nI'll meet you there.", objectives = "" }
WordHunterWoW_QuestEN[84826] = { title = "Eco-Dome: Rhovan", description = "I will not make excuses for what we did. I will carry the responsibility of it for the rest of my existence. Alleria will come to understand why it was necessary. When she sees the power of the All-Devouring, she will understand.\n\nWe will need at least two more Reshii Ribbons to bring enough of a force to bear against Dimensius. My friend Om'bera is a holder of a ribbon. She works in Eco-Dome: Rhovan on the next island. Let us gather her to our cause.", objectives = "" }
WordHunterWoW_QuestEN[84827] = { title = "The Shattered Dome", description = "Eco-Dome: Rhovan was shattered by a falling chunk of void glass, destroying the structure and scattering its caretakers. They have returned to recover whatever equipment, flora, or fauna can be salvaged before the wastes claim them. \n\nSearch the ruins to find any clues of Overseer Om'bera's fate. We must have her Reshii Ribbon! Om'resh and I will search the impact crater.", objectives = "" }
WordHunterWoW_QuestEN[84831] = { title = "The Rhovan Infestation", description = "When the meteor struck, Om'bera and I tried to salvage what we could. Without the dome's shield, we were soon beset upon by scavengers of the Great Dark Beyond. We fled and were separated.\n\nSuch creatures are not of K'aresh, and hostile to the stable biomes we sought to achieve. We need to clear these invasive creatures to find our equipment, and Om'bera.", objectives = "" }
WordHunterWoW_QuestEN[84834] = { title = "Tempest Clefts", description = "The Wastelanders were once the oracles of the Worldsoul of K'aresh. They were so proud and strident about their oaths. Now they scavenge the ruins like animals. Even rats have their uses. \n\nGather void cleft essences for me. I have an idea of how we might sway the fallen oracles to our cause.", objectives = "" }
WordHunterWoW_QuestEN[84838] = { title = "Enemies of Enemies", description = "The Wastelanders have made camp in the ruins of old K'aresh. A sanctuary from the ravenous beasts of the Void that stalk the wastes of K'aresh. A bulwark against outsiders.\n\nIf a hostile entity were to enter their camp, you could defeat it--then they would respect you. Take the void energy you gathered into the ruined tower north of here. Be ready!", objectives = "" }
WordHunterWoW_QuestEN[84848] = { title = "Before the Void", description = "You've impressed these Wastelanders with your violent prowess, my champion. Well done. Now let me do my work.\n\nI know what these former oracles want. They dream of hearing the Song of K'aresh once more. I must make them believe it is possible, then pull on that string of desire. Soon we will have our army, and another Reshii Ribbon.\n\nFirst, let's return the Tabiqa ritual dagger.", objectives = "" }
WordHunterWoW_QuestEN[84855] = { title = "Dead Silence", description = "Dimensius's power is so great that even shattered, his aura radiates a power debilitating to mortal life. It is why the K'areshi were changed to beings of energy--it was the only way we could survive his presence.\n\nI had hoped my scouts could find a path that was safe for you and your compatriots to enter the manaforge. Raz'ida, Lo'shah, and Yanhal should have met us by now. Find them for me. Their information is vital to our defense against the All-Devouring.", objectives = "" }
WordHunterWoW_QuestEN[84856] = { title = "Where the Void Gathers", description = "With Locus-Walker's Reshii Ribbon, I can transmute your flesh to energy. It won't hurt much.\n\nYou will have the ability to travel within Dimensius's aura without being destroyed. There you can search for a path into the manaforge. You will travel in Untethered Space as a creature of energy, ignored by the Shadowguard. Their void beasts however... stay well away or be devoured. \n\nTalk to me when you are ready. Time is of the essence.", objectives = "" }
WordHunterWoW_QuestEN[84857] = { title = "Eco-Dome: Primus", description = "Xal'atath is correct. We need more than my one Reshii Ribbon to get a force to Dimensius. \n\nThere is an eco-dome south of here. The founder of the Trust is there, overseeing its operation. She acquired the domes from the Consortium. She claims they will be the key to restoring K'aresh. I am skeptical anything will be safe now that Dimensius stirs. \n\nShe was a member of the Ravel and possesses a Reshii Ribbon. Surely she would lend it to us.", objectives = "" }
WordHunterWoW_QuestEN[84858] = { title = "System Restart", description = "My Reshii Ribbon is all that is keeping this dome and its systems from collapsing.\n\nThis eco-dome took too much of my fortune to build just for the Shadowguard to destroy it. They have sabotaged many of our control consoles, risking a complete ecological collapse.\n\nFind Engineer Om'loof and help him restart our environmental support system while I monitor the rest of the facility.", objectives = "" }
WordHunterWoW_QuestEN[84859] = { title = "Damage Report 101", description = "Just like Engineer Om'loof, I have hired more well-regarded, highly trained, expensive management consultants from cartel Om. Two of them have not reported in. Are they dead, or just distracted again? \n\nFind botanist Om'nittar and shield technician Om'door. Get their damage reports. I need to know if the attack caused any lasting damage to my dome.", objectives = "" }
WordHunterWoW_QuestEN[84860] = { title = "Eco-Stabilizing", description = "The Shadowguard attack caused chaos and disarray in this dome. Several control consoles have powered down, and my consultants are stretched thin reviving their assigned biomes and systems.\n\nThis is where you come in, {name}. It's an easy, but critical job. Find the disabled consoles and make sure they restart.", objectives = "" }
WordHunterWoW_QuestEN[84861] = { title = "This Is Our Dome!", description = "We may have driven the saboteurs out of the dome and repaired its systems, but that doesn't mean the Shadowguard is done with my domes. They're still hiding at the perimeter, trying to find a way to harvest the vast amounts of expensive energy needed to power the eco-dome.\n\nI need you to fight them off. Then maybe this attack will truly end.", objectives = "" }
WordHunterWoW_QuestEN[84862] = { title = "Void Alliance", description = "We can't have you patrolling the perimeter of this dome, like the city watch fighting attackers in perpetuity. We need a permanent solution so we can continue with our noble quest.\n\nTake these crystals. They've been attuned to the eco-dome's defense magics. Just place them near strategic parts of the perimeter to strengthen the magical defenses.\n\nWhat? This time it's no trick. If this dome explodes, I'll never get to destroy Dimensius.", objectives = "" }
WordHunterWoW_QuestEN[84863] = { title = "Counter Measures", description = "I cannot relinquish my Reshii Ribbon just yet, {name}. Not while the Shadowguard assaults my eco-dome from their camp in Serrated Peaks. Take the fight to them! If you decimate their forces, they will stop this assault. \n\nBring Locus-Walker's apprentice, Alleria. She looks like she knows how to handle herself in a fight. She also keeps staring daggers at the Harbinger, and I don't have time to play peacemaker between those two.", objectives = "" }
WordHunterWoW_QuestEN[84864] = { title = "Her Dark Side", description = "An ethereal army runs on its energy siphons. Interrupt the flow of energy by destroying their siphon tower, and the army will pull back. It's one of their weaknesses as minions. Normally I wouldn't share the secrets of their defeat, but they betrayed me and will forever live with the consequences.\n\nThe siphon has a control console that can be overloaded to collapse the system. It will be shielded by a void barrier. Alleria can remove it for you.", objectives = "" }
WordHunterWoW_QuestEN[84865] = { title = "Divide and Conquer", description = "Of all the assets on the field of battle, the troops are the most expendable. I've sent enough to their destruction to know this as a fact. If we are to safeguard this dome for Ve'nari and get her Reshii Ribbon, we should destroy their cannons.\n\nThose cannons are easily worth the lives of all of their soldiers. Destroy them and their commanders will sound the retreat. Most field commanders would never admit this as it's bad for morale, but you seem like the type that can handle uncomfortable truths.", objectives = "" }
WordHunterWoW_QuestEN[84866] = { title = "To Purchase Safety", description = "I need to focus on the mission. Regardless of my doubts about our companions, the Shadowguard are a scourge. We should slay their Shadow-Captain so they cannot easily return to Eco-Dome: Primus. Ve'nari would lend her Reshii Ribbon to our cause, and we would discover if my trust in Locus-Walker was well placed.\n\nI will not let my doubts stay my bow on the battlefield, {name}. You can trust me to hunt these followers of Dimensius.", objectives = "" }
WordHunterWoW_QuestEN[84867] = { title = "Stalking Stalkers", description = "I've planted the seed, yet Soul-Scribe still hesitates. Her daughter Narathe is more receptive. She might be able to give us the nudge that's needed to win the Wastelanders over. Daughters are useful.\n\nGo with Narathe. Win over their tribe. I will stay here and continue to work on Soul-Scribe's will.", objectives = "" }
WordHunterWoW_QuestEN[84868] = { title = "A Whiff of Help", description = "You seem quite equipped for solving secrets now! As much as I expect Maru would want to come with you, she's far too young.\n\nFortunately, we Tuskarr have an incense that lets our souls communicate across long distances.\n\nI keep a stock of it on me if you need. As a friend of Maru, I will only charge you for the cost of materials.", objectives = "" }
WordHunterWoW_QuestEN[84869] = { title = "Hunting on Glass", description = "Violent scavengers of the Void have been drawn to Dimensius's aura to feast upon the scraps he will leave behind. This presents a problem for our Wastelander friends. Scavenging is their job.\n\nThey could handle these beasts--I would not be seeking to ally with them if they couldn't. But why not give them a gift, and show them you are their equal--no, their superior in combat?", objectives = "" }
WordHunterWoW_QuestEN[84876] = { title = "The Oasis", description = "Soul-Scribe would fight for us, even die for our cause. Yet she still denies us her Reshii Ribbon. She sees it as a tool of the Ravel, and her oaths are getting in the way of our mission.\n\nIf she could feel the presence of the Worldsoul K'aresh once again, she would give anything to protect him--even the ribbon. The Oasis is the Trust's eco-dome that has a stable biome. The perfect place to commune with a Worldsoul, if one still exists.", objectives = "" }
WordHunterWoW_QuestEN[84879] = { title = "Restoring Hope", description = "This dome is a reasonable facsimile of K'aresh. We will find no better place for Soul-Scribe to hear the Worldsoul's song. \n\nAnd yet, as Dimensius grows in power, even the Oasis succumbs to the Void. I can feel the rifts tearing open. Their energies will disrupt this delicate ritual. Unfortunately they'll need to be closed so Soul-Scribe can be convinced.", objectives = "" }
WordHunterWoW_QuestEN[84882] = { title = "Deck Dismay", description = "Gather up the cards that got scattered around the area and I will be forever grateful!", objectives = "" }
WordHunterWoW_QuestEN[84883] = { title = "K'aresh That Was", description = "The Tabiqa has not been attempted for thousands of years. It was clear that the Devouring War destroyed K'aresh.\n\nAnd yet, looking at this dome... they have recreated so much that I thought lost forever--fresh water, clean air, even the zaranit flowers I thought extinct. Does the Harbinger speak the truth?\n\nNo. I didn't break my oath and abandon the Worldsoul. K'aresh is gone.", objectives = "" }
WordHunterWoW_QuestEN[84885] = { title = "Working for G.E.T.A.", description = "Attention: Protect the Citizens of Undermine AND get paid!\n\nProfit-seeking bounty hunters encouraged to check in at the local G.E.T.A. office for more information.", objectives = "" }
WordHunterWoW_QuestEN[84891] = { title = "G.E.T.A. The Radioactive Rat", description = "We got a report here of some big, radioactive rat that was chased into a nearby sewer. Not only is it highly aggressive, it's terrible for the environment.\n\nHey, don't look at me like that. Us Underminers care about that stuff even if the big cartels don't.\n\nI put the location of the sewer entrance on your map. Hopefully, one of these lunks will get off their butts and join you there.", objectives = "" }
WordHunterWoW_QuestEN[84892] = { title = "G.E.T.A. The Crocodilian", description = "Did you know that crocodiles can grow indefinitely?\n\nWell, the owner of this crocodile didn't. And when it got too big, it was released. Normally these crocodiles make their way out of the Undermine. But this one decided it liked the taste of goblins and stayed.\n\nIf you're up for it, the people of Undermine could use someone brave to face it. Are you game?", objectives = "" }
WordHunterWoW_QuestEN[84893] = { title = "G.E.T.A. The Captain", description = "This is a unique one. \n\nSome cave skippers got into the Undermine sewers and are starting to populate, causing all sorts of problems. It looks like an especially big one is organizing them somehow.\n\nWe've taken to calling him \"the Captain.\"\n\nMake sure his reign of finned, eye-bulging terror ends today.", objectives = "" }
WordHunterWoW_QuestEN[84894] = { title = "G.E.T.A. 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[84896] = { title = "The Next Dimension", description = "By the Songs of K'aresh, I will join you to face the Shadowguard and Dimensius in battle. Let those that would prey on Untamed K'aresh fear his followers!\n\nMy scouts have tracked your comrades setting a foothold in Shadowguard territory. They will need our assistance. \n\nK'aresh lives! Our cause is just! Our oaths are unbroken!", objectives = "" }
WordHunterWoW_QuestEN[84897] = { title = "The Calm Before We Storm", description = "Narathe is right. We are fortunate that void elves have experience battling the Shadowguard. The wastes of K'aresh are merciless, and the battle to come will be as well. I hope they are prepared for a brutal fight. These will not be the scattered scouts they are used to fighting on Telogrus.\n\nYou should ensure they are ready for the battle to come.", objectives = "" }
WordHunterWoW_QuestEN[84898] = { title = "The Sands of K'aresh", description = "My people have fought across every inch of the ruins of our world. We gave our oath to King Salhadaar and he rewarded us by sending the Shadowguard to hunt us down.\n\nSalhadaar is long dead, but we knew the Shadowguard would return. In the long years that followed, we secreted caches of weapons so we would always be able to raise a blade in defiance.", objectives = "" }
WordHunterWoW_QuestEN[84899] = { title = "Shadowguard Diffusion", description = "With or without Xal'atath, the Shadowguard have long been a thorn in my side. It would be wise to take out as many as we can on this rock. I still do not trust her, but we must focus on the enemy we can defeat right now.\n\nDo not relent, {name}. If you see any Shadowguard, cut them down. A battle against them today saves us a battle against them tomorrow.", objectives = "" }
WordHunterWoW_QuestEN[84900] = { title = "Like a Knife Through Aether", description = "Very good, my champion. You are a swift and sharp blade of destruction.\n\nWe will put all that power to use now. We will slaughter the Shadowguard that seek to raise Dimensius, and the machines created to feed his insatiable hunger. \n\nThe Shadowguard must have a Reshii Ribbon among their spoils. As we destroy their garrisons, look for this final ribbon. It is our way forward to kill a Void Lord.", objectives = "" }
WordHunterWoW_QuestEN[84901] = { title = "[DNT] CH04Q05p", description = "Priest unique quest, do the same objective but mind control an enemy who will help you kill them first.", objectives = "" }
WordHunterWoW_QuestEN[84902] = { title = "Adverse Instantiation", description = "Turning into beings of energy was a choice we made when we had no other option. In the time since then, we have become reliant on consuming energy to survive. \n\nThe Shadowguard are feeding that power to Dimensius. His hunger is infinite, and he will drain the energy from K'aresh to fuel his re-emergence. We must destroy this machinery that feeds him, {name}.", objectives = "" }
WordHunterWoW_QuestEN[84903] = { title = "Until the Sands Bleed Void", description = "I have fought Shadowguard on Eredath, Telogrus, and now on K'aresh. They are a thorn that should be plucked from the cosmos.\n\nThat they should follow the very monster that threatened their world proves they are a scourge. Though, perhaps I am no better, fighting alongside Xal'atath. \n\nI will grapple with that contradiction later. For now, I intend for us to put an end to them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[84904] = { title = "And We Will Answer", description = "This is unthinkable. Heretical!\n\nThe Shadowguard have captured my warriors and are converting them into new troops for Dimensius--forcing an oath to serve the All-Devouring as the Void fills their being.\n\nFree them, {name}. We cannot let this last any longer. I will send Narathe to aid you in this fight. She knows how to untether the souls of oath-breakers.", objectives = "" }
WordHunterWoW_QuestEN[84905] = { title = "To Walk Among Shadow", description = "We must continue disabling or destroying these buildings. I am loathe to destroy the technology of my people, but when used for such dire purpose, there is no choice!\n\nFrom here on out, hold nothing back. Let us raze the works of the Shadowguard.", objectives = "" }
WordHunterWoW_QuestEN[84906] = { title = "Nexus Regicide", description = "Now is the time, {name}.\n\nWe must not hesitate. They will send their strongest to defend this last manaforge. We will find Nexus-Prince Azir there and we will end him before we take this battle to Dimensius. Xal'atath or no Xal'atath, we have what we need to do this. Just one final kill. \n\nLet us not dally. Make haste.", objectives = "" }
WordHunterWoW_QuestEN[84908] = { title = "Stormrider's Honors", description = "<A golden missive finds its way to you.>\n\nChampion, though you are no Stormrider, you may yet be worthy of the Stormrider's armor.\n\nFind Stormrider Bruelda if you wish to claim this honor.", objectives = "" }
WordHunterWoW_QuestEN[84909] = { title = "Ghostly Celebration Crate", description = "<The crate emits a ghostly glow, and you can't help but feel the presence of mysterious spirits. Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[84910] = { title = "The Tabiqa", description = "My followers long for the days when they were oracles. They yearn to hear the Song of K'aresh. I am a realist. The evil of the Ravel, of Dimensius--they have destroyed the beauty that was our Worldsoul.\n\nBut you have gathered the items for the Tabiqa. So I will attempt it. When I hear the void of K'aresh's absence, there will be consequences.", objectives = "" }
WordHunterWoW_QuestEN[84912] = { title = "The Show Must Go On", description = "Thank you for coming! We've had a bit of a mishap with the script and various stage props.\n\nThey've all gone missing! It seems as though a prankster has decided to make a mockery of our productions and scattered several needed items throughout the area.\n\nAt least the prankster was somewhat considerate and left us some clues as to where we can find the missing items. Do you think you can solve the riddles?\n\nAnd please, do not carry any open flames or shine any bright lights while in our theater.", objectives = "" }
WordHunterWoW_QuestEN[84915] = { title = "Clearing the Dunes", description = "The deserts here were never safe, but there was still beauty--birdsong, herds of animals, and the desert would bloom from horizon to horizon after a storm.\n\nNow it's a wasteland. I barely took two steps off the docks before being chased by some monster. I need to get out there. If you could cull the worst of those creatures, I'd feel much safer.", objectives = "" }
WordHunterWoW_QuestEN[84923] = { title = "A Bird's Tale", description = "I've heard that Reshad has a new story to tell involving his bird companion, Percy. Speak with him if you would like to discover the tale.", objectives = "" }
WordHunterWoW_QuestEN[84924] = { title = "A Bird's Tail", description = "I've told many tales in my days, but my companion Percy has a tale of his own to tell. Would you care to learn about it?\n\nI will give you a clue on where to start. From there, you must find the clues that Percy has left behind to discover his story.\n\nYou can have this feather that Percy left behind as well. Look closely and you may find more clues. Perhaps a bird of your own may help you on your journey.", objectives = "" }
WordHunterWoW_QuestEN[84925] = { title = "Rallying All Rapscallions!", description = "Come one, come all, straight to Dornogal!\n\nIn addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds!\n\nPresent this brochure to Hotharn to receive a few of these, on us!\n\n- Aisha", objectives = "" }
WordHunterWoW_QuestEN[84932] = { title = "A Legacy of Destruction", description = "Adventurer! A dragon whelpling recently showed up in the pet playground and has been causing all sorts of chaos.\n\nCould you go talk to him and see if you can sort out the issue?", objectives = "" }
WordHunterWoW_QuestEN[84933] = { title = "From Ashes to Wisdom", description = "I will become the great and powerful Deathwing! Cower before my strength!\n\nYou there! Do you wish to join me, the next Deathwing, on an epic adventure?", objectives = "" }
WordHunterWoW_QuestEN[84934] = { title = "A Dark Descent", description = "I realize what I'm proposing is just this side of mad. The realm of death isn't the sort of place we're supposed to be able to just visit.\n\nBut these visions that are plaguing my family... Mother's led to the destruction of Dalaran. What if Silvermoon is next? I can't afford to risk any complacency. And if there's anyone, living or otherwise, who might be able to speak to Silvermoon's defense...\n\nWell. Here goes nothing. See you on the other side?", objectives = "" }
WordHunterWoW_QuestEN[84935] = { title = "Excising the Incursion", description = "The Devouring Host must have somehow followed us here.\n\nI don't know what they could want with a place like this, but I can't imagine the Void is suddenly infused with benevolent purpose. We can't allow this incursion to get out of hand.\n\nSlay as many of them as you can manage. Enough to thin their numbers, at least.", objectives = "" }
WordHunterWoW_QuestEN[84936] = { title = "To Cleanse Shadow's Stain", description = "These monstrosities certainly wasted no time once they arrived. They are snatching up souls left and right and drowning them in void magics.\n\nTake my holy symbol. It should be potent enough to drive away the shadows that cling to any lingering souls.", objectives = "" }
WordHunterWoW_QuestEN[84937] = { title = "Distant Echoes", description = "Can you hear it? There's a strange sound echoing in the distance. Given where we are, I would assume it's a trick. Or worse, a trap. But it feels...\n\nI don't know how to describe it, but I feel calmer for hearing it. Like I'm in control.\n\nThis is going to sound mad, but I think--I think we should follow it. I don't know where it could be coming from, but my instincts are telling me to trust it. We should follow its trail.", objectives = "" }
WordHunterWoW_QuestEN[84938] = { title = "Chaos Control", description = "These are no mere embodiments of Void. They move with precision and purpose. They have taken up a defensive position within the Tremaculum. No doubt they intend to expand their presence and shore up their defenses, now that they have a foothold.\n\nAll the better. It means they will all be gathered in one place.\n\nBreak their ranks. Show no mercy.", objectives = "" }
WordHunterWoW_QuestEN[84939] = { title = "Mad Space", description = "It doesn't matter how many of these void monstrosities we kill. We have to deal with the source, or they'll just keep coming.\n\nTraveling across the rift is not an easy feat in the best of times. If we can find the places where they've been able to tear through and close them, then we should be able to cut off their reinforcements.\n\nLead the way. I'll be at your back the entire time.", objectives = "" }
WordHunterWoW_QuestEN[84940] = { title = "Friendly Competition", description = "See, Ricket offered to dig it up, but the Arathi expedition lady didn't seem too keen on that.\n\nGave 'er an earful. Could hear it from the airship. Yeesh.\n\nBargus, the earthen \"ordinant\"--whatever that means-- proposed scanning the crystal to help us \"understand it better.\"\n\nI don't need to understand it. All I need's my cut. But I'm fine layin' low and doin' what they want. \n\nGo talk to Bargus at the earthen camp. See how they're comin' along an' if we can help.", objectives = "" }
WordHunterWoW_QuestEN[84941] = { title = "Cave Barging", description = "Unless it is a convergence of coincidence, whoever these large outlanders are, they appear to also be interested in the crystal's signal--and the location of its origin.\n\nWe earthen do not often take stock in coincidences.\n\nEngage your defense protocols, {name}. \n\nThese outlanders are not hospitable like your people.", objectives = "" }
WordHunterWoW_QuestEN[84942] = { title = "The Final Hazard", description = "With their lesser rifts closed, the Devouring Host will be hard-pressed to muster any reinforcements. But if we don't deal with their leader, then they'll just open more.\n\nAbove, in the parapets... There's no mistaking it. I can feel a force of Void drawing everything toward it, even all the way from down here. That's where we'll find our mark, without a doubt.", objectives = "" }
WordHunterWoW_QuestEN[84943] = { title = "The Long Vigil", description = "If you and Arator desire something of me, it will have to wait. There are souls here that require my attention, assuming your bumbling hasn't driven them off.\n\nI've managed to track four souls that fell into the Maw without proper judgment. Correct your mistakes and help me to retrieve them, and perhaps I will find time for a chat.", objectives = "" }
WordHunterWoW_QuestEN[84944] = { title = "Preludes and Preparations", description = "As you are no doubt aware, ferrying souls beyond the bounds of the Maw is no easy task. This is not a place from whence souls are meant to ascend.\n\nOur resources are limited, but I have devised a way to ensure the relative safety of the souls I retrieve--though I will require materials. Fetch for me the reeds that grow in the silt of the Gorgoa River, soulthread from the cloaks of the wandering specters, the hide of a soul-eater... Ah. And mawrat teeth.\n\nWe mustn't forget the mawrat teeth.", objectives = "" }
WordHunterWoW_QuestEN[84945] = { title = "Repent of the Highborne", description = "The reagents are gathered, and the lingering souls have been put at ease for the moment.\n\nWe do not have long. Stand back, while I send them to where they are meant to dwell.", objectives = "" }
WordHunterWoW_QuestEN[84946] = { title = "Returning to Life", description = "When I decided to come here, I have to admit that I wasn't sure what I would find. There's no disputing the terrible things that Sylvanas has done, and it's a burden that she will have to bear for the rest of her days.\n\nBut seeing her, like this...\n\nCome. We've been here too long as it is. The weight of this place is starting to get to me.", objectives = "" }
WordHunterWoW_QuestEN[84947] = { title = "Determination", description = "Hold a moment.\n\nArator will be fine for a few moments longer. Let him travel alone for a moment.\n\nI wish to speak to you. Privately.", objectives = "" }
WordHunterWoW_QuestEN[84949] = { title = "The Eleventh Hour", description = "It's high time we got back to Azeroth. I think we've done all we can do when it comes to mustering the Windrunners for whatever is to come.", objectives = "" }
WordHunterWoW_QuestEN[84956] = { title = "A Shadowy Invitation", description = "{name},\n\nI've received word from my mentor, Locus-Walker. He warns of a Shadowguard plot that requires our aid. I wonder if he has finally tracked down Xal'atath.\n\nCome to the Foundation Hall in Dornogal. We must speak immediately.", objectives = "" }
WordHunterWoW_QuestEN[84957] = { title = "Return to the Veiled Market", description = "I have been retained by the K'aresh Trust--a coalition of both broker and ethereal cartels who seek to reclaim K'aresh. The Trust is in desperate need of one of your skills, {name}.\n\nThe Shadowguard assaults our city and threatens the work of the eco-dome project.\n\nPlease accompany me.", objectives = "" }
WordHunterWoW_QuestEN[84958] = { title = "Beasts Unbound", description = "I am Ta'ka, supplier of rare creatures destined to repopulate my homeland.\n\nAt least, I was until some of them escaped their translocation cages! This cannot stand!\n\nThese creatures are vital. If you could assist me with capturing them, I'd be quite appreciative.\n\nEngage them in combat and subdue them. The capture device I've provided will automatically translocate them back to my care once they are on the verge of defeat.", objectives = "" }
WordHunterWoW_QuestEN[84959] = { title = "Lost Lines of Defense", description = "This is not a good day! Not at all. My whole shipment of barrier projectors was ransacked! Most of them are gone, and it seems whatever the culprits didn't take, they destroyed.\n\nThese barrier projectors are essential for securing the wild places on K'aresh, and even the city of Tazavesh. Our efforts are in jeopardy!\n\nPlease, if you can find any of my shipments it would help us get our efforts back on track.", objectives = "" }
WordHunterWoW_QuestEN[84960] = { title = "The Darkness Among Us", description = "Alleria, {name}... Have you sensed it? The Void lingers in all of this. Whoever is pulling the strings is cloaked in shadow, hiding from us.\n\nCome, let's seek them out and drag them into the light before they strike.", objectives = "" }
WordHunterWoW_QuestEN[84961] = { title = "Barriers to Entry", description = "Those barrier projectors we recovered? We need them now. Place them at key points to reinforce the city shield and block more portals from forming.\n\nMove swiftly, {name}. This may be our only chance to stop the Shadowguard from flooding in.", objectives = "" }
WordHunterWoW_QuestEN[84963] = { title = "Sealing the Shadows", description = "No, no, no! The Shadowguard are ransacking the city and our defenses are crumbling! We even invested in new security golems after the city was last breached, but we haven't had time to activate them.\n\nWait... I have an idea. The Shadowguard--some of them must have looted entropic cores that we can use to activate the golems. \n\nPlease, you must take them down and retrieve those cores. We need to get those golems online to protect our investments! Uh, I mean, our city!", objectives = "" }
WordHunterWoW_QuestEN[84964] = { title = "Heroes Among Shadow", description = "{name}! These people may not be my own, but we cannot stand by while the Shadowguard cut them down. You and I, we can make a difference! \n\nWe need to get out there, rescue the civilians, and bring them to safety. The city may be in chaos, but we can still be the shield they need.", objectives = "" }
WordHunterWoW_QuestEN[84965] = { title = "Core Contributions", description = "The entropic cores we collected will be crucial in our defense.\n\nUse the entropic cores to activate the market guardians scattered around the city. Once reactivated, these golems will join our fight and help us push back the invaders.\n\nTime is of the essence, {name}. The fate of Tazavesh rests in your hands.", objectives = "" }
WordHunterWoW_QuestEN[84967] = { title = "The Shadowguard Shattered", description = "The commander of the Shadowguard, Shadowlord Al'zar, has assaulted this shelter of the Trust. I am preoccupied with assisting these injured brokers. I dare not leave, or their soul's energy will pour out.\n\nI must depend on you, {name}. Venture forth and eliminate Shadowlord Al'zar. His demise will cripple the Shadowguard's assault on Tazavesh. \n\nThe fate of the city rests on your shoulders.", objectives = "" }
WordHunterWoW_QuestEN[84972] = { title = "Chipping the Void", description = "Greetings. I am Driruj. I think you could help with a project of mine. \n\nThe nearby expanse of purple-hued crystal is ripe with potential. The void-infused glass could have many uses, from being a spell reagent to being melted down for crafts. I can't get near it myself, but someone like you will have no trouble at all!\n\nBring me back some samples of the void glass so I can assess their worth to future buyers.", objectives = "" }
WordHunterWoW_QuestEN[84973] = { title = "Of Motes and Husks", description = "Regrettably, the void glass was too unstable. However, I have another idea. I believe I can stabilize the glass, but only at the moment of its creation. First, I need motes from the wyrms outside the eco-dome to power my device.\n\nWhile you're out there, hunt down some of those krolusks as well. Their husks can be ground down to make a pleasing beverage for which the folk in Shattrath will pay the highest of prices.", objectives = "" }
WordHunterWoW_QuestEN[84974] = { title = "Shards of Hope", description = "I still believe void-infused glass is my ticket out of here.\n\nThe problem lies in the creation process itself. The motes you brought me can help stabilize the glass with the help of void energy. Lucky for us, there are numerous void surges on the edges of the glass crevasse.\n\nI have charged a device with the motes. All you need to do is channel void energy through it! Stand where a surge is about to happen and then collect the glass that's formed. Easy! Oh, it might tingle a bit...", objectives = "" }
WordHunterWoW_QuestEN[84985] = { title = "Not Ready on Set", description = "Oh {name}, I am glad to see you again.\n\nMy superiors have informed me that I'm responsible not only for the guests here, but for everyone putting on celebrations!\n\nNow I'm hearing that Dapperdew in Ardenweald is trying to put on a new play and running into problems.\n\nWould you mind checking in on the situation? I can hardly manage this celebration, let alone whatever is happening in the Shadowlands.", objectives = "" }
WordHunterWoW_QuestEN[84996] = { title = "Vereesa's Tale", description = "We came here so Vereesa could get closer to the source of her visions. Unfortunately, it has only made them stronger, not clearer.\n\nBut this is her story. She should be the one to tell it.", objectives = "" }
WordHunterWoW_QuestEN[84997] = { title = "What Might Come", description = "Thank you for coming with us, {name}. I'm long overdue in saying goodbye to my dear Rhonin.", objectives = "" }
WordHunterWoW_QuestEN[84998] = { title = "Bringer of the Void", description = "Go with... Arator. Slay... their leader.", objectives = "" }
WordHunterWoW_QuestEN[85001] = { title = "Blessings Be Upon You", description = "These innocents were simply trying to clean up the ruins, but the cultists are slaughtering them. We must come to their aid!\n\nChampion, I am certain that you and I can do this if we work together.", objectives = "" }
WordHunterWoW_QuestEN[85002] = { title = "Off to Tazavesh", description = "It's imperative we seek my mother's counsel. But before we can do that, we'll have to find her.\n\nLast I heard, she was out hunting in the Great Dark Beyond on a world known as K'aresh.\n\nLucky for us, I thought ahead and asked Khadgar for a portal scroll to go directly there. I'll meet you on the other side.", objectives = "" }
WordHunterWoW_QuestEN[85003] = { title = "Restoring Operational Efficiency", description = "Locus-Walker was brought into the Trust to handle such a violent crisis of the Void. He says you are some kind of hero or champion. Good. We are in need of such a thing.\n\nTazavesh is under threat from the Void. The Shadowguard! They threaten the work of the Trust and my reputation as an administrator.", objectives = "" }
WordHunterWoW_QuestEN[85005] = { title = "A Radiant Call", description = "I have an urgent missive for {name} from Mylton Wyldbraun, second in command of the Flame's Radiance!\n\nHallowfall requires what strength we can muster and the Flame's Radiance seeks volunteers to join the fight against the remaining Sureki forces.\n\nPlease report to Wyldbraun without delay.", objectives = "" }
WordHunterWoW_QuestEN[85006] = { title = "Those We Have Lost", description = "Ah, traveler! This was one of the first locations to show a response to our attempts to rejuvenate the land. We're actively studying why it happened at this location in particular.\n\nI have another experiment I wish to run, but I need some extra sources of power. The souls that litter the dunes are unfortunately lost, but we may let them serve one last time by using their energy.", objectives = "" }
WordHunterWoW_QuestEN[85007] = { title = "Extended Reach", description = "I'm very curious on why the influence of this restoration stopped where it did, as are my fellow colleagues. We set up some devices at the edge of the dunes to track the fluctuation in various energy types.\n\nThey have probably sat out there long enough for an initial reading. Could you go gather that info for me?", objectives = "" }
WordHunterWoW_QuestEN[85008] = { title = "Machinations of Memory", description = "Well, the readings aren't anything to be concerned about...\n\nSo we'll move on to the next step of my experiment. This console here is the central piece of our system to rejuvenate the area. I'm hoping that if we hook it up to a significant charge, it may stabilize the area even more. Could you help me set up the energy containers as I adjust the machine?", objectives = "" }
WordHunterWoW_QuestEN[85009] = { title = "Those We Have Yet to Save", description = "The fauna here seem to be the same in shape as what would have been found nearby when K'aresh was still intact, but they are acting rather oddly for their species.\n\nI wonder if we could give them one last push and fully bring them into being. Take the last of the energy. I have a device that should let you channel it into them.", objectives = "" }
WordHunterWoW_QuestEN[85011] = { title = "Where in K'aresh is Alleria Windrunner?", description = "While you were on your way, I took the liberty to ask around. These brokers seem friendly enough, but be warned... part of the city is still under attack by a group of ethereals known as the Shadowguard.\n\nI managed to get a lead on a few traders who might have crossed paths with my mother recently.\n\nWe should go before her trail runs cold.", objectives = "" }
WordHunterWoW_QuestEN[85017] = { title = "Tracking Quest to Send Mailer [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[85018] = { title = "Packets of Promises", description = "I will not wait a moment longer. I have arranged for transport outside of the dome, and it will be arriving soon. \n\nWill you meet me outside? I have one last thing I would ask of you.", objectives = "" }
WordHunterWoW_QuestEN[85019] = { title = "An Outcast's Request", description = "I felt it. Something happened in that dome. Something--no... someone...\n\nMy friend, I do not know your name or where you came from, but this is it! It has to be!\n\nThe ruined town of Sufaad to the southeast of here was where I resided as a Wastelander. Please go there and bring back my scepter, prayer book, and ceremonial bowl. There was no time to pack. I just ran, so the items could be anywhere within the town.", objectives = "" }
WordHunterWoW_QuestEN[85020] = { title = "The Blood of K'aresh", description = "In the old days, we used certain deep-mined salts in cleansing processes and rituals. As you can see around you, mining is no longer valid, as these fragile rocks are hanging on to each other.\n\nOn the day of the Devouring of K'aresh, a never-before-seen mineral surfaced. The Blood of K'aresh is a blue mineral with some deposits to the west of here. Even though K'aresh is dying, I should follow the old traditions to the end.\n\nPlease collect deposits from sand striders or veins and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[85021] = { title = "Cleansing the Void", description = "Now that you have brought me all that I need, the ritual of return can begin.\n\nYou see, stranger, the items you recovered were stowed in my hovel for over a hundred thousand years. The Void that surrounds us leaves its mark on everything it touches.\n\nWhile grinding the mineral removed the impurities of the Void, I still need to cleanse myself and the items. Please help me with the ritual. I do not foresee any distractions or issues. We are very close now.", objectives = "" }
WordHunterWoW_QuestEN[85022] = { title = "Priest of the Old Ways", description = "{name}, I suspect that a living manifestation of the Void came out of myself and the items. I cannot, with good conscience, take on the mantle of a priest of the old ways while these manifestations are out there.\n\nI have a final request for you.\n\nGo find these creatures and slay them. Then, I will be able to reassume the mantle of priest.", objectives = "" }
WordHunterWoW_QuestEN[85024] = { title = "Toy Trouble", description = "Adventurer, Maru is once again in need of your aid.\n\nShe has an urgent matter that she would like to discuss with you.", objectives = "" }
WordHunterWoW_QuestEN[85025] = { title = "Operation Toy Rescue", description = "A sneaky thief has taken some of my friends' toys!\n\nYou're a good sleufer now, right? Can you help my friend Yennu find his stolen toy? You'll find him on da Dragon Isles.", objectives = "" }
WordHunterWoW_QuestEN[85026] = { title = "Where Legends are Made", description = "There's so much to catch you up on {name}! \n\nWhere do you want to start?", objectives = "" }
WordHunterWoW_QuestEN[85027] = { title = "Lorewalking: The Protectorate", description = "I have long been curious about the ethereals, who first came to Pandaria when the Mists parted. A mysterious group, they are reticent to speak of their history... but I am perhaps more persistent than most in my inquiries.\n\nSo! Who are these strangers? What do we know of their history? We must piece it together, it seems. \n\nBut our tale begins in Outland, where a hero joined a group of ethereals in Netherstorm to aid them with their cause.", objectives = "" }
WordHunterWoW_QuestEN[85028] = { title = "Lorewalking: The Brokers", description = "The ethereals are most fascinating indeed, but in my studies I have encountered another race of creatures who share many similarities with the ethereals. I feel we should speak of them as well--the brokers.\n\nThey share a nomadic nature, a desire to collect rare and unusual antiquities, and a penchant for trade.\n\nYet the brokers do not exist on Azeroth. Instead, they dwell in the Shadowlands... the land of death.", objectives = "" }
WordHunterWoW_QuestEN[85029] = { title = "Lorewalking: Locus-Walker", description = "While the Protectorate of Outland may have stopped Dimensius and Salhadaar, the Ethereum remained. And as Salhadaar had wished, they chose to embrace the Void. \n\nNot just embrace it--become it. It twisted them into shadows of themselves, consumed with the pursuit of power.\n\nBut there was one ethereal, Locus-Walker, that sought to harness the Void for more altruistic purposes. His history is entwined with an elf from our world--Alleria Windrunner.", objectives = "" }
WordHunterWoW_QuestEN[85032] = { title = "What Is Left of Home", description = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath. I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal.\n\nWe can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", objectives = "" }
WordHunterWoW_QuestEN[85035] = { title = "Locus-Walker, Telogrus Ranger", description = "I apologize for interrupting your conversation, mortal. But it was your discussion that drew Ve'nari's attention. She hears much, after all--especially when her name is involved. \n\nI have been sent with an object for you to deliver to Locus-Walker. He is an ethereal that dwells within Telogrus Rift. I believe the \"void elves\" of your world also reside there.\n\nThere is no need to travel. I will provide a portal to where you must go. Will you assist her in this task?", objectives = "" }
WordHunterWoW_QuestEN[85036] = { title = "Veni Vidi Ve'nari", description = "A broker sent you with this device? And they were sent to you by Ve'nari?\n\nThis does not bode well.", objectives = "" }
WordHunterWoW_QuestEN[85037] = { title = "That's a Wrap", description = "The possibilities have begun to narrow. We are on the cusp of victory. Are you ready, my champion, to fulfill your oath against Dimensius?\n\n<Xal'atath chuckles.>\n\nVery well. I have some promises of my own to keep. Let us formalize our defense against Dimensius by the platform toward the manaforge.", objectives = "" }
WordHunterWoW_QuestEN[85039] = { title = "Compromised Containment", description = "Somehow, an artifact in the Menagerie has broken open, unleashing a swarm of furious arcane creatures. They're wreaking havoc, and havoc is bad for the project. I need someone capable of getting this situation under control with no questions asked.\n\nIf you can get down there, clear your way through the creatures, and seal that artifact... I'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[85042] = { title = "The Final Toy", description = "Maru discovered that one of her toys is now missing!\n\nCould this be related to the other missing toys that you previously helped her friends with?", objectives = "" }
WordHunterWoW_QuestEN[85043] = { title = "The Toy Thief", description = "My toy! It's been stolen!\n\nWe have to figure out who da culprit is before they take more toys!", objectives = "" }
WordHunterWoW_QuestEN[85044] = { title = "DEPRECATED", description = "", objectives = "" }
WordHunterWoW_QuestEN[85047] = { title = "A Pirate Predicament", description = "I was recently made aware of a small group of Booty Bay Buccaneers who have landed and set up camp just outside the celebration area to the north.\n\nPirates aren't inherently a problem, per se, but they do introduce an element of chaotic unpredictability. I know you're busy, but would you mind checking on them to see if they need any assistance?", objectives = "" }
WordHunterWoW_QuestEN[85051] = { title = "Beach Comber", description = "There's a peculiar mechanical gnome scouring the beach nearby for valuable scrap metals. I am concerned for his safety but also intrigued. I just wonder what he's trying to find!\n\nMaybe he would be willing to share anything he finds in exchange for your assistance...\n\nCould you aid him in recovering any valuable items?", objectives = "" }
WordHunterWoW_QuestEN[85052] = { title = "A Lucrative Opportunity", description = "Most fortuitous greetings, offworlder!\n\nI have been stuck for an eon at this post checking manifests one after another. This is not real trade. Real trade is done on the streets of Tazavesh!\n\nIt just so happens that a contact of mine from your world was unloading waste cargo. I bought the whole supply. Expired storage contracts of some sort. However, I know better than to be trading without a permit.\n\nIt would bring good fortune to my endeavor to have your help with this. Can I count on you, {race}?", objectives = "" }
WordHunterWoW_QuestEN[85053] = { title = "Obtaining Permits", description = "There is a difference between securing a permit and securing permission to sell in Tazavesh.\n\nXy'vez is a licensed dealer. He can buy and sell as he pleases in accordance with the authorities. However, I am glad he knows his place. If you are on my streets, you need my permission.\n\nNot everyone knows this. Cartel Ba likes to test the waters. I'll award your permission if you teach them a lesson.", objectives = "" }
WordHunterWoW_QuestEN[85054] = { title = "Articles of Acquisition", description = "Take this ledger to Xy'vez. Let him know I expect dinars upfront and on time. There are to be no discrepencies between my records and his, do you understand?\n\nYou may head to the market to inform him. Knowing traders like him, he'll have already found a spot to set up shop.\n\nThis venture has my blessing. Don't let it become unprofitable or we'll be seeing each other again, offworlder.", objectives = "" }
WordHunterWoW_QuestEN[85055] = { title = "Expired Goods", description = "Now then, on to business. I hear tale that your world is full of heroes on adventure. And where there's adventurers, there's need for storing their treasures. Always.\n\nThus, you have turned to our kin to keep them safely deposited between realms. Yet not one of you read the contract. We have since ceased such services and returned goods to their owners. \n\nYou and I, {name}, are selling opportunities to purchase what remains. Blind of course. Help me prepare.", objectives = "" }
WordHunterWoW_QuestEN[85059] = { title = "A Piece of the Action", description = "Game on table look like fun. But Skaggit no want Jack to play. Maybe you can?\n\nSneak in and put a bet down. We see who wins!", objectives = "" }
WordHunterWoW_QuestEN[85060] = { title = "Pirate Foods and Superstitions", description = "Our trusty cook, Cooktholomew, was lost at sea. Quite tragic that was, but now all the more tragic for us here! We don't dare set sail again without the lucky feast ol' Cooktholomew would prepare for us before each voyage.\n\nWe've tried to make out his scribbles, but alas, we only managed to make the ink run.\n\nMe matey here swears he heard Cooktholomew say once he only brought copies out to sea. If that be true, the originals must be back in Booty Bay, somewhere near his bunk!", objectives = "" }
WordHunterWoW_QuestEN[85071] = { title = "Skyrocketing Sprint", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85075] = { title = "To Stormsong", description = "We have need of more species to help pollinate. I have studied your world, and I believe your bees in Stormsong Valley will be best. Not the fire ones though. Too dangerous. \n\nBring back some bees and we can see if they are suitable. Take this communicator in case I need to contact you.", objectives = "" }
WordHunterWoW_QuestEN[85076] = { title = "Don't Bee Crazy", description = "Something is agitating the bees, and I suspect it's these honey-crazed maulers!\n\nTake some down and see if it helps. \n\nEven if it doesn't, you're doing the world a favor. They are completely out of control!", objectives = "" }
WordHunterWoW_QuestEN[85077] = { title = "Sticky Fingers", description = "Stormsong has some of the biggest and best pollinators on Azeroth--when they aren't angry at least. If you are looking to take these, you'll need to try to calm them down.\n\nIt looks like their honey is being stolen. Try to take some honey back from those honey... blob... things?\n\nCan't hurt right? Sorry. I'm more of a plant person than a bee person. They just come with the territory!", objectives = "" }
WordHunterWoW_QuestEN[85078] = { title = "Bee in the Bonnet", description = "While you were out, I scouted some of the smaller bee hives. They all look like they've suffered damage. \n\nWe should investigate them. Maybe that's the cause of their aggression?", objectives = "" }
WordHunterWoW_QuestEN[85079] = { title = "Such a Sleebee-head", description = "We need to deal with the hive guardians one way or another if we are going to investigate this place. \n\nI do hope we don't have to kill them.", objectives = "" }
WordHunterWoW_QuestEN[85080] = { title = "An Un-Bee-lievable Solution", description = "If we can save the smaller bees, they can join the queen's colony. I just wish we had some way of capturing or transporting them. \n\nDo you have any ideas? Perhaps that friend of yours has something?\n\nIf you come across any of the larger bees... I worry they may be beyond saving. Do what you have to do.", objectives = "" }
WordHunterWoW_QuestEN[85081] = { title = "Beehemian Rhapsody", description = "We need a way to lure out the queen so we can take her away from here. \n\nOh! The honey you gathered earlier! Put that out to lure her, then catch her in this ventilated jar. \n\nYou said you were after bees? I think she'd be a great fit.", objectives = "" }
WordHunterWoW_QuestEN[85082] = { title = "To K'aresh", description = "We've secured the queen and apparently sent some bees to K'aresh. \n\nSo... How do we get there?", objectives = "" }
WordHunterWoW_QuestEN[85083] = { title = "Photogra-Bee", description = "The bees seem to be doing very well in this new environment. They are even starting to pollinate the plants here.\n\nWe should document it. It's not science if you don't write it down. You'll find them mostly around the plants.", objectives = "" }
WordHunterWoW_QuestEN[85084] = { title = "Bee Strong", description = "It's taking the hive a while to get up and running, and they are low on honey. \n\nThankfully, you gathered plenty of honey back in Stormsong! Could you feed the queen?", objectives = "" }
WordHunterWoW_QuestEN[85096] = { title = "Skyrocketing Sprint - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85097] = { title = "The Heaps Leap", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85098] = { title = "The Heaps Leap - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85099] = { title = "Scrapshop Shot", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85100] = { title = "Scrapshop Shot - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85101] = { title = "Rags to Riches Rush", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85102] = { title = "Rags to Riches Rush - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85139] = { title = "[PH]", description = "[PH] Any gem can be removed from your Cyrce's Circlet by clicking on them.\n\nThe gem will not be destroyed.\n\nExtract a gem now.", objectives = "" }
WordHunterWoW_QuestEN[85151] = { title = "In Her Shadow", description = "The two of you fell into the trap I set for Shadowlord Vesheen. I need to know what his orders are from Salhadaar and what he knows about Xal'atath's plans.\n\nNow, the three of us are going to sneak into this camp and see what we can discover. We're not here to fight--just some reconnaissance. I don't want him to know that I'm after him.", objectives = "" }
WordHunterWoW_QuestEN[85155] = { title = "Do You Have a Spare?", description = "Now that we know where Vesheen is, I need a cage to put him in so I can get my answers. And I know just the person who will provide us with one.\n\nVe'nari.\n\nYou'll find her in the eco-dome called the Oasis. It's on the island off to the east. Do what you must and don't take no for an answer, {name}.", objectives = "" }
WordHunterWoW_QuestEN[85174] = { title = "Get Out There", description = "You all saw what Gallywix can do. These weapons, this Black Blood--we have to cut him off at the source. Revilgaz, you've gotta kill their shipments coming out of your HQ. And Grimla, Venture Co. has to be involved for Nikki the Fixer to be so well-armed. Split up.\n\n{name}, I want you with me. I've got a newsman, Dirk, you'll want to talk to in Tailgate Park. We'll need hearts and minds to take back this city. I'll be there soon.", objectives = "" }
WordHunterWoW_QuestEN[85184] = { title = "Repossession is Nine-Tenths of the Law", description = "A cage you say? Of course, I have one. But, it's not free. I'll need something in return. Several somethings.\n\nI believe the saying in your world is, \"You scratch my back, I'll scratch yours.\"\n\nTo my point, there are Wastelanders occupying the nearby ruins. They are illegally hoarding relics of historic importance which belong to all the K'areshi.\n\nI want you to repossess them. Take my portation tags to make it all easier. However else would you carry so many? Your backpack isn't that big.", objectives = "" }
WordHunterWoW_QuestEN[85185] = { title = "Those As Well", description = "There are any number of stolen smaller, but still significant artifacts in the ruins at North Sufaad. While you're out there, I see no reason why you should not also retrieve them for me.\n\nI'm certain I can make the transaction worth your time.\n\nI trust this isn't beneath you... so long as the payment is sufficient.", objectives = "" }
WordHunterWoW_QuestEN[85186] = { title = "A Cage for Alleria", description = "I do so love a bit of intrigue. Please hurry back and let me know how everything plays out with this new Shadowguard lieutenant.\n\nActually, I might just come pay you a visit.\n\nI'm sure Alleria will get all the answers she's after this time...", objectives = "" }
WordHunterWoW_QuestEN[85189] = { title = "Our Day in Court", description = "Another series of miscellaneous and legally questionable tasks done well, {name}! You should really consider going into this line of work full time... whatever line of work this is exactly.\n\nI'll grab the Gnomes's signatures, and meet you back at my office.\n\nNormally I'd be willing to give you a ride, but I've got a personal errand to run first. You'll see.", objectives = "" }
WordHunterWoW_QuestEN[85190] = { title = "Settled Dust", description = "I'm surprised Shaw showed up in person. I thought he'd send an agent or somethin', but... maybe I should start expectin' better of people.\n\nI made sure Renzik got looked after. Got the respect he deserves. This chest took me a long time to make. A lot of tiny tools. I'm not used to detail work like that, but I got it done pretty good.\n\nI'm sure he could still pick the lock like nothin', but...\n\n<Gazlowe smiles sadly.>\n\nLet's get him sent back home to Stormwind, yeah?", objectives = "" }
WordHunterWoW_QuestEN[85191] = { title = "Cut After Cut", description = "Renzik was one of my finest agents--but more than that, he was a friend.\n\nHe wasn't an agent of the Stormwind crown begrudgingly fulfilling a mission in Undermine. He worked for Stormwind, but he loved Undermine.\n\nHis people were his home. Not us.\n\nHelp me gather up some of Renzik's things he left here. They should go back to Undermine, along with him.", objectives = "" }
WordHunterWoW_QuestEN[85192] = { title = "Coming Home", description = "Renzik would want his ashes returned to Undermine. I know that for certain, and I would like to do my friend one last favor by seeing it done.\n\nI'm sure he'll like it far more than being stuffed under a marble slab in the Stormwind cemetery, far away from his people.\n\nLet's go, {name}.", objectives = "" }
WordHunterWoW_QuestEN[85195] = { title = "Pirate Gastronomy", description = "Here are Cooktholomew's notes deciphered. Even though this still looks strange, I am positive I deciphered it correctly. \n\nI was able to work out how much of everything you need, but it looks like he had his own names for different ingredients, so... good luck!", objectives = "" }
WordHunterWoW_QuestEN[85196] = { title = "Tag, You're It", description = "Vesheen is up in the Khiyed Ruins to the north. The fool thinks he's so clever, but he's about to find out who he is dealing with.\n\nWear him down and then place Ve'nari's tag on him. It will teleport him into the cage here.\n\nI'll stay here to make sure the cage works. Hurry, {name}, before he realizes we're on to him!", objectives = "" }
WordHunterWoW_QuestEN[85208] = { title = "A Pirate Missive", description = "There you are, {name}. Someone named Scowling Rosa wants to see you in Booty Bay.", objectives = "" }
WordHunterWoW_QuestEN[85212] = { title = "A Void Test of Wills", description = "This will be dangerous. I intend to use the Void to break his will and extract what I can from his mind.\n\n{name}, stand ready to assist. First, we'll set up some ritual devices. Then, listen for my instructions.\n\nOne false move could mean our doom.", objectives = "" }
WordHunterWoW_QuestEN[85213] = { title = "Off to Tazavesh, Again", description = "Now that we've helped my mother, it's time to continue on.\n\n<Arator seems choked up at the idea of leaving his mother again so soon.>\n\nVe'nari helped us before. I know it's dangerous, but maybe she can get us into the Maw to find Sylvanas?", objectives = "" }
WordHunterWoW_QuestEN[85214] = { title = "Here Goes Something", description = "Getting you into the Maw to visit his auntie, Sylvanas, can be done... but at no small risk to Arator. Under no circumstance should he linger there.\n\nHowever, that is your business. I am in the business of keeping my slates clean, and this is something I can do for you.\n\nThe engine of Tazavesh can power a gateway and allow the two of you to break into that dreadful place.", objectives = "" }
WordHunterWoW_QuestEN[85229] = { title = "Rallying All Rapscallions!", description = "Come one, come all, straight to Dornogal!\n\nIn addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds!\n\nPresent this brochure to Hotharn to receive a few of these, on us!\n\n- Aisha", objectives = "" }
WordHunterWoW_QuestEN[85238] = { title = "Stranger on the Steps", description = "Please! We have to stop the Naakroans. Three of us were sent by cartel Om to install a research machine. It was only meant to help study extinct plants. At first, the Wastelanders were polite, even curious--until we tried to leave. \n\nThey forced us to modify the machine. Om'musa refused and they killed him. Om'baladh and I obeyed. We should have refused as well.\n\nOnce we finished, the Wastelanders let their guards down. Om'baladh said to run, so I did. He was right behind me. Please--find him.", objectives = "" }
WordHunterWoW_QuestEN[85239] = { title = "A New Devouring", description = "This isn't a temple anymore--it's an abattoir. They tear souls from captives to power their rituals. Right now, they're pouring stolen energy into our machine. I think I know why.\n\nWith the modifications we made, overloading the device with arcane energy will create a massive feedback loop. It'll disrupt our technomancy across K'aresh. The eco-domes will fail. Tazavesh will be defenseless. We'll be just another feast for the Naakroans. If you can disrupt their rituals, it will buy us time.", objectives = "" }
WordHunterWoW_QuestEN[85240] = { title = "Only Hunger Remains", description = "They think Xal'atath has returned for them--that their worship will be rewarded. They'll consume everything to prove their devotion to her.\n\nWe came here for peace--to rebuild our shattered home. We have to protect the future, {name}. It's all we have left. These Wastelanders are massing to raid the eco-domes. If they manage to bring down the shields, they'll pick them clean. Don't give them that chance.", objectives = "" }
WordHunterWoW_QuestEN[85241] = { title = "A Once-Proud Priest", description = "Their leader conducts the last ritual site. Issam the Unraveler... I saw him live up to that name. If he uses our echo machine against us, he and his followers will tear through everything. We'll all be offerings to their absent \"god.\"\n\nSlay him and end his ritual. We can't allow a second Devouring.", objectives = "" }
WordHunterWoW_QuestEN[85242] = { title = "Seasonal Refresher", description = "We're back tae uncovering more things within delves! \n\nLet's get ye up to speed on new items we've found first. \n\nThen I've got some concerning information tae talk about.", objectives = "" }
WordHunterWoW_QuestEN[85243] = { title = "I Want My Hat Back", description = "Ye may have noticed a change in me fashion. \n\nSome goblin went and took me hat! And all the treasures we had collected so far!\n\nI'll tell ye how it all went down.", objectives = "" }
WordHunterWoW_QuestEN[85244] = { title = "Defeating the Underpin", description = "This blasted \"Underpin\" took me hat! Along with all the curios we collected.\n\nIt's time tae get some vengeance. We got tae get stronger if we're going tae take him down.\n\nI know he's somewhere in Undermine when yer ready tae tackle him. \n\nI'll be right there with you!", objectives = "" }
WordHunterWoW_QuestEN[85249] = { title = "A Bee Test", description = "I will send your... guest... to the Atrium to handle the bees.\n\nYou should check on her. No doubt she needs assistance.", objectives = "" }
WordHunterWoW_QuestEN[85252] = { title = "Lorewalking: Children of the Blood", description = "The blood elves of the Eastern Kingdoms have only taken up that name in recent years. Once, they were known as highborne, or high elves--but no more. Would that it were a pleasant tale, but in truth the name reflects upon those who have fallen and lost their lives... an unthinkable number. \n\nThe blood elves, or sin'dorei, will never forget that loss. Let us remember them as well.", objectives = "" }
WordHunterWoW_QuestEN[85254] = { title = "Lorewalking: Children of the Void", description = "The void elves... so strange. There is very little difference between a void elf and a blood elf, other than what they have chosen to wield. Yet to their former kin, they are anathema--no longer considered a blood elf at all, and no longer welcome in their former home. \n\nLet us explore how, and why, this came to be.", objectives = "" }
WordHunterWoW_QuestEN[85255] = { title = "Tranquila-Bee", description = "I think we should start prepping to move the bees into the Oasis. I'd like to tag them so we can monitor the hive. \n\nBees don't tend to stand still for long. We'll need to tranquilize and tag them. I tagged the queen. Would you tag the honey bees?", objectives = "" }
WordHunterWoW_QuestEN[85256] = { title = "Botany, Finally", description = "The bees are doing well and have no negative interactions with the local fauna. But what about the flora?\n\nI have some cuttings of plants from the Oasis. Would you gather some cuttings from this dome so I can compare them?", objectives = "" }
WordHunterWoW_QuestEN[85257] = { title = "Primus Buzzness", description = "Alright. Let's get these bees into Eco-Dome: Primus for the next round of tests!", objectives = "" }
WordHunterWoW_QuestEN[85258] = { title = "Oh Honey Honey", description = "The hive has settled in quite well. I'd like to do a quick honey check though. The pollen in these plants is quite different, and it should change the honey quite a bit. We need to make sure it's working for the hive. \n\nIt should be fine based on the experiments in the earlier domes. Best to check though, right?", objectives = "" }
WordHunterWoW_QuestEN[85259] = { title = "Waggle Dance", description = "Alaenra requested that I pass on a message.\n\n\"Hey, Om'talad. I'm going to dance for the bees so they know where the new flowers are. Can you ask {name} to do the same?\"\n\nOdd, but please feel free to... frolic.", objectives = "" }
WordHunterWoW_QuestEN[85260] = { title = "Hiving a Hard Day", description = "I just spotted a few bees flop to the ground. I think they've overworked themselves trying to get at the new plants.\n\nThey'll be fine. They're just tired. Could you help me pick them up and bring them back to the hive?", objectives = "" }
WordHunterWoW_QuestEN[85261] = { title = "Bee Roll", description = "Ah, there you are. It's time for documentation!\n\nWe need to keep track of how the bees are doing in the Oasis. I've filled out the paperwork already. Perhaps you could get me some photos of the bees in action?", objectives = "" }
WordHunterWoW_QuestEN[85262] = { title = "The Royal Procession", description = "Hmm, your photos make me think the hive is ready to swarm!\n\nThis is the ultimate goal of any hive--birth a new queen and create a new hive. It does mean our queen needs to move to a new location, but there is plenty of eco-dome to go around, right?\n\nCan you help her find a new location?", objectives = "" }
WordHunterWoW_QuestEN[85383] = { title = "Applied Mixology", description = "Allow me to introduce myself, traveler. I am known as Ba'kril.\n\nAs you know, my people do not imbibe as yours do. My proposal is simple: help me concoct a new energy drink and I shall allow you to use it free of charge.\n\nIt will most certainly make you a hero amongst heroes. Is that not worth the risk?\n\nI have acquired various potent energy sources. Infuse them into the berry juice cocktail and let us see how potent we can make it.", objectives = "" }
WordHunterWoW_QuestEN[85384] = { title = "Market Research", description = "Since I never doubted our success, I took the liberty of making further preparations.\n\nI have arranged for a couple of volunteers. I want to see our new energy drink in action before you imbibe it, {name}. May I call you {name}? Of course I can. We're partners now.\n\nYou will find the volunteers lounging on the high terraces of the city. Tazavesh has many such comfortable areas for visitors like yourself.", objectives = "" }
WordHunterWoW_QuestEN[85394] = { title = "An Eye for Trouble", description = "If we were to consider the silver lining here, it is that we now know our concoction works. Just not on whom we wished.\n\nI do not suppose you have it in you to defeat this empowered version of the creature? It is only our reputations and the future of Tazavesh at stake.\n\nAnother chance to prove you truly are as mighty as they say.", objectives = "" }
WordHunterWoW_QuestEN[85409] = { title = "Snitches Get Stitches", description = "I thought we could talk here in Gutterville, but it feels tense. They're all Venture Company, but I don't recognize a lot of 'em. Word is, Gallywix sent down a bunch of workers who are sympathetic to him so they could spy on us. \n\nClear out some of these turncoats. If any of them report to Overseer Gozzic that we're working against the pipeline, he'll go after my people.", objectives = "" }
WordHunterWoW_QuestEN[85410] = { title = "Undermine's Long Shadow", description = "These engineers have been through a lot. Let's make sure they're good. Maybe they can shed some light on Undermine.", objectives = "" }
WordHunterWoW_QuestEN[85429] = { title = "Overwhelm Them", description = "There's an audit coming up. My employer, Xy Imports, will be audited. Again.\n\n<Xy'nell visibly shakes, ducking his head.>\n\nI need this audit to go badly. It must be worse than the last.\n\nCan you help me? We have a shipment of small devourers that would cause a lot of trouble if they were to escape or go missing.\n\nBreak open their crates. Business needs to be overwhelmed just like last time.", objectives = "" }
WordHunterWoW_QuestEN[85430] = { title = "Mandatory Time Off", description = "If my colleagues knew of my plan, they would be in danger of discharging their oaths as good employees. Besides that, they are far too excellent at their jobs.\n\nTake these. They're devices of my own creation. When placed near my colleagues, it will create an illusion of them working.\n\nThey will be able to step away and rest. And the business will be under even more pressure without them.", objectives = "" }
WordHunterWoW_QuestEN[85431] = { title = "Drain Their Resources", description = "We've made good progress, but we need more disorganization.\n\nI've redirected a particularly large shipment of anima in the form of a devourer. Kill it and bring its anima core to me.\n\nThe anima itself is not important--rather, the fact that it can be stolen. My boss will have more to answer for in the audit when his books are in disarray.", objectives = "" }
WordHunterWoW_QuestEN[85432] = { title = "Confuse Their Contacts", description = "When our imports are delayed or lost, the most direct impact is on Tazavesh businesses.\n\nTake this illusion pin. It will make you appear as a Xy Imports employee. Tell the businesses their shipments are delayed indefinitely.\n\nMy boss cannot ignore downstream pressure forever.", objectives = "" }
WordHunterWoW_QuestEN[85433] = { title = "Eyes on Us", description = "I can hear Coordinator Xy'thir raging about the slide in business already.\n\n<Xy'nell shifts uncomfortably and ducks his head.>\n\nWe're ready. Go to Port Authority Zo'rau. Tell them you represent an invested party and that the audit should be moved up.\n\nAnd there's one more thing I need you to do. Speak with me before you go.", objectives = "" }
WordHunterWoW_QuestEN[85434] = { title = "On a Technicality", description = "It's time. I cannot tell you what to expect, {name}. I only hope this is the last day I must keep such a dreadful oath.\n\n<Xy'nell shakes his head.>\n\nLet us hurry. Port Authority Zo'rau has already begun questioning Coordinator Xy'thir.", objectives = "" }
WordHunterWoW_QuestEN[85438] = { title = "Or Else", description = "Am I glad I found you, {name}! \n\nMy boss, Kraz Torquewrench, sent me to find you, and he don't take no for an answer, yanno? I thought I was gonna have to cash out and move futher underground, but here you are!\n\nAnyway, the boss's little girl is getting married, and he told me he wanted you, specifically, to help him \"finalize\" some \"details,\" with her intended and who's attendin'--if you get my meanin'.", objectives = "" }
WordHunterWoW_QuestEN[85444] = { title = "Found Family", description = "This crew trusted me. They're my family. We gotta see if any of them survived. \n\nI have other engineers who ain't here. They must have fled into the field. Razi, Keets, and Glizza are out there. Find 'em. Bring 'em home.", objectives = "" }
WordHunterWoW_QuestEN[85449] = { title = "Phase Shift", description = "As soon as the ethereals attacked, phase resonance tore open rifts throughout the area. The rifts are gone, but the ethereals can return while the resonance remains. That is how they call more soldiers and communicate with their commanders.\n\nWe need to destroy that resonance.\n\nIt may earn us the ire of whoever is behind this attack, but I gladly invite them to stop us.", objectives = "" }
WordHunterWoW_QuestEN[85450] = { title = "Evacuation Plan", description = "We cannot let the ethereals find the Dark Heart before we do.\n\nGazlowe needs to be informed. We must gather our forces and find the Dark Heart--quickly!", objectives = "" }
WordHunterWoW_QuestEN[85451] = { title = "The Burning of Hammerfall", description = "The Syndicate has put Hammerfall to torch!\n\nAnd the cowards are using pyromancers to feed the flames.\n\nBut we can save our huts if we get to them quickly.\n\nFight through the Syndicate bandits to a building and then blow this horn. A Hammerfall shaman will come to put out the fire!", objectives = "" }
WordHunterWoW_QuestEN[85459] = { title = "Anima Reclamation Program", description = "The eco-domes run on anima. While you are out in K'aresh, if you see any devourers--kill them and return with their anima.\n\nYou will be compensated.", objectives = "" }
WordHunterWoW_QuestEN[85461] = { title = "Food Run", description = "Our latest food shipment for the animals was taken by an ethereal raid in Tazavesh. \n\nI would like you to reacquire it.", objectives = "" }
WordHunterWoW_QuestEN[85462] = { title = "A Challenge for Dominance", description = "Our slateback alpha has been getting a bit... testy recently. I believe he is looking for a challenge. \n\nYou are the most combat capable of us. Go give him one.", objectives = "" }
WordHunterWoW_QuestEN[85465] = { title = "Play Ball", description = "This thorntail kit has been begging me for attention all morning. It is quite charming, but I have work I need to get done!\n\nI think it needs to burn some energy off. Take this ball and go play with it.", objectives = "" }
WordHunterWoW_QuestEN[85470] = { title = "Root Redux", description = "Some of the lapbugs are getting stuck in the tree roots again. If left to their own devices they will eventually eat their way out, but it would be easier if you offered your assistance.", objectives = "" }
WordHunterWoW_QuestEN[85475] = { title = "Secret in the Sands", description = "Welcome back. Maru is looking for you again. She says only you have the skills to help her with this task.\n\n<The groans and complaints from the crowd intensify.>\n\nOh, don't worry about me. I'll be here... As always...", objectives = "" }
WordHunterWoW_QuestEN[85476] = { title = "Buried Tweasure", description = "Hello friend! You won't believe it, but I heard there's a hidden tweasure somewhere in Tanaris!\n\nI'm suuuper sneaky and managed to get a copy of the first riddle. And you're so good at solving them tat I want to give it to you!", objectives = "" }
WordHunterWoW_QuestEN[85477] = { title = "Lost and... Found?", description = "I am so overwhelmed. A group of folks were here a little while ago, all complai... I mean, submitting lost-item notices with great passion, but all at the same time. \n\nI tried to take down all the details, but in the stress of the moment, I fear they're all jumbled.\n\nI have this collection of items that have been found over the day, and I'm fairly sure these are the items those folks were talking about. Do you think you could use my notes and figure out which item belongs to each person?", objectives = "" }
WordHunterWoW_QuestEN[85481] = { title = "Ridge Racer", description = "Our Slateback Alpha needs to burn off some energy. I believe he is looking for a race.\n\nHe seems to enjoy you the most. Would you race with him?", objectives = "" }
WordHunterWoW_QuestEN[85502] = { title = "Festive Reflections", description = "Oh good, you're back. I have my hands full here and Detective Jones has been asking for your help on some new case.\n\nNot that it seems to matter. For all the good we do for the guests, I think this line--if you can still call it that--has only grown longer!\n\nI should get back to it, and you should talk to Detective Jones.", objectives = "" }
WordHunterWoW_QuestEN[85503] = { title = "A Surprising Investigation", description = "Well, look who's back to solve more cases.\n\nIt seems that Chromie has been fiddling with time again and some imposters have popped up around the celebration area.\n\nAll you need to do is identify who doesn't belong and send them to Chromie. This should be a breeze for you.", objectives = "" }
WordHunterWoW_QuestEN[85523] = { title = "Mildewed Celebration Crate", description = "<The crate is covered in a growing mildew from the jungle climate. It looks like you found it before the goods inside were spoiled. Alyx would appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[85529] = { title = "Past Glory", description = "Marran's\"Red Dawn\" has left the city and peace has returned to Stromgarde. \n\nAt least for now.\n\nFaerin left for the countryside. She said she wanted to check on Newstead and Refuge Point, but I think she wanted to get out of Stromgarde.\n\nShe came here with such enthusiasm. I should not have tempered it so harshly. I feel in the end it was I who needed to learn a lesson.\n\nWe should check in on her.", objectives = "" }
WordHunterWoW_QuestEN[85531] = { title = "Earth-Encrusted Gem", description = "", objectives = "" }
WordHunterWoW_QuestEN[85532] = { title = "The Wealth of a Kingdom", description = "", objectives = "" }
WordHunterWoW_QuestEN[85533] = { title = "Kej", description = "", objectives = "" }
WordHunterWoW_QuestEN[85534] = { title = "The General's Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[85535] = { title = "Kej", description = "", objectives = "" }
WordHunterWoW_QuestEN[85536] = { title = "Resonance Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[85537] = { title = "Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[85538] = { title = "Shinies", description = "", objectives = "" }
WordHunterWoW_QuestEN[85539] = { title = "Take Candle!", description = "", objectives = "" }
WordHunterWoW_QuestEN[85540] = { title = "Take Big Candle!", description = "", objectives = "" }
WordHunterWoW_QuestEN[85541] = { title = "Here's a Shiny!", description = "", objectives = "" }
WordHunterWoW_QuestEN[85542] = { title = "Take Really Big Candle!", description = "", objectives = "" }
WordHunterWoW_QuestEN[85543] = { title = "More Shinies!", description = "", objectives = "" }
WordHunterWoW_QuestEN[85544] = { title = "Many Little Shinies!", description = "", objectives = "" }
WordHunterWoW_QuestEN[85545] = { title = "Resonance Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[85546] = { title = "Resonance Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[85553] = { title = "Side Gig: Feeling Crabby", description = "Food's a critical resource for any crew that dares to sail the sea. So is gunpowder.\n\nLet's kill two crabs with one stone and get our hands on some of those bombshells out on the Kaja'Coast.\n\nJust don't get yourself blown up while you do it, yeah?", objectives = "" }
WordHunterWoW_QuestEN[85554] = { title = "Side Gig: It's Always Sunny Side Up", description = "Pterrordax eggs have been all the rage lately in the Undermine. And what good would the Blackwater name be if we couldn't import high-demand luxury goods?\n\nIf you're interested in makin' some gold, head over to the Kaja'Coast and collect some for us.\n\nOh, and make sure you don't take too many. Consumers these days love when we can label our goods \"ethical.\"", objectives = "" }
WordHunterWoW_QuestEN[85560] = { title = "TEST", description = "", objectives = "" }
WordHunterWoW_QuestEN[85562] = { title = "Tougher Than We Thought", description = "Hah! I've never been feeling better! Now, we seize back what rightfully belongs to Blackwater, {name}.\n\nThey've turned our prized headquarters into a smuggler's cove for that foul sludge. There are too many crates of Black Blood to deal with right now, but they can't move their cargo without fresh bodies. Let's cut them down.", objectives = "" }
WordHunterWoW_QuestEN[85570] = { title = "The Tattered Journal", description = "<The journal almost falls apart in your hands as you leaf through it. \n\nWhat few pages that remain are filled with an erratic scrawling script.\n\nPerhaps Stellin Verasa would be interested in this journal back in camp.>", objectives = "" }
WordHunterWoW_QuestEN[85571] = { title = "Scattered To The Winds", description = "My goodness! This journal is missing many of its pages! \n\n<Stellin flips through the journal, careful to not let any loose pages fall out.>\n\nThis journal doesn't look very old... and it seems to be of human origin? Could this be the key to discovering what happened to the humans that came here? What a mystery!\n\nBut less of a mystery if we could find the missing pages... Would you keep an eye out for them while you're out in the field?", objectives = "" }
WordHunterWoW_QuestEN[85572] = { title = "A Group Effort", description = "This is, um, quite the mess you've handed me. All these pages... what order do they go in?\n\nAha!\n\nThis journal seems to have belonged to a Kul Tiran that came here...\n\n<Stellin looks up, her eyes shining with excitement.>\n\n...and it might hold the key to learning about their time on the isle. \n\nBut the pages are hard to read... perhaps we should ask around to see if anyone can read them?\n\nHere, take a few pages. I'll keep trying to decipher the base journal while you go to camp and ask around.", objectives = "" }
WordHunterWoW_QuestEN[85573] = { title = "Laid To Rest At Last", description = "<Stellin listens as you explain what you've learned and nods gravely.>\n\nThis poor fellow was part of a crew that sailed here aboard a ship called the Maiden's Whisper. They were almost wiped out by a storm, but then even the survivors disappeared!\n\nHe was the last one and... didn't make it either in the end. Perhaps we can put his memory to rest?\n\nI spotted a graveyard out behind the Kul Tiran's base... perhaps setting the journal there amongst his crew's graves will bring his memory some peace.", objectives = "" }
WordHunterWoW_QuestEN[85574] = { title = "Hazy Celebration Crate", description = "<This crate phases in and out of existence with dark, necromantic energy. Regardless, Alyx would likely appreciate the supplies returned.>", objectives = "" }
WordHunterWoW_QuestEN[85589] = { title = "Ruffled Pages", description = "Many of the wyvern on this isle have crafted their nests from folios, scrolls, and documents they scavenge from the isle's ruins.\n\nBecause of this, their nests may hold the clues we need to understand the full history of this place.\n\nOur scouts have secured grappling holds for you to climb to their nests, but use any means you like to recover the paper the wyverns have used as nesting material. Our knowledge of the isle's history depends on it!", objectives = "" }
WordHunterWoW_QuestEN[85648] = { title = "Delver's Call: Earthcrawl Mines", description = "HELP WANTED\n\nTroubles continue within Earthcrawl Mines. Fine pay to whoever can handle it.", objectives = "" }
WordHunterWoW_QuestEN[85649] = { title = "Delver's Call: The Waterworks", description = "NOTICE\n\nThe Waterworks have become unstable. Request aid in addressing issues.", objectives = "" }
WordHunterWoW_QuestEN[85653] = { title = "Dipping a Toe", description = "That ring of yours has caused quite a stir, hasn't it? And the history behind it... vrykul? Someone named Cyrce?\n\nI know you and Bargus unlocked more of the ring's potential by scouting the isle but... perhaps you should turn your attention to the sea?\n\nTake your ring into the water and see what happens. Bring whatever you find back to me. I'm a bit of a novice, but I might be able to piece whatever you find back together.", objectives = "" }
WordHunterWoW_QuestEN[85654] = { title = "Juicing Up and Storming Out", description = "Well, look. If it ain't {name}, the talk of the camp.\n\n<Didi grabs your hand and looks closely at your ring.> \n\nThat ring on ya finger sure is peculiar, ya sure ya don't want a different one? \n\n<Didi looks up at you and winks.> I'm just yankin' ya chain, let's see what we can do with it!\n\nYa get me enough of that magic metal lookin' stuff we've been finding, and I'll see about gettin' you suited up in the Pummeler over there. \n\nYour ring oughta give it the juice it needs to really wreak some havoc!", objectives = "" }
WordHunterWoW_QuestEN[85655] = { title = "Unleashing Her Power", description = "This ring that you and Bargus found has taken you all over the isle learning its history and finding its treasures.\n\nThe ring has aided you in your exploration--and in battle. But, we have never truly pushed the ring to find its limitations.\n\nPerhaps some formal testing is in order. Perhaps we can unveil more of its potential if we invite a bit of danger.\n\nGo now and test the ring against any worthy opponents you can find. Come back to me with your observations.", objectives = "" }
WordHunterWoW_QuestEN[85656] = { title = "The Singing Bandit Catcher", description = "Seems you've gotten the hang of that ring, eh? Maybe you can put it to good use for me. \n\nOur supplies here--especially our gold and flame-blessed iron--have been disappearing!\n\n<Tanmar leans in to whisper.> \n\nNormally I wouldn't suggest this--the Arathi are a trustworthy lot--but the number of incidents is building. and I'm wondering if there's a thief among us.\n\nSee if you can find 'em. They being pretty brazen. I'm sure you can catch 'em in the act somewhere!", objectives = "" }
WordHunterWoW_QuestEN[85657] = { title = "Cyrce Would Be So Proud", description = "It ain't no secret the winds here are terrible. \n\nBut! I don't think we've given that ring there a fair chance at fightin' 'em. I mean, that thing can let ya swim like a fish, make tornadoes outta nothin', and even shock the invisibility off of magical boxes! Surely it's got somethin' to say about a lil' nasty weather, right?\n\nTake my balloon up and see if you can keep it stable usin' that ring of yours. Maybe we can find the trick for stayin' in the sky!", objectives = "" }
WordHunterWoW_QuestEN[85664] = { title = "Delver's Call: Nightfall Sanctum", description = "CALL FOR AID!\n\nThe Order of Night may have a base set up in a location called Nightfall Sanctum.\n\nIt is imperative that we stop any of their operations as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[85666] = { title = "Delver's Call: Spiral Weave", description = "HELP WANTED\n\nWord is the nerubians have big military operations within the Spiral Weave.\n\nHelp out the survivors of the Dalaran crash by putting a stop to them!", objectives = "" }
WordHunterWoW_QuestEN[85667] = { title = "Delver's Call: The Underkeep", description = "WEAVER'S ORDERS\n\nDark operations are happening within a place called the Underkeep.\n\nI wish for it to halt.", objectives = "" }
WordHunterWoW_QuestEN[85678] = { title = "Repair Yourself", description = "Your gear isn't looking too great from your last excursion.\n\nSpeak to Quartermaster Richter to get it repaired.", objectives = "" }
WordHunterWoW_QuestEN[85679] = { title = "Repair Yourself", description = "Your gear is nearly destroyed from your last fight!\n\nSpeak with Provisioner Jin'hake to repair it right away.", objectives = "" }
WordHunterWoW_QuestEN[85710] = { title = "Sizing Them Up", description = "We have been trying to do medical checkups on the slatebacks, but they are... aggressive in their disagreement.\n\nVe'nari has provided this shrinking device to help. Collect some for me.", objectives = "" }
WordHunterWoW_QuestEN[85711] = { title = "Unsolicited Feedback", description = "Alice is back, and she's a much better cook than she ever was before she became a <whispers> rat.\n\nBut don't take my word for it. Here, hand out some food and hear it straight from the customers!", objectives = "" }
WordHunterWoW_QuestEN[85716] = { title = "Rune-Seared Spear", description = "<An elaborate rune-covered spear. Angorla may have interest in studying this weapon.>", objectives = "" }
WordHunterWoW_QuestEN[85718] = { title = "A Shining Stone", description = "", objectives = "" }
WordHunterWoW_QuestEN[85721] = { title = "Killer Instinct", description = "The hunting training seems to be working with the Thorntail Matriarch, and we'd like to keep up with it. \n\nCan ye have her hunt a few more lapbugs at your direction?", objectives = "" }
WordHunterWoW_QuestEN[85722] = { title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", objectives = "" }
WordHunterWoW_QuestEN[85724] = { title = "Repel the Invaders", description = "A big lunk of a hobgoblin, Skeez, took over the docks around the time that Gallywix had me thrown in the brig. He moved his Darkfuse in, and a lot of my Blackwater lads went missing. Captain took that personal, and so do I. Skeez thinks Gallywix will keep him safe.\n\nLet's kill him.", objectives = "" }
WordHunterWoW_QuestEN[85730] = { title = "Salvaging What's Left", description = "The loss of an eco-dome is unimaginable. The death of Om'bera...\n\n<The broker's shoulders rise and fall in what looks like a sigh, though no breath is heard.>\n\nI cannot leave without retrieving the research crates! Her work must live on, even if she cannot. Om'bera's manifest says that there were at least five crates full of research and resources.", objectives = "" }
WordHunterWoW_QuestEN[85780] = { title = "Right Where We Want Him", description = "Gallywix is down, but he ain't out. \n\nThe Gallagio is built like a fortress. If we want to keep him from threatening Undermine, or Azeroth, we gotta figure out how to get him outta there. Meet me and the other bosses back at the Incontinental Hotel.", objectives = "" }
WordHunterWoW_QuestEN[85804] = { title = "The Parent Trap", description = "I'm happy to help in any way that I can.\n\nTo find Alleria, you must fly far north from here. She's hunting a new Shadowguard lieutenant in the hope of extracting information from him.\n\nLast I heard, she was on the outskirts of a place called the Fracture of Laacuna.", objectives = "" }
WordHunterWoW_QuestEN[85811] = { title = "Thrayir, Eyes of the Siren", description = "<The power of the storm has reformed Thrayir, Eyes of the Siren.  He awaits your acceptance.>", objectives = "" }
WordHunterWoW_QuestEN[85815] = { title = "A Small Pouch of Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[85818] = { title = "A Small Pouch of Crystals", description = "", objectives = "" }
WordHunterWoW_QuestEN[85827] = { title = "Glinting and Gleaming", description = "", objectives = "" }
WordHunterWoW_QuestEN[85862] = { title = "A Prince's Duty", description = "It's a big day, lad. We've got a parade of the troops, a visiting contingent from Ironforge, and I hear word your father--er, King Terenas--will be here to oversee everything.\n\nIt's days like today that you've been forged for, Arthas. Inspire your men. Prove yourself. \n\nWhip these troops into shape. No doubt Muradin has been itching for a brawl as well...", objectives = "" }
WordHunterWoW_QuestEN[85869] = { title = "Many Jobs, Handle It!", description = "Shipping & Handling is tryin' out a new driver incentive program.\n\nDo some jobs and let's see how it goes eh?", objectives = "" }
WordHunterWoW_QuestEN[85871] = { title = "Lorewalking: The Blade's Forces", description = "Xal'atath brings with her an army of shadows and tricks. \n\nThey are nothing to our evolved forms! \n\nYou have been chosen--blessed with power by N'Zoth to serve as his champion. \n\nGo now and destroy them!", objectives = "" }
WordHunterWoW_QuestEN[85873] = { title = "Another Shadowy Invitation", description = "{name}, do you like paperwork and forms as much as I do? \n\nThen let us dispense with the expedited entry to Tazavesh and experience once more the joy of jumping through bureaucratic hoops and paying bribes as is the tradition of all great broker stories.\n\nWARNING!  \nCOMPLETING THIS QUEST WILL REQUIRE YOU TO FINISH CHAPTER 1 OF THE 11.2 CAMPAIGN!", objectives = "" }
WordHunterWoW_QuestEN[85875] = { title = "Ascent of the Lich King", description = "<Icecrown lies before you. Waiting. \n\nFrostmourne bids you...\n\n... ascend.>", objectives = "" }
WordHunterWoW_QuestEN[85876] = { title = "Reading the Runes", description = "My curiosity is still not terminated, {name}. I would like to know more about these vrykul and why they came to this land.\n\n<Bargus's wiry brows knit together and his mustache bristles as he thinks.>\n\nThe tablets you found were by far the best source of information on the vrykul and whoever this \"Cyrce\" is. \n\nPerhaps there are additional tablets we missed?\n\nI have my ordained duties here, but please examine them and report back to me.", objectives = "" }
WordHunterWoW_QuestEN[85878] = { title = "O' Thanagor", description = "You are the Lich King.\n\nThe whole of Azeroth is arrayed against you.\n\nShow them what it means to be king.", objectives = "" }
WordHunterWoW_QuestEN[85879] = { title = "Reduce, Reuse, Resell", description = "The guys over at S.C.R.A.P. could use some extra hands this week.\n\nYou want a piece of the pie, go find one of their reps named Carlo out in the field and see if he's got any work for you.\n\nBut if you find a piece of pie in any of those trash piles, don't, uh... Don't actually eat it. I hope that kinda goes without sayin'.", objectives = "" }
WordHunterWoW_QuestEN[85884] = { title = "Lorewalking: The Prince Who Would Be King", description = "Before I can tell you the story of the Lich King, we must learn about who he was before he put on his crown.\n\nBefore he pulled that cursed sword from the depths of Frostmourne Cavern. \n\nWe must talk about the prince who was promised the world, and the people who championed his cause. \n\nWe must start in Lordaeron, many years ago, on a day of pomp and circumstance.", objectives = "" }
WordHunterWoW_QuestEN[85885] = { title = "Lorewalking: No King Rules Forever", description = "What makes a king? Is it his crown? Is it the sharpness of his sword? The coldness of his heart?\n\nPerhaps the undying servitude of his people?\n\nJust as it is difficult to say when a sapling becomes a tree, or a mountain becomes a hill, so too is it difficult to know when exactly Arthas Menethil passed into memory, and the Lich King was born.\n\nWhere do we draw the line between man and monster?", objectives = "" }
WordHunterWoW_QuestEN[85900] = { title = "Breakneck Bolt", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85901] = { title = "Breakneck Bolt - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85902] = { title = "Junkyard Jaunt", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85903] = { title = "Junkyard Jaunt - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85904] = { title = "Casino Cruise", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85905] = { title = "Casino Cruise - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85906] = { title = "Sandy Scuttle", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85907] = { title = "Sandy Scuttle - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[85913] = { title = "Side Gig: Cleanup Detail", description = "We're looking for someone with a strong arm and stronger stomach to help deal with all the blood monsters popping up in the Ringing Deeps. The cleanup crews keep getting eaten and it's murder on our schedule.\n\nYou up for it?", objectives = "" }
WordHunterWoW_QuestEN[85914] = { title = "Side Gig: Coolant Matters", description = "Sounds like the old Black Blood pipes in the Ringing Deeps are thawing out, but we haven't figured out a solution for all the goo they're packed with just yet. A few more budgetary meetings, though, and we're on it.\n\nIn the meantime, we earmarked a little cash for some temp help. That's you.\n\nGet out there and refreeze those pipes.", objectives = "" }
WordHunterWoW_QuestEN[85916] = { title = "Midnight", description = "", objectives = "" }
WordHunterWoW_QuestEN[85917] = { title = "Midnight", description = "", objectives = "" }
WordHunterWoW_QuestEN[85918] = { title = "Midnight", description = "", objectives = "" }
WordHunterWoW_QuestEN[85919] = { title = "Midnight", description = "", objectives = "" }
WordHunterWoW_QuestEN[85920] = { title = "Midnight", description = "", objectives = "" }
WordHunterWoW_QuestEN[85921] = { title = "Midnight", description = "", objectives = "" }
WordHunterWoW_QuestEN[85929] = { title = "Archivist Rubbleglint", description = "", objectives = "" }
WordHunterWoW_QuestEN[85930] = { title = "Archivist Coppermoss", description = "", objectives = "" }
WordHunterWoW_QuestEN[85931] = { title = "Archivist Farolt", description = "", objectives = "" }
WordHunterWoW_QuestEN[85932] = { title = "Archivist Silsigra", description = "", objectives = "" }
WordHunterWoW_QuestEN[85933] = { title = "Elder Knythall", description = "", objectives = "" }
WordHunterWoW_QuestEN[85934] = { title = "Elder Swornvow", description = "", objectives = "" }
WordHunterWoW_QuestEN[85935] = { title = "Elder Ikk'zivan", description = "", objectives = "" }
WordHunterWoW_QuestEN[85936] = { title = "Elder Ikk'xataz", description = "", objectives = "" }
WordHunterWoW_QuestEN[85941] = { title = "Attitude Adjustment", description = "I'm not a violent gal by nature, but there are a lot of Darkfuse out there. They're already hassling the locals and they won't like you guys asking questions. \n\nYou wanna keep your friends safe? You wanna put the locals in better spirits? It'd probably be best if there were a whole lot less Darkfuse. If you catch my meaning.", objectives = "" }
WordHunterWoW_QuestEN[85944] = { title = "Side Gig: Blood Type", description = "Darkfuse was up to all sorts of questionable research out in the Ringing Deeps and, well, everywhere, really.\n\nAnyway, they had to write some of it down. Nab whatever notes you can find and bring them back to me.\n\nDon't look at me like that. It's not intellectual dishonesty, it's industrial espionage!", objectives = "" }
WordHunterWoW_QuestEN[85945] = { title = "Side Gig: Blood-B-Gone", description = "Do you have any idea how hard it is to get dried blood stains out of your laundry? Well, you might, I guess.\n\nSteamwheedle's finest are working on a new detergent specifically formulated to deal with this pressing issue!\n\nAnd while the blood fields in the Ringing Deeps might be bad for the environment, and you, they're the perfect place to field test our latest formulations.\n\nJust give the blood slimes out there a quick hose down and let us know what happens.", objectives = "" }
WordHunterWoW_QuestEN[85947] = { title = "An Original Journey Through Time", description = "Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day.\n\nI bet they would say you're not tough enough to last 10 minutes in their world.\n\nThink you're tough enough to find out? How 'bout you show me.", objectives = "" }
WordHunterWoW_QuestEN[85948] = { title = "A Burning Journey Through Time", description = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "" }
WordHunterWoW_QuestEN[85949] = { title = "A Frozen Journey Through Time", description = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "" }
WordHunterWoW_QuestEN[85960] = { title = "Side Gig: Lost in the Sauce", description = "Some of the workers forced by the Darkfuse to work the blood fields never made it home.\n\nWe've got reports that they might be lost in whatever the \"Unseeming\" is. Apparently it's got something to do with the big blood puddles?\n\nSounds like a job for someone more expendable--I mean experienced, than me.", objectives = "" }
WordHunterWoW_QuestEN[85961] = { title = "Moving the Pawns", description = "There is a small island to the northwest of here, called Overlook Zo'Shuul. My scouts have been searching for a way into Manaforge Omega, where we must stop the return of the All-Devouring.\n\nIf we are fortunate, the scouts have already found a safe pathway inside.", objectives = "" }
WordHunterWoW_QuestEN[85962] = { title = "Side Gig: Unseemly Reagents", description = "There's all sorts of weirdness going on in the Ringing Deeps thanks to all that Black Blood still lying around.\n\nAnd where there's madness and mutation, there's opportunity!\n\nGet out there and see what sort of horrific but potentially lucrative reagents you can scrape up.", objectives = "" }
WordHunterWoW_QuestEN[86151] = { title = "Faceless Mask of the Burned Bridge", description = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", objectives = "" }
WordHunterWoW_QuestEN[86152] = { title = "Faceless Mask of the Daredevil", description = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", objectives = "" }
WordHunterWoW_QuestEN[86153] = { title = "Faceless Mask of the Dark Imagination", description = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the voids' domain. In these pursuits, these magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", objectives = "" }
WordHunterWoW_QuestEN[86154] = { title = "Faceless Mask of the Pained", description = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", objectives = "" }
WordHunterWoW_QuestEN[86155] = { title = "Faceless Mask of the Long Night", description = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", objectives = "" }
WordHunterWoW_QuestEN[86156] = { title = "Getting Involved", description = "You. Do that again. Could be good stuff we ain't seen yet. \n\nGet those caves open an' see what's in there!", objectives = "" }
WordHunterWoW_QuestEN[86177] = { title = "Side Gig: The Tides Provide", description = "You look like the type who ain't shy to get your hands dirty. Up for a little treasure hunting?\n\nWord has it that a ship exploded not far off the Kaja'Coast. Go to shore and see what the tide's brought in.\n\n\"Finders keepers\" is one of the foundational tenets of goblin society, after all.", objectives = "" }
WordHunterWoW_QuestEN[86178] = { title = "Side Gig: Cleanin' the Coast", description = "It's time for the Venture Company to earn a lil' good faith.\n\nWe're lookin' to hire some efficient workers like yourself to clean up the Kaja'Coast.\n\nCould you help us kill some of the kaja'mentals that have gone... well, mental out there? We'll toss some competitive compensation your way.", objectives = "" }
WordHunterWoW_QuestEN[86179] = { title = "Side Gig: Lucky Break's Big Break", description = "You know the Lucky Break Mines over on the Kaja'Coast? Settin' those up was kind of a rush job. Darkfuse didn't exactly give Venture a whole lotta time to reinforce the place.\n\nLong story short, there's a good chance the mines might collapse if we don't fix 'em up. That wouldn't be good news for anyone, especially not my wallet.\n\nCould you head over and rig up some support beams in the mines? That should do the trick for now.", objectives = "" }
WordHunterWoW_QuestEN[86180] = { title = "Side Gig: Infested Waters", description = "So, my workers were supposed to be loadin' up some kaja'mite over in Zuldazar, but apparently the transport got upended and a shark swallowed the whole crate.\n\nI tried submittin' an insurance claim, but they ain't buyin' it. So we got no choice but to get that kaja'mite back ourselves.\n\nDown for a little shark huntin'?", objectives = "" }
WordHunterWoW_QuestEN[86182] = { title = "Ghost Buster", description = "I have been working on the Oasis console and I believe I am ready for the next step. It will involve destruction, so naturally I thought of you.\n\nI need you to use a phase conduit to shift into the Untethered Space of K'aresh and retrieve the essence of the ghostly slatebacks. I will explain more when you return.", objectives = "" }
WordHunterWoW_QuestEN[86183] = { title = "The Power of Gods", description = "Today, we create life. \n\nAssuming my calculations are correct--which they are--we can use the essence you gathered along with the data we have collected to create new slatebacks.", objectives = "" }
WordHunterWoW_QuestEN[86184] = { title = "Diminishing Returns", description = "The machine has its uses, but the slatebacks must start breeding so they can sustain themselves. Thus far, they have shown no inclination to do so.\n\nTake this device and use it to collect the slatebacks for testing. Om'talad will review the data.", objectives = "" }
WordHunterWoW_QuestEN[86185] = { title = "Running Free", description = "Been talkin' to Ve'nari and Om'talad--trying to help the slatebacks get together. \n\nApparently slatebacks used to display virility by engaging in races. \n\nChallenge the slateback alpha to a race. At worst, you'll both get some exercise. At best, it will increase the likelihood of a successful pairing.", objectives = "" }
WordHunterWoW_QuestEN[86186] = { title = "The Super Sniffer", description = "It appears the slatebacks are not secreting the correct pheromones, resulting in them not breeding. \n\nWe believe this is a side effect of the stasis. The technology was never tested for such an extreme length of time. Until now. \n\nHemet tells me there are creatures called niffen in Azeroth that have expertise in this research. Bring me one from Azj-Kahet. You can use my portal to quickly get there.", objectives = "" }
WordHunterWoW_QuestEN[86187] = { title = "The Smallest Possible Effort", description = "You're a shrewd negotiator, {name}. That's good fun! I'll start packing. You go get some bug bits for me, okay?", objectives = "" }
WordHunterWoW_QuestEN[86188] = { title = "More-shrooms", description = "Poor Gharrli needs to be set up while I'm away. The mushrooms you get will help with that.\n\nGet eight of them for now. We'll worry about the last one later!", objectives = "" }
WordHunterWoW_QuestEN[86189] = { title = "Fungal Invasion", description = "I'm sending you somewhere a lil scary, but I'm sure you can handle anything that comes your way!\n\nMind clearing up some of the creatures so it'll be easier for Gharrli to gets the ingredients in the future?", objectives = "" }
WordHunterWoW_QuestEN[86190] = { title = "One Mushroom to Rule Them All", description = "We've been working on a new scent to delight the locals, but we have one more ingredient we need. \n\nIt's a rare mushroom from Pillar-nest Vosh. Get that, and Gharrli can finish the fragrance while I'm away!", objectives = "" }
WordHunterWoW_QuestEN[86191] = { title = "Smell Ya Later", description = "Well. That's everything, I think. I'm ready for adventure!", objectives = "" }
WordHunterWoW_QuestEN[86192] = { title = "On a Bed of Bones They Lie", description = "I was talking to Om'talad over there. Apparently, slatebacks used to gather bones for birthing nests, which is kinda funny on account of them being herbivores! \n\nNormally they get bones from dead animals, but we don't have any in the eco-domes. Can you gather some bones from creatures outside the Oasis for me? They'd appreciate it, and so would I!", objectives = "" }
WordHunterWoW_QuestEN[86193] = { title = "Life for Life", description = "We're too late! The ritual is self-sustaining. It'll draw in more power until it overloads the machine. Tazavesh, the eco-domes--nothing will be safe if the failure cascades. \n\nIf we remove the infusers, the energy should dissipate before it can cause any harm. It's too powerful though. It will tear you apart if you try to get close, and I'm not strong enough to do it alone...\n\nUnbind me. I'll wrap you in my energy. That should be enough to let you get close to the machine.", objectives = "" }
WordHunterWoW_QuestEN[86194] = { title = "The Scent of Love", description = "I was out and about checking on these slatebacks of yours, and your broker friends are wrong!\n\nThe slatebacks are giving off the smell of love, but it's just not strong enough to overpower all this dry air on K'aresh. Not yet anyway! I whipped up a batch of pheromones that should fix them right up!\n\nTake this sprayer and douse the slatebacks. That'll get things started!", objectives = "" }
WordHunterWoW_QuestEN[86195] = { title = "Slateback Soccer", description = "Oh my. I never thought I would see the day. A newly born slateback!\n\nI have been running standard non-invasive medical tests. However, I also need a test of its coordination. I have been noticing it chasing this ball around. Perhaps you could throw it and observe the results?", objectives = "" }
WordHunterWoW_QuestEN[86196] = { title = "Give Me Fuel", description = "Thank you for coming, {name}.\n\nThere are many dangers we face when attempting to terraform K'aresh, not the least of which is attracting creatures that see the domes as convenient energy sources.\n\nEco-Dome: Springhost is plagued with them. I have a plan to remedy this, but I could use your help preparing.", objectives = "" }
WordHunterWoW_QuestEN[86200] = { title = "Give Me Fire", description = "Now we need to process this firebud pollen into fuel. And with this fuel, the downfall of these pests will be assured.", objectives = "" }
WordHunterWoW_QuestEN[86201] = { title = "Watch Me Make These Bugs Expire", description = "Now that we've processed this firebud pollen, we can bring some flame to bear against our pests in Eco-Dome: Springhost.", objectives = "" }
WordHunterWoW_QuestEN[86203] = { title = "Operation: Floodgate", description = "My sources report that Darkfuse forces have infiltrated the Waterworks down in the Ringing Deeps. They have seized the power generators there and are rerouting the electricity somewhere else.\n\nWe do not know their directive, but I am not keen to find out.\n\nDismantle their operation and I will see that you are adequately rewarded.", objectives = "" }
WordHunterWoW_QuestEN[86204] = { title = "Liberation of Undermine: The House Loses", description = "Gallywix has been a stain on Undermine since he forgot where he came from.\n\nGallywix's always been steppin' on the little guy--greed and always looking for the \"next best thing\" is just makin' him step even harder. Seeking power just for its own sake? Forget that! The power lies with the people.\n\nLet's bring Gallywix some swift justice, {name}.", objectives = "" }
WordHunterWoW_QuestEN[86261] = { title = "Homeward Bound to Safer Shores", description = "<Upon seeing you walk into camp this dirty, matted dog perks up. His tail wags when he sees the familiar face of the person who found his favorite toy.\n\nThe faded tag around its neck reads: \"The Duke.\"\n\nHe seems to have been here since the Kul Tirans disappeared and has somehow survived the isle's many perils.\n\n\"The Duke\" looks at you longingly and nuzzles your hand, seeking affection.>", objectives = "" }
WordHunterWoW_QuestEN[86271] = { title = "Sanity's Rest", description = "Looks like another one down the hatch, huh? \n\nI'm tellin' ya, these Black Blood dig sites are chewin' up workers faster than I can hire 'em! Every day, one of my guys goes down with the shakes, sproutin' nonsense about seein' tentacles in the dirt... \n\nTake 'em to see my guy, Stitchoaf, in the cave over there. He's brewin' up some kinda \"cure.\" \n\nSee if he can't help this poor guy out.", objectives = "" }
WordHunterWoW_QuestEN[86272] = { title = "Counteracting the Black Blood", description = "Black Blood? Nasty stuff. Glad I got this mask here. Nobody should be workin' in that mess.\n\nIt gets inside ya, messes with ya head. Some folks get dizzy, seein' things that ain't there. Some even sproutin' strange scales. Makes me itch thinkin' about it.\n\nAn' there ain't no cure. Best we can do is ease the pain an' maybe help the symptoms a bit.\n\nI got a \"cure\" brewin'. It's just soup, but they don't know that. \n\nIt's almost \"done,\" but it could use some flavor.", objectives = "" }
WordHunterWoW_QuestEN[86273] = { title = "Visit to the Shop", description = "That's all we can do for now.\n\nBut if you really wanna help us fix all this, you ought to talk to our local engineer--uh, Tricksy... or maybe Trixxy. \n\nShe's got her workshop set up further down in the cave, and Benny's got her tinkerin' away day and night on some kind of... \"permanent solution.\" \n\nOdd, but she's sharp as a blade. If anyone's got a chance at makin' people safe down here, it's her.", objectives = "" }
WordHunterWoW_QuestEN[86274] = { title = "Automation Solution", description = "As you have probably figured out, Black Blood exposure is bad for your health. And that's a problem for our operation. \nWe can't keep replacin' our workers. It's expensive, and it ain't ethical.\n\nSo! What's the solution? Replacin' our workers with my fully-automated bots.\n\nThese beauties don't get affected by Black Blood exposure. They just dig and haul--precision, efficiency, an' no more sick workers!\n\nI just need more scrap to patch 'em up. You in?", objectives = "" }
WordHunterWoW_QuestEN[86275] = { title = "Bug Exterminator Needed", description = "Well, if ya really wanna help...\n\nWe're safe in this cave from the Black Blood--or we were until it was crawlin' with nasty bloodfeasters.\n\nThe ugly little creeps always had a taste for blood--but now they're gonzo for Black Blood! I got a hunch they're spreadin' Black Blood poisonin' when they bite us.\n\nI can't work like this. Each time I see one in a scrap pile, I wanna scream. They're gross, an' I don't wanna get bit an' start seein' things.\n\nStomp 'em flat so we can keep safe an' keep workin'!", objectives = "" }
WordHunterWoW_QuestEN[86276] = { title = "Out in the Fields", description = "If Trixxie has those bots ready, then all we gotta do is mark where they needa work. \n\nHead out, fire a flare, and deploy those tin cans--an' see if they actually, yanno, work.\n\nWatch for glitchy servos, smokin' coolant vents... You know the drill. \n\nIf they start doin' their work? Great. \n\nIf not, well... I might be callin' some workers back in to clean up.", objectives = "" }
WordHunterWoW_QuestEN[86277] = { title = "\"Worm\" Food No More", description = "We've got the bots workin' the fields, but there are still flesh-an'-blood workers out there.\n\nThey need to be able to get back here safely, an' they can't do that with a giant, slobberin' \"worm\" doggin' their steps 'cause it's got a taste for goblin meat.\n\nSo, here's the job: I don't want that thing scared off, I want it gone. Go out there, track down that overgrown \"earthworm\", and make sure it dies. \n\nDon't hold back--I want guts everywhere. Payback for all the goblins it's had for lunch.", objectives = "" }
WordHunterWoW_QuestEN[86297] = { title = "Morale Reflects Leadership", description = "Undermine swallows everything that's good. Now it got Laslo. We need to find who's in charge now and figure out how to keep 'em safe. I think I know where to start askin'.", objectives = "" }
WordHunterWoW_QuestEN[86327] = { title = "The Tempest Fields", description = "Those Wastelanders have that broker's ribbon. We must get it back or you will never be able to reach Dimensius.\n\nThey are deliciously bloodthirsty. I think we should lure them to our cause. We need an army for the coming battle, and they have the numbers for that.\n\nThe void glass lies between their camp and us. That might provide a means to manipulate--speak with the Wastelanders.", objectives = "" }
WordHunterWoW_QuestEN[86332] = { title = "Distribution of Power", description = "My people need energy to live. We can harvest it from the pylons that were set out to collect it or hunt the energy scavengers that have siphoned off what is ours.\n\nLet's gather today's meager bounty of energy and then distribute it to my people. If we are to go to war together, it will help us both to know the character of your allies.", objectives = "" }
WordHunterWoW_QuestEN[86339] = { title = "Oasis Overdrive", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[86340] = { title = "Oasis Overdrive - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[86341] = { title = "Oasis Overdrive - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[86342] = { title = "Soaring over K'aresh", description = "We've been taking the k'arrocs out for flights outside of the Oasis. Perhaps you might be interested in riding one?", objectives = "" }
WordHunterWoW_QuestEN[86348] = { title = "Fox Bane", description = "You have done well with the slatebacks. Will you do as well with the thorntails?\n\nIf we are to improve their numbers, we will need some of their astral essence to produce new ones. Procure it for me.", objectives = "" }
WordHunterWoW_QuestEN[86349] = { title = "Lapbug Essence Hunter", description = "Thorntails are known to hunt smaller creatures. If we are to increase their numbers, we should also increase the numbers of the lapbug population to compensate.\n\nGather some of their astral essence. You can use a phase conduit to get into Untethered Space.", objectives = "" }
WordHunterWoW_QuestEN[86350] = { title = "Eau de Foxy", description = "It's my favorite {race}! \n\nI've been sniffing around the Oasis and I've whipped up a batch of pheromones for those thorntails out there. Can you give them a good dose for me?\n\nLet Om'talad know when you're done--he was lookin' to do some testing too!", objectives = "" }
WordHunterWoW_QuestEN[86351] = { title = "Strike a Pose", description = "We are running low on food for the thorntails. It is odd. They should be hunting for a larger portion of their food.\n\nCan you take some pictures of them for documentation purposes? Perhaps it will shed some light on the issue.", objectives = "" }
WordHunterWoW_QuestEN[86352] = { title = "Hunting for a Good Author", description = "I am growing concerned that we may be in danger of overbalancing the ecosystem. We require a consultant. \n\nHave you read \"The Green Hills of Stranglethorn?\" I enjoyed it a great deal. The author appears to have turned from hunter to conservationist. Do not ask how I acquired this information. \n\nHowever, these are precisely the two skills I need. Retrieve him. Last I heard, he was in the Azure Span on the Dragon Isles. Use the portal to travel there.", objectives = "" }
WordHunterWoW_QuestEN[86353] = { title = "Protecting the Young", description = "These gnolls have kidnapped children from Iskaara. I was going to sneak in and rescue them, but I could use some help. \n\nLet's split up. Two sets of eyes are better than one. If you spot any kids, tell 'em to gather at this spot. Tell them Hemet sent you. They know me.", objectives = "" }
WordHunterWoW_QuestEN[86354] = { title = "A Percussive Antidote", description = "These gnolls have been corrupting the land--growing too big and throwing off the ecosystem.\n\nWe need to stop them, and let this land recover from all that decay.", objectives = "" }
WordHunterWoW_QuestEN[86355] = { title = "Using the Whole Animal", description = "K'aresh, eh? Sounds a bit like Netherstorm.\n\nI've been staying with the tuskarr for a while an' learning what I can from 'em. I was supposed to gather meat for the evening meal. If you can do that, I can start packing.", objectives = "" }
WordHunterWoW_QuestEN[86356] = { title = "Sustainable Harvesting", description = "I'd like to repay the tuskarr's kindness for hosting me. They have some repairs that need doing.\n\nCan ye gather some wood for them? They can handle the repairs themselves--they just need a bit of help gatherin' the materials.", objectives = "" }
WordHunterWoW_QuestEN[86357] = { title = "Time for Noms", description = "The local ottuks have a symbiotic relationship with the tuskarr, and it's feeding time.\n\nCan ye put out some of the meat ye gathered for them?", objectives = "" }
WordHunterWoW_QuestEN[86358] = { title = "Any Old Excuse", description = "This'll be the hardest task for ye yet.\n\nThe ottuk pups have to get acclimatized to touch. I... I need ye to go pet them. \n\nHard work, but it has to be done.", objectives = "" }
WordHunterWoW_QuestEN[86359] = { title = "Return to K'aresh", description = "Right then. I'm ready to go. How do we get there?", objectives = "" }
WordHunterWoW_QuestEN[86360] = { title = "Fantastic Ms. Fox", description = "The thorntails aren't hunting like they're supposed tae?\n\nVe'nari said that lapbugs aren't their normal prey. We'll need to teach the matriarch how to hunt them ourselves!", objectives = "" }
WordHunterWoW_QuestEN[86361] = { title = "Are You Kitting Me?", description = "We need to ensure that the thorntail kits' reflexes are sharp so they are effective hunters when they grow up.\n\nPlease take this ball and have a kit chase it. For scientific purposes, of course.", objectives = "" }
WordHunterWoW_QuestEN[86362] = { title = "What Does the Fox Dream?", description = "I'd like to get some medical data on how the thorntails are doing. Please gather some blood samples for me.\n\nUse these to tranquilize the creatures. There should be more than enough blood for sampling on the darts when you retrieve them.", objectives = "" }
WordHunterWoW_QuestEN[86363] = { title = "The Better Part of Valorstones", description = "It's been many months since we arrived in Dornogal and there's still more to learn of Valorstones. It turns out they can be found beyond Azeroth! This discovery opens up entirely new avenues of research.\n\nWith new research comes a need for new supplies. Bring me some, and we'll help upgrade your gear to new heights.", objectives = "" }
WordHunterWoW_QuestEN[86364] = { title = "Crests from the Ether", description = "Wonderful. Valorstones are capable of upgrading lower-level equipment on their own. \n\nThat being said, Valorstones can only do so much. More powerful equipment will also require Ethereal Crests to upgrade to their full potential. These crests are rewarded through many different activities. Ethereal Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Weathered Ethereal Crests, and we can help you upgrade some gear further.", objectives = "" }
WordHunterWoW_QuestEN[86365] = { title = "Crest Transmutation", description = "My friend, these Crests are magnificent. It looks like they can be transmuted into different tiers!\n\nIf you find yourself no longer in need of a lower-tier Crest, then I can transmute them to be more powerful. I can also transmute Crests into a weaker tier.\n\nLet's practice the transmutation process. Here's a few Carved Ethereal Crests. Speak to me and I can transform them into Weathered Ethereal Crests for you.", objectives = "" }
WordHunterWoW_QuestEN[86368] = { title = "[DNT] Repeatable - Camp 001", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[86388] = { title = "Spark - Template", description = "", objectives = "" }
WordHunterWoW_QuestEN[86392] = { title = "Foxy Footwork", description = "Your efforts in teaching the matriarch to hunt have been too effective, it seems. Several broker guards have been attacked recently. \n\nSince you caused this issue, I need you to solve it. Best the thorntail matriarch in a fight. The rest of the thorntails will back down once their leader is humbled.", objectives = "" }
WordHunterWoW_QuestEN[86406] = { title = "[DNT] Camp Assignment", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[86408] = { title = "My Hole in the Wall", description = "Never thought when I was lookin' for security I'd get some kinda bona fide hero. I can see why rumors about you spread so quickly. You like helpin' people, don'tcha?\n\nLook I don't wanna get all sappy or nothin'. It's just... What you did for everyone... \n\n<Mama Keara shakes her head and regains her composure.>\n\nAnyways. A deal's a deal. Sign your name on the apartment log over there and you'll be an official Barrelbottom resident. I'd say you've definitely earned it.", objectives = "" }
WordHunterWoW_QuestEN[86417] = { title = "Ready Check", description = "We've done what we can here, {name}. Now we just have to hope it'll be enough.\n\nMaybe Gazlowe's got a plan. Maybe now we're ready to face down Gallywix. Let's formulate our next steps. I enjoy a bit of formulation from time to time.", objectives = "" }
WordHunterWoW_QuestEN[86448] = { title = "Piecing Things Together", description = "<Elise Starseeker should be able to piece these Bounty's Remnants back together.>", objectives = "" }
WordHunterWoW_QuestEN[86456] = { title = "An Elegy for a Silent World", description = "<The crystal you are holding vibrates faintly in your hand. The energy it emits feels like it is holding your hand, trying to reach out and never let go--like it wants you to hold it, to bring it to safety. You can hear a faint song in the back of your mind--a song of fear, confusion, and longing for life.\n\nMaybe Ve'nari would know more about it?>", objectives = "" }
WordHunterWoW_QuestEN[86457] = { title = "A Lullaby of Hope", description = "{name}, do you know what this is?\n\nIf I am right, this crystal is the essence of my world, K'aresh. I've spent much of my capital preserving some bit of K'aresh through the eco-dome project. But this...\n\nI do not wish to assume anything before verifying if it is true.\n\nPlace down the shard, and let's see what we can find.", objectives = "" }
WordHunterWoW_QuestEN[86458] = { title = "A Song for Our Future", description = "There is a site, Eco-Dome: Al'dani, which I have kept hidden. It is built on the remains of one of our most sacred places with a powerful connection to K'aresh. It is the site of our greatest triumph of the project. This is the place where we can take the Worldsoul's essence so it can survive.\n\nThis is also the eco-dome where Soul-Scribe and her Wastelanders are attacking.\n\nClear the way for me one last time, {name}. For K'aresh to survive, we need both the dome and Soul-Scribe intact.", objectives = "" }
WordHunterWoW_QuestEN[86461] = { title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[86462] = { title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "" }
WordHunterWoW_QuestEN[86469] = { title = "A Stromgarde Tour", description = "The very walls of Stromgarde have stories to tell, if only you have the patience to listen.", objectives = "" }
WordHunterWoW_QuestEN[86470] = { title = "Fearin's Version", description = "I need someone to deliver these requests to people around the city. We've been shorthanded and I haven't gotten around to distributing this bunch.\n\nAs my newest deputy, this responsibility is now yours!\n\nMost of these are simple and straightforward. Requests for supplies and such for the Stromic army.\n\nJoseph is another matter. He's been inciting the populace with inflammatory rhetoric. He needs to stop or we will have to arrest him. We can't afford another riot breaking out right now.", objectives = "" }
WordHunterWoW_QuestEN[86481] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[86482] = { title = "A Lifeline", description = "<The snapdragon barely moves as you approach. It is clearly weak and seems much smaller than it should be. \n\nPerhaps Zexel Fingersnap has something for sale that could help get it back up on its feet?>", objectives = "" }
WordHunterWoW_QuestEN[86483] = { title = "Snap To It", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. \n\nNot only has it grown bigger overnight, but its scales have changed to a seaweed-green color similar to the Kaja'cola-braised meat you fed it.\n\nBetween it's talons lie morsels of meaty rations it has stolen from nearby invading forces. The snapdragon looks at you expectantly.\n\nPerhaps you can bring it more meaty rations by slaying the invading forces on the island.>", objectives = "" }
WordHunterWoW_QuestEN[86484] = { title = "Temper Like A Tempest", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation. \n\nNot only has it grown bigger overnight, but its scales have changed color from the meat you fed it yesterday.\n\nBetween it's talons lie the remains of a sea creature from the last Seafury Tempest. The snapdragon looks at you expectantly.\n\nPerhaps by venturing into the Seafury Tempest and slaying creatures there you can bring it more meat.>", objectives = "" }
WordHunterWoW_QuestEN[86485] = { title = "A Loyal Friend", description = "<The snapdragon seems to recognize you as you approach, its ear fins wiggling with anticipation.\n\nIts massive, lithe body unfurls as it stands before you as a fully grown adult. It stares you down, clacking it's massive jaw gently as if it's deciding something.\n\nIt seems to wait for you to make the first move.>", objectives = "" }
WordHunterWoW_QuestEN[86486] = { title = "Hungry, Hungry Snapdragon", description = "<The snapdragon seems to recognize you as you approach. Its ear fins wiggle with anticipation. \n\nIt is hungry again and looks at you expectantly. It seems to want meat and doesn't seem to care where it comes from.>", objectives = "" }
WordHunterWoW_QuestEN[86491] = { title = "Dastardly Duos! It's on!", description = "Hello, fight fans. The world's meanest villains are teamed up and back for revenge! They have returned, this time as Dastardly Duos!\n\nMeet me in Dornogal, at the foot of Contender's Gate and sign up to face the Dastardly Duos. Beat down these bosses one more time. Relive the dream!\n\n-Vinnie Sweets", objectives = "" }
WordHunterWoW_QuestEN[86493] = { title = "LFGDungeons - Timewalking \"Heroic\" Random - 1st", description = "", objectives = "" }
WordHunterWoW_QuestEN[86494] = { title = "LFGDungeons - Timewalking \"Heroic\" Random - Nth", description = "", objectives = "" }
WordHunterWoW_QuestEN[86495] = { title = "The Reshii Ribbon", description = "During the Devouring War, I witnessed the horrific results of the All-Devouring's presence. A mortal being cannot approach him at the manaforge. He is the entropy of the end, and you are just flesh.\n\nXal'atath knows rituals from across the Great Dark Beyond. With the power of the Reshii Ribbons, she was able to transform the K'areshi so they could withstand Dimensius.\n\nAlleria will not like this plan. You must convince her!", objectives = "" }
WordHunterWoW_QuestEN[86496] = { title = "An Ordered Design", description = "<Bargus holds up a tiny splinter of golden crystal.>\n\nMuch like the radiant remnants found by the Arathi within Hallowfall, the Siren Crystal appears to be effecting the surrounding geological matrix of the island.\n\nUnlike our goblin compatriots, I don't recommend harvesting the larger shards we've seen around the isle, lest we disturb the fragile caverns beneath us or offend the Arathi. \n\nBut these tiny splinters are worth investigating.\n\nBring me a sizable portion. For... experimental purposes.", objectives = "" }
WordHunterWoW_QuestEN[86503] = { title = "Who are the Dastardly Duos?", description = "Great question! Here's how to find out: Talk to Xyggie Marou and sign up to fight the Dastardly Duos.\n\nAnd because you're new to this, let me give you a list of \"Dastardly\" tasks to do while you're in there!\n\nGood luck! Maybe I'll see you on the other side.", objectives = "" }
WordHunterWoW_QuestEN[86509] = { title = "Friend or Fiend", description = "Despite that spirited display, I'm inclined to help you. After all, what's a little violence between friends? \n\nAnd since we're friends, I'll let you in on a secret: shutting down the storm is only possible from inside the Nexus-Points. Of course you can't just walk in--you need the Mantle of Predation.\n\n<Decimus seems to savor the words.>\n\nDo I have your attention? Let's shake the dust off and discuss this somewhere... civilized. Meet me at my estate.", objectives = "" }
WordHunterWoW_QuestEN[86510] = { title = "Domus Penumbra", description = "It seems we all wish to stop the Voidstorm. Common ground--a rare thing here. I'll even tell you how to do it, and all I ask in return is for you to let me enjoy the show.\n\nBut you must be tired. Show yourself around, and help yourself to the amenities. Then we will continue our discussion.\n\nDon't take too long. There is much to see, and the storm rages on.", objectives = "" }
WordHunterWoW_QuestEN[86511] = { title = "Edge of the Abyss", description = "I don't trust Decimus any more than the rest of the beasts here. I do trust that they only serve themself. Seems having Xal'atath as a master isn't to their taste. We can turn one foe against another. Even Lothraxion would agree if he weren't so stubborn.\n\nIf this Mantle of Predation will let us stop the storm, then it's our best shot. A troop of ren'dorei have been scouting the Obscurion Citadel. We'll meet with them and see what they've learned.", objectives = "" }
WordHunterWoW_QuestEN[86512] = { title = "The Harvest", description = "Two sigils--you'll need both to open Terminas's vault and claim the Mantle.\n\nThe first belongs to Torentia, petty ruler of this sad trench. Too ambitious for Terminas to bring her into his inner circle, too cowardly to strike out on her own. So here she cowers behind an unbreakable shield of Void.\n\nShe's terrified of losing her already meager holdings. What a pity. Slaughter your way through the trench. The potential emergence of a new apex predator is something she won't ignore.", objectives = "" }
WordHunterWoW_QuestEN[86513] = { title = "Face the Tide", description = "I expected an army, but this is chaos--beasts pouring from the Void, gorging themselves, taking captives for sport.\n\nOur mission is to claim the Mantle, but we can't ignore this. Sooner or later, these forces will be loosed against Silvermoon. Any blows we strike now will save lives down there, {name}.\n\nStarve their forces, stem the flow of beasts from the Void, and free every captive they've abducted.", objectives = "" }
WordHunterWoW_QuestEN[86514] = { title = "Lady of the Pit", description = "For all their power, these domanaar still behave like beasts. That's good for us. Wolves try to avoid each other, but if one threatens another's territory, they'll fight to the death. \n\nBy now, I think you've more than proven that you're a threat. Torentia can't back down if you challenge her--it would go against her nature.\n\nSo take the fight to her, slay her, and claim her sigil.", objectives = "" }
WordHunterWoW_QuestEN[86515] = { title = "Hollow Hunger", description = "Alleria's judgement is clouded. She's spent too much time steeped in Void. I've prosecuted campaigns across the cosmos. Casualties are inevitable. I could not command if the loss of every soldier broke my will.\n\nWe have the information we need: the location of the sigil bearer. The fiends whisper of a domanaar named Severum. Slay him and take his sigil, then we can be rid of this place.", objectives = "" }
WordHunterWoW_QuestEN[86516] = { title = "All Become Prey", description = "Lothraxion's acting like we have an army, but a single ultradon will tear through us if we're caught off guard. We need to be smarter.\n\nI've watched the beasts of this world: studied them, tracked them, killed them. They prey on weakness, and cull their own kind at the first sign of frailty. \n\nHarvest carrion essence from the carcasses around the citadel. Use it to mark ultradons. Other beasts will pounce, thinking they're wounded or dying. Let them tear each other apart, then clean up what's left.", objectives = "" }
WordHunterWoW_QuestEN[86517] = { title = "Vanished in the Void", description = "\"Acceptable losses.\" I hope I never find it that easy to dismiss the deaths of friends and comrades. What use is the Light if it leaves us as callous as our enemies?\n\nSideras was nearly killed. Luckily, he escaped through a rift. Riftblade Maella led the others in a fighting retreat. Find her. Hopefully they stuck together.\n\nI can't leave Sideras--not until he's stable.", objectives = "" }
WordHunterWoW_QuestEN[86518] = { title = "The Mantle of Predation", description = "Let's move quickly. We need to steal the Mantle before Terminas returns and before Lothraxion does something rash. \n\nI understand this place grates on him, but he should know to trust my instincts. I thought we'd fought together long enough to earn that.\n\nLet's end this. Ready when you are.", objectives = "" }
WordHunterWoW_QuestEN[86519] = { title = "Abyssus, Abyssum", description = "I don't see Decimus. For all their glee at handing us over, I'd expect they'd want to watch the fight. What could be more important to a domanaar than enjoying a battle?\n\n<Alleria nocks another arrow.>\n\nAnswers can wait. Right now we need to survive.", objectives = "" }
WordHunterWoW_QuestEN[86520] = { title = "Hunt the Light", description = "There's no time. Lothraxion already has the lead. \n\nGet to Nexus-Point Xenas, {name}. We'll meet you there.", objectives = "" }
WordHunterWoW_QuestEN[86521] = { title = "Nexus-Point Xenas: Eclipse", description = "If he destroys the Nexus-Point, everyone we're fighting for could perish. I'll try to talk him down, but if I can't, if I have to...\n\n<Alleria's face clouds.>\n\nNo hesitation. We end this, one way or another.", objectives = "" }
WordHunterWoW_QuestEN[86522] = { title = "Daylight is Breaking", description = "Turalyon is busying himself with the troops. We'll need to let him know what they'll face here, tell him about Lothraxion...\n\n<Alleria shakes her head.>\n\nThank you, {name}. Even when my thoughts feel clouded, you never seem to waver. Go, give Lor'themar my report. Arator and I will brief Turalyon.", objectives = "" }
WordHunterWoW_QuestEN[86528] = { title = "A Cracked Holokey", description = "<A unique-looking ethereal device rests upon the cold ground. It bears a crack down the middle from damage in a scuffle.\n\nPerhaps Alleria will know what it is.>", objectives = "" }
WordHunterWoW_QuestEN[86530] = { title = "First, The Shells", description = "Ages ago, on a dismal world of swamp, I led the Army of the Light to a demon-infested manaforge obscured by vines and fog. My soldiers left that world in a haze of flame and smoke, the scent of burning mana and victory in the air. We will do now as we did then.\n\nWe'll begin by collecting the empty canisters they use to hold and transport fuel. The ethereals, and especially their automatons, will have them.", objectives = "" }
WordHunterWoW_QuestEN[86531] = { title = "Work Disruption", description = "The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped.\n\nPut down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.", objectives = "" }
WordHunterWoW_QuestEN[86535] = { title = "Test Run", description = "Hey, you lookin' to make a few coins?\n\nWe made a deal with the earthen to build a teleporter up in Dornogal. We get all the tourism traffic we want, and they get their pick of the finest cracked, chipped, or otherwise unsellable gemstones Undermine's jewelers can offer.\n\nI just got this end of things workin', but I haven't tested it out yet. You wanna try? If you come out the other side, my coworker Kenzi will compensate ya.\n\nWe'll say this constitutes a verbal waiver, yeah?", objectives = "" }
WordHunterWoW_QuestEN[86536] = { title = "Reliable Enemies", description = "The ren'dorei scouts report a familiar enemy upon this world: ethereals. Wretched scavengers and bandits that plague every corner of the Great Dark Beyond. The Shadowguard are the worst of them. We'll handle them.\n\nThis... thing we've taken prisoner must know what they're doing here, and much else. Press the Void's secrets from it. See that it is convinced to share what it knows, or I will employ my own methods.", objectives = "" }
WordHunterWoW_QuestEN[86537] = { title = "Network Insecurity", description = "Judging by the design and the strength of this holokey's energy, it must be used to encrypt important communications.\n\nLet us try this lead. See if it's compatible with any of the consoles you find around the refinery. Given the damage it's taken, we'll have to piece together whatever scraps of information we can.", objectives = "" }
WordHunterWoW_QuestEN[86538] = { title = "Second, The Fuel", description = "Ethereals seek corners of the cosmos to drain of potent nether. Arcane, Void, fel--to them, it matters only the yield. And we have a rich vein to work with.\n\nNow, slay those who possess that energy: wild arcane elementals from their pipes, or their ethereal harvesters flush with energy. We have need of it.", objectives = "" }
WordHunterWoW_QuestEN[86539] = { title = "A Naaru!", description = "I refuse to let another naaru fall to darkness.\n\nBefore our departure, the scouts reported they had found a Nexus-Point connected to this forge. If the Void's forces possess a naaru, it might be where they're keeping it.\n\nI will prepare the manacells as we conduct the search. Come.", objectives = "" }
WordHunterWoW_QuestEN[86540] = { title = "Third, Blow It Up", description = "The manacells have been prepared. Set them near the pylon and its supporting machinery. When it's done, I will command Alleria to ignite them from afar.\n\nBut we cannot proceed until the naaru has been brought to safety. Go now and I will make certain of her freedom.", objectives = "" }
WordHunterWoW_QuestEN[86541] = { title = "Just In Case...", description = "Perhaps Lothraxion will be able to bring that shield down on his own. Or perhaps he is a pompous blowhard.\n\nThe Devouring Host offers its trusted soldiers fragments of a relic that can override any ethereal device, including that shield. You'll need to carve quite a swath through their forces to recover enough shards.\n\nBut what do I know? I am merely unworthy voidspawn.", objectives = "" }
WordHunterWoW_QuestEN[86542] = { title = "Flicker in the Dark", description = "We're dawdling! There's no time to waste!\n\nGet that shield down, now! T'era's anguish tears at my soul!", objectives = "" }
WordHunterWoW_QuestEN[86543] = { title = "Magisters' Terrace: Homecoming", description = "We know there's land inside the Voidstorm, through its massive portal. If we can reach it, we can take the fight to Xal'atath.\n\nI have found the key. It is a relic known as the Cynosure of Twilight. For ages, it has mystified us by revealing unreachable pathways to infinite unknowns. \n\nMy research tells me I can use it to open a path to the storm. \n\nThere's just one problem: it's in Magisters' Terrace. And I'm not exactly... in their good graces, at the moment.", objectives = "" }
WordHunterWoW_QuestEN[86544] = { title = "Post-Mortem", description = "We all bear a heavy burden in this place. I feel myself slipping towards hopelessness. But we haven't failed until we refuse to stand back up. I know my mother will collect herself. But the others need to know this fight isn't over. \n\nSpeak with Hieron. He and the other scouts should have information. We can start there.", objectives = "" }
WordHunterWoW_QuestEN[86545] = { title = "The Light's Brand", description = "No! {name}, we have to stop them! Lothraxion's boiling temper risks everything! That he chooses now of all times, when my mother is out of commission...\n\nThere's no time. We have to go!", objectives = "" }
WordHunterWoW_QuestEN[86549] = { title = "No Fear of the Dark", description = "Against all odds, we made it. \n\nI can open a way into the storm, but it will be a tenuous connection. We can only get a small team through the portal. \n\nWe have no idea what awaits us on the other side. We must be prepared. \n\nI can use the Cynosure to bind us to Magisters' Terrace. If we need a quick escape, I can bring us back there. \n\nCome--help me calibrate this spell.", objectives = "" }
WordHunterWoW_QuestEN[86555] = { title = "Undermine Benefactor", description = "", objectives = "" }
WordHunterWoW_QuestEN[86556] = { title = "A Shattered Journey Through Time", description = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "" }
WordHunterWoW_QuestEN[86557] = { title = "A Matter of Strife and Death", description = "Ha! A distant realm, crawling with vicious evil monsters? Just like old times.\n\nAlleria, Turalyon, and I faced a thousand years of war with demons in the far-flung realms. It is as simple a solution now as it was then. \n\nKill or be killed.", objectives = "" }
WordHunterWoW_QuestEN[86558] = { title = "Save a Piece of Mind", description = "The Void here. It is like nothing else. Surely you can feel it, too? The overwhelming power...\n\nWe must do something to stabilize the area. I'm barely able to keep our escape route from imploding, and the rest of our scouts... I can only hope they can hold it together.\n\nThe ren'dorei know what to do. They will place Shadestar Loci to protect this area, but will need your help activating them.", objectives = "" }
WordHunterWoW_QuestEN[86559] = { title = "The Far, Far Frontier", description = "We have secured this location. Some void elves can make this into a proper camp.\n\nThere must be some weakness we can exploit to stop the storm. We must bring my army here to mete out justice to Xal'atath's armies!\n\nJoin me and young Arator. Let us see what we can gather from this place across the horizon.", objectives = "" }
WordHunterWoW_QuestEN[86560] = { title = "A Shrouded Journey Through Time", description = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "" }
WordHunterWoW_QuestEN[86561] = { title = "A Strange, Different World", description = "I don't know the purpose of these towers, only that they are called Nexus-Points and they thrum with Void power. We must get more information. \n\nThe domanaar use some kind of Void-infused metal on the beasts here to add them to armies of the Devouring Host. They call it shadowgrafting.\n\nIt empowers them, but also influences their minds.\n\n<Alleria smiles wryly.> \n\nWhat power doesn't? \n\nI have a plan for it. With you here, I can finally act on it.", objectives = "" }
WordHunterWoW_QuestEN[86562] = { title = "Dancing with Death", description = "We may be a small strike team, but we are strong. We have you, after all. \n\nThere is no need to move with complete stealth. We must cut a path to the domanaar here. \n\nTake down the strongest enemies you can find. We will join you in the fray.", objectives = "" }
WordHunterWoW_QuestEN[86563] = { title = "A Savage Journey Through Time", description = "The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "" }
WordHunterWoW_QuestEN[86564] = { title = "A Fel Journey Through Time", description = "A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing.\n\nWhile its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "" }
WordHunterWoW_QuestEN[86565] = { title = "No Prayer for the Wicked", description = "Alleria has a plan to use this shadowgrafting material to capture that domanaar for information. \n\nBut what good is information given by evil? I've fought countless demons and every one of them was a liar.\n\n<Lothraxion scowls.> \n\nLet us follow her plan, for now. Do what she asks with this metal, then slay the domanaar's pet beast. \n\nOnce we speak with this vile creature, I will decide how long it lives.", objectives = "" }
WordHunterWoW_QuestEN[86575] = { title = "Rocket Roll", description = "That scrap was just what I needed. An' now without those bloodfeasters givin' me the heebie jeebies, I can get these bots officially rolled out.\n\nWhile I finish up here, why don't you go tell Benny the good news?\n\nI'm sure he'll wanna deploy 'em right away!", objectives = "" }
WordHunterWoW_QuestEN[86587] = { title = "To Maldraxxus", description = "Rays once soared through the skies of K'aresh. While their void-touched descendants are in the skies outside the Oasis, we have no surviving specimens that have not been void-touched.\n\nHowever, I know of a location where we can procure a similar creature that should inhabit the same part of the ecosystem: Maldraxxus in the Shadowlands. Take my portal, and find the creatures for me.", objectives = "" }
WordHunterWoW_QuestEN[86588] = { title = "Ritualistic Murder", description = "The local ritualists are causing problems for the necrorays. Specifically, plague problems.\n\nIf you kill them, it should lessen the issues for the necrorays.", objectives = "" }
WordHunterWoW_QuestEN[86589] = { title = "A Plague a Day Keeps the Doctor Away", description = "The ritualists have been testing a new plague out on our poor necrorays. This is abominable... That's my job!\n\nBring me some samples of deceased rays and I should be able to concoct a cure for the ones that haven't perished.", objectives = "" }
WordHunterWoW_QuestEN[86590] = { title = "I Don't Even Work Here", description = "It's good you are here, apprentice! I came to gather the essences from the local rancor. They are wonderful for adding just that little extra spice to a plague.\n\nBut now that you are here, I can have you gather them instead! What an excellent learning opportunity for you!", objectives = "" }
WordHunterWoW_QuestEN[86591] = { title = "A Poor Imitation", description = "This is Vorax's work. He was once my apprentice, just like you!\n\nHe's trying to replicate my work? Flattering, but sloppy. I'll work on a solution for you, apprentice, while you work on a solution for him.", objectives = "" }
WordHunterWoW_QuestEN[86592] = { title = "Get Your Jabs", description = "If these rays are to travel, we should inoculate them first.\n\nWhat a good opportunity for you to learn about administering anti-plague, apprentice! It's not something that happens here very often.", objectives = "" }
WordHunterWoW_QuestEN[86593] = { title = "To the Oasis", description = "I suppose you will be heading back now?\n\nIt has been a true joy to work with you, apprentice. I hope we will see each other soon. I'll have some new experiments for you to help me out with. Please do take care of the necrorays! I hope they enjoy their new home.", objectives = "" }
WordHunterWoW_QuestEN[86594] = { title = "A Cultured Palette", description = "We're trying to figure out what these rays eat. \n\nI've gathered some options. Can ye put them out? I'll watch for responses.", objectives = "" }
WordHunterWoW_QuestEN[86595] = { title = "Custodial Duties", description = "Seems like these rays slough off some gunk as they move. It's congealin' and makin' a mess!\n\nVe'nari sent over this vacuum device to help out. Can you clean things up while yer out and about?", objectives = "" }
WordHunterWoW_QuestEN[86601] = { title = "Triple Twenty", description = "Tag the necrorays with these darts. It'll monitor their location and health. It also injects a pain killer so the necrorays don't even notice it.\n\nThese brokers have some incredible inventions!", objectives = "" }
WordHunterWoW_QuestEN[86602] = { title = "Medical Checkup", description = "You said your friend de-plagued those necrorays, but we need to see if the other animals are picking up anything else from them.\n\nCan ye go and collect some samples so we can check for issues?", objectives = "" }
WordHunterWoW_QuestEN[86603] = { title = "Ray-ket Ball", description = "It seems one of the necrorays you brought back was pregnant, so I have been dealing with a newborn all day. Thank you. \n\nPerhaps you would not mind testing out its reflexes for me?", objectives = "" }
WordHunterWoW_QuestEN[86604] = { title = "Dubious Intent", description = "The ooze that Hemet had you collect may be of use to us. \n\nGo and collect the ooze directly from the necrorays. You can use this tranquilizer dart to bring them within range for collection.", objectives = "" }
WordHunterWoW_QuestEN[86605] = { title = "Booster Shots", description = "After some analysis of the samples you brought back, it appears the necrorays are suffering from a vitamin deficiency. \n\nVe'nari contacted Marileth, who prepared something... and then re-prepared it after she requested he remove the plague from it.\n\nPlease gather the necrorays so we can test the initial batches.", objectives = "" }
WordHunterWoW_QuestEN[86606] = { title = "The Golden Ooze", description = "Our custodians have yet to do their daily cleanup of the necrorays' discharge. I have many buyers in Tazavesh lined up for this material. They need it urgently, so its collection falls to you.\n\nTake the vacuum device. Compensation will be provided.", objectives = "" }
WordHunterWoW_QuestEN[86607] = { title = "The Freedom of Ray-cing", description = "Those necrorays responded really well to those treatments you gave 'em! So well in fact that one of 'em is needin' to burn off some energy.\n\nWould ye be able to wear it out?", objectives = "" }
WordHunterWoW_QuestEN[86618] = { title = "License Not Required", description = "Alright. Before you go out and run somebody over let's make sure you know how to do it properly.\n\nWe'll introduce you to the car, the D.R.I.V.E. service we offer, and how to drive it in style.", objectives = "" }
WordHunterWoW_QuestEN[86621] = { title = "The Wayward Magister", description = "Magister Umbric--he's second only to Mother in mastering the Void. If anyone can help us with that storm in the sky, he's the one who can make it happen... if he can forgive the others for not listening to him in the first place. \n\nAt least Lor'themar saw reason. There's no way we can take the fight to Xal'atath without Umbric.\n\nThe forces keeping the Voidstorm at bay will only hold out so long. Let's make haste.", objectives = "" }
WordHunterWoW_QuestEN[86622] = { title = "Chance Meeting", description = "I've heard some odd rumors myself. Strange happenings to the south--but also to the east and west, and the north. Tranquillien is surrounded by enemies, it seems.\n\nSince you are so dead-set on your investigation, would you look into something for me?\n\nThere is an important report I need from one of my scouts. Check in with them, while I check over the rest of town.", objectives = "" }
WordHunterWoW_QuestEN[86623] = { title = "Appeal to the Void", description = "Kasiea... whatever you've found, you've perished for it.\n\nI won't let her work be in vain. \n\nThere's something to be found here, {name}. There are a few locations listed. Let's travel to them and try some of these theorems. The formulae may be incomplete, but perhaps we can discover what she was looking for. \n\nIt had to have been important.", objectives = "" }
WordHunterWoW_QuestEN[86624] = { title = "Rational Explanation", description = "Something just doesn't feel right about all of this. Umbric can look into the notebook, but I suspect there's something more going on here. \n\nIt couldn't hurt to ask around Tranquillien and see if anyone's heard anything odd. I'll take the north side of town, and you take the south.\n\nAnd... use your discretion, my friend. We should avoid alarming anyone for now.", objectives = "" }
WordHunterWoW_QuestEN[86625] = { title = "The Clue in the Inn", description = "Call me paranoid, you'd be correct, but I have been chased out of enough towns that I have a system.\n\nI establish a safehouse. Somewhere easily defensible, with enough materials that I can finish any delicate tasks and prepare for departure. That is the situation we find ourselves in-- we will retreat to the top floor of the inn and assess our options from there.\n\nI had shared the location with Caliea, when she was still studying with me... hopefully it serves us better than it did her.", objectives = "" }
WordHunterWoW_QuestEN[86626] = { title = "The Ransacked Lab", description = "My notes, my research... I never should have left it alone.\n\nI was just beginning to understand the Voidstorm! Everything I'd learned, torn from my hands by cultists... Were they watching the entire time? Waiting for me to turn my back?\n\nI cannot let this stop me. They can't have destroyed everything. Perhaps there's enough here to salvage.", objectives = "" }
WordHunterWoW_QuestEN[86632] = { title = "The Battle for Tranquillien", description = "The Twilight's Blade? Attacking in broad daylight now that their cover's blown... we'll prove what a mistake that was.\n\nSlay the traitors and the creatures they've summoned. Destroy their effigies and their supplies. \n\nMake this retreat costly, {name}.", objectives = "" }
WordHunterWoW_QuestEN[86633] = { title = "Comprehend the Void", description = "Kasiea's notes may be lost forever, but we must try and improvise. I have one final ritual to try.\n\nIf this doesn't work, then the answers lay in Deatholme, the Twilight's Blade's heart. But first...", objectives = "" }
WordHunterWoW_QuestEN[86634] = { title = "The Past Keeps Watch", description = "I don't trust the quiet here. Let's shore up the defenses. Did you see those slumped-over arcane golems around the village?\n\nThey may not look like much now, but a quick tune up will have them on their feet soon enough. They're good for standing guard, and also for ferreting out any hidden snakes in the weeds.\n\nLet's get to work. The sooner the golems are running, the better I'll feel about this town's safety.", objectives = "" }
WordHunterWoW_QuestEN[86635] = { title = "To Deatholme", description = "That coward Antenorian has doomed us all. I had hoped it wouldn't come to this, but...\n\nWe need the rest of Kasiea's research--the missing pages that were stolen from her corpse. But the cult has retreated south, to the ruins of Deatholme.\n\nFitting that such traitors would sequester themselves in such a vile place. But we must root them out.", objectives = "" }
WordHunterWoW_QuestEN[86636] = { title = "Void Walk With Me", description = "I did not expect this place to be so heavily guarded. This is far more complicated than one charismatic leader and a group of wayward pilgrims. Still... if we take out Antenorian, it should weaken them considerably. A cult is nothing without its leader.\n\nValeera tracked the governor to that cavern. He's gone in. We'll make sure he never comes out.", objectives = "" }
WordHunterWoW_QuestEN[86637] = { title = "Anything but Reprieve", description = "This is dire. The Twilight's Blade is much larger--much more powerful--than any of us could have guessed.\n\nI'm relieved Umbric is on the case, but we need to let Silvermoon know what's happened here.", objectives = "" }
WordHunterWoW_QuestEN[86638] = { title = "Choking Tendrils", description = "I haven't the expertise of Orweyna in these matters. But if the Lightbloom moved this quickly, I assume the rutaani are accelerating the spread here just as they were in Fairbreeze.\n\nThe town is beyond saving, but we can at least try to contain the Lightbloom within its walls.", objectives = "" }
WordHunterWoW_QuestEN[86639] = { title = "What's Left", description = "You see what we have to contend with here. Runestone Shan'dor is helping stop the spread further north, but if this Lightbloom surges again, I don't know if we can halt it.\n\nI've heard cries for help from survivors still trapped within. We have to find them, and direct them to safety!", objectives = "" }
WordHunterWoW_QuestEN[86640] = { title = "Premonition", description = "I came as quickly as I could. This is... devastating.\n\nI have called in our Magisters to reinforce this runestone. They will keep an eye on the Lightbloom spread.\n\nI suspect Halduron Brightwing and the Farstriders have uncovered more than the villagers know. I can rely on him for anything. We shall rendezvous with him at the encampment to the north, and soon have some answers.", objectives = "" }
WordHunterWoW_QuestEN[86641] = { title = "Old Scars", description = "Of course the Amani would use this moment to encroach, the cowards. We are beset on all sides!\n\nThis land belongs to the sin'dorei, and I will not see it taken by anyone. Not by raging plants, not by a cult, not by the Void, and never by the Amani!\n\nWhatever they are doing over there, it must be stopped. Do whatever you can to disrupt them and send them scurrying back to Zul'Aman where they belong.", objectives = "" }
WordHunterWoW_QuestEN[86642] = { title = "A Foe Unseen", description = "I know Lor'themar is angry, but... this is strange, {name}. They didn't attack Suncrown--the Lightbloom did. What are the Amani doing over there?\n\nThere has to be some kind of explanation for this. It doesn't look like an invasion. Let's see what we can find out.", objectives = "" }
WordHunterWoW_QuestEN[86643] = { title = "Following the Root", description = "Lor'themar has a right to defend this land, but I don't think he's seeing clearly. The presence of Amani is too inciting.\n\nThis doesn't add up. The trolls are going out of their way to craft Lightbloom weapons--to fight what? It isn't us. They didn't attack Suncrown. They could have, and they didn't.\n\nWe need to find the truth. Let's head south. That hideout I discovered must have some answers.", objectives = "" }
WordHunterWoW_QuestEN[86644] = { title = "Gods Before Us", description = "I suppose I shouldn't have expected a greeting with open arms, but I did not expect to be trapped in here.\n\nThe Amani are clever. They must have made a way to escape. We have only to find it. Let's look around.", objectives = "" }
WordHunterWoW_QuestEN[86646] = { title = "An Impasse", description = "How deep does this crypt go?\n\nWe need to find Zul'jan and explain to him that we fight a common enemy. Surely he'll see reason!\n\nCome on. They can't have gotten much farther in this maze.", objectives = "" }
WordHunterWoW_QuestEN[86647] = { title = "Beat of Blood", description = "None of this is necessary. We need to make them see reason!\n\nMy father will know what to do. I know he'll see reason, once I explain what has happened here. There is no need for bloodshed! It's simple: if the Amani are set against the Twilight's Blade, we fight on the same side.", objectives = "" }
WordHunterWoW_QuestEN[86648] = { title = "Light Guide Us", description = "Our findings at Tor'Watha were correct. By the time Turalyon and I arrived here with troops, the Amani had already begun to take the pass. They seek to establish another path to acquire the lightwood from our land.\n\nThe Amani have chosen war, as they always do. This, at least, is a threat I know how to handle.\n\nArator is but a boy. He cannot grasp the magnitude of history between the sin'dorei and Amani--and I don't expect him to.\n\nWill you stand by the blood elves, and all that is right?", objectives = "" }
WordHunterWoW_QuestEN[86649] = { title = "Past Redemption", description = "These monsters deserve nothing more than swift retribution. For Silvermoon. For the sin'dorei.\n\n<Turalyon's eyes blaze with Light.>\n\nFor Alleria. This will be finished!", objectives = "" }
WordHunterWoW_QuestEN[86650] = { title = "Fractured", description = "Lady Liadrin will remain here. The rest of us shall return to Silvermoon and debrief.\n\n<Lor'themar looks at the devastated Turalyon.>\n\nWe still have many battles ahead, it seems.", objectives = "" }
WordHunterWoW_QuestEN[86652] = { title = "Left in the Shadows", description = "De loa have not spoken to us in many years... not since I was a young child.\n\nAnd dey have shown no sign of wanting to help us now.\n\nNo. It is up to us alone. We must find a way to rally de other tribes and fight de Twilight's Blade as one.\n\nI will speak to de tribal representatives and help de refugees where I can--dey are our priority.\n\nCome, you might learn somethin' about de Amani.", objectives = "" }
WordHunterWoW_QuestEN[86653] = { title = "The Path of the Amani", description = "Kinduru is my uncle, and I trust him... But dis \"path of de hash'ey\"...\n\nThings are not what dey were decades ago. The loa are gone--they not gonna hear us.\n\n<Zul'jarra lets out a low growl only you and Liadrin hear.>\n\nNo. We're running out of options. If dis is de time for old myths and dreams, so be it.\n\nWe meet at the foot of the mountains, Akil'zon's Reach, where de old hash'ey shrines are.", objectives = "" }
WordHunterWoW_QuestEN[86654] = { title = "Gnarldin Bashing", description = "Zul'jarra regards the gnarldin as a fierce, nomadic people that normally keep to themselves. It is clear by their clothing and weapons that they have a primitive but unique culture.\n\nIf the circumstances were different, I would advocate for diplomacy.\n\nBut they are between us and our mission.\n\nThey cannot block our path or continue to damage the shrines or the nests of the eagles that roost here. We will eliminate only those that are in our way. The Amani can choose what to do with them later.", objectives = "" }
WordHunterWoW_QuestEN[86655] = { title = "De Ancient Path", description = "My uncle, de loa speaker, spoke of de hash'ey when I was a child. But when de loa remained silent so many years...\n\nI do not think he would admit it, but he lost a little faith too.\n\nI remember some of his lessons.\n\nA chieftain must light de shrines on de way to de temple. De hash'ura must as well. Why? I do not remember.\n\nBut if it is de only way to get de loa's favor? Come. Let us get dis out of de way.", objectives = "" }
WordHunterWoW_QuestEN[86656] = { title = "Brutal Feast", description = "<Zul'jarra's brow furrows and her lip curls as she looks toward the temple.>\n\nWhen we lit de last shrine, some of de eagles returned to de temple. It could be a sign.\n\n<Zul'jarra scoffs.>\n\nOr de eagles are movin' in after de gnarldin started movin' out.\n\nWhen we get to the temple, all we gonna find is silence. Just like always.\n\nBut we still gonna try. We should go now and present an offerin'.", objectives = "" }
WordHunterWoW_QuestEN[86657] = { title = "Shadebasin Watch", description = "<Zul'jarra smiles slightly as Akil'zon's blessing buffets her.>\n\nKinduru's stories were real. We have de blessin' of Akil'zon, and de path of the hash'ey stretches out before us.\n\nWe must follow Akil'zon's advice and seek out Halazzi next. As Akil'zon is de loa of de rulin' tribe--de Amani--and my family, Halazzi is de loa of the Witherbark and their leaders.\n\nIf their loa speakers are gone, then maybe Kul'amara will know how to approach him.", objectives = "" }
WordHunterWoW_QuestEN[86658] = { title = "The Crypt in the Mist", description = "<Zul'jarra growls through her gritted tusks.>\n\nNow it's not as surprisin' dat Malacrass's tribe, de Vilebranch, fell to the lure of hex magic.\n\nBut dat is their choice and a path dey chose long ago--a path away from us.\n\nI won't let dem live long enough to regret it.\n\nWhat de Vilebranch have done to de Witherbark has gone too long without an Amani response. De mist is not in our way.\n\nWe can use it to our advantage.\n\nWe will take a life for all de lives dey took. And make sure dey stay dead.", objectives = "" }
WordHunterWoW_QuestEN[86659] = { title = "Breaching the Mist", description = "The Vilebranch seemed to be just as confused by the mist as the Witherbark.\n\nWhatever has caused de mist, dealin' with de Vilebranch changed nothing.\n\nAnd now we must find de hash'ey shrines in de dark.\n\n<Zul'jarra moves her hand in front of her face, testing her range of visibility, and frowns.>\n\nWe must light de shrines. Try not to get separated.\n\nDis will try my patience. But I'm sure if we use our heads, we will find de path.", objectives = "" }
WordHunterWoW_QuestEN[86660] = { title = "Rescue from the Shadows", description = "Kul'amara has told me dat a shadowy mist has fallen over Numazon. She believes de Vilebranch are behind it, usin' their magic to hide de crimes dey commit against de Witherbark.\n\nShe believes dey are hidin' in de Numazon crypts. De hash'ey shrines are near there as well.\n\nWe must find our way to Numazon and rescue de Witherbark captives. If we find de hash'ey shrines along de way, so be it.\n\nIf Halazzi will not stand with us, den maybe de Witherbark will.", objectives = "" }
WordHunterWoW_QuestEN[86661] = { title = "Coals of a Dead Loa", description = "By helpin' de Witherbark, we helped ourselves--and passed Halazzi's trial.\n\nThere is a lesson in that.\n\nNow dat Halazzi has returned, we should go back and let Vun'zarah know. I hope dis will improve de relationship between our tribes.\n\nAnd maybe he knows where we can find out how to resurrect Jan'alai.", objectives = "" }
WordHunterWoW_QuestEN[86663] = { title = "Embers to a Flame", description = "The loa speaker talks of fire in de heart--in all hearts.\n\nJan'alai is de loa of birth, death, and rebirth. Maybe de loa speaker is askin' for sacrifice.\n\n<Zul'jarra smiles deviously.>\n\nHey, Liadrin. How much fire you think is in an elf's heart, eh?\n\n<Liadrin gives her a sour look.>\n\nHeh.\n\nWhatever de loa speaker wants, it is either part of resurrectin' de loa or part of de trial. Let's see what he has do say.", objectives = "" }
WordHunterWoW_QuestEN[86664] = { title = "Seer or Sear", description = "Dis old, crazy loa speaker is too busy dancin' to tell us what to do next.\n\nBut I think I know.\n\nWe could not light de shrines on de way to de temple. But now dat Jan'alai's presence is here...\n\nMaybe now we can.\n\nI will take de ember to de hash'ey shrines. Den maybe de trial will start.\n\nI jumped from de top of de temple of Akil'zon. I found my way through de mists of Halazzi.\n\nI am ready for Jan'alai's fire.\n\nWe can only hope dey will receive us after what my grandfather has done.", objectives = "" }
WordHunterWoW_QuestEN[86665] = { title = "Face in the Fire", description = "First my grandfather, then my brother.\n\nJan'alai knew my shame at my grandfather's rage. And de rage I feel when Zul'jan disrespects me. I know I put fuel on his fire by respondin' de way I do. \n\nMaybe dat needs to change. I have left my doubt of de loa behind me. I can leave those thoughts behind too, and continue de path of de hash'ey.\n\nStoke de coal, {name}. I am ready for de final trial, whatever it may be.", objectives = "" }
WordHunterWoW_QuestEN[86666] = { title = "In the Shadow of Rebirth", description = "Jan'alai's trial has made me realize...\n\nI need to make things right between me and my brother.\n\nHe acts out at me, but it's because I put him down. I do not think about how hard it must be to be my brother.\n\nWe should also check on how our preparations are goin' and if my troops are gettin' de food and rest dey need.\n\nNalorakk's not gonna go anywhere. He can wait a few hours.", objectives = "" }
WordHunterWoW_QuestEN[86681] = { title = "Den of Nalorakk: A Taste of Vengeance", description = "Zul'jan has taken de troops without my orders--again!\n\nAnd de number of casualties... for what? For wood?\n\nI want to take his tusks and...\n\n<Zul'jarra growls but seems to center herself.>\n\nKinduru will need help with de soldiers' death rites. Help him prepare de herb mixture and pour it onto de fires.\n\nMy brother and I need to... talk.", objectives = "" }
WordHunterWoW_QuestEN[86682] = { title = "Den of Nalorakk: Waking de Bear", description = "We must set aside what Zul'jan has done and focus on de final hash'ey trial: facin' Nalorakk, de Loa of War.\n\nDe Revantusk were once beloved of Nalorakk. Legend has it dat his loa speaker was so devoted, she followed him into his temple and his den with de most faithful of de Revantusk's warriors.\n\nBut now de temple is sealed. We cannot speak to de loa speaker, but maybe Lilaju knows how to get Nalorakk's attention.\n\nShe keeps watch for de Twilight's Blade at Torntusk Overlook with her guards.", objectives = "" }
WordHunterWoW_QuestEN[86683] = { title = "Hash'ey Away", description = "We've done it, {name}. De loa are at our side once again.\n\nAm I hash'ey? I do not know. But I do know I would not have gotten dis far without my hash'ura.\n\nCome. We will return to Amani'Zar and tell Kinduru and Zul'jan de good news.", objectives = "" }
WordHunterWoW_QuestEN[86684] = { title = "The Blade's Edge", description = "With de other tribes and de loa's help, we can take de fight to de Twilight's Blade and take dem down.\n\nBlood for blood!", objectives = "" }
WordHunterWoW_QuestEN[86685] = { title = "Chip and Shatter", description = "<Zul'jarra shakes her head back and forth and jumps in place, shaking out her muscles.\n\nShe stops and turns to you, grinning broadly.>\n\nHeh. Do you feel it, my hash'ura?\n\nDe electricity in de air? De smell of blood and fire?\n\nMy soul is leapin' to join de fight.\n\nYou ready to chop de enemy down, bathe in dey blood, and make dem pay for what dey done?\n\nMe too.", objectives = "" }
WordHunterWoW_QuestEN[86686] = { title = "Light Indiscriminate", description = "Though the dead litter this field, I still see plenty of Amani clinging to life.\n\nHelp me heal the injured. We'll ensure their reputation for survival continues on after this day.", objectives = "" }
WordHunterWoW_QuestEN[86687] = { title = "Conduit Crisis", description = "With de loa at our side, we can finally break de Twilight's Blade and return to Amani'Zar with Mor'duun's head.\n\nDe loa are already attackin' de main source of Mor'duun's power: summoned spheres of pure void energy.\n\nGo to de loa and offer your assistance. When de orbs are destroyed, we can move forward and strike at Mor'duun!", objectives = "" }
WordHunterWoW_QuestEN[86692] = { title = "Blade Shattered", description = "It ends here. De path of the hash'ey, my path, has led me here.\n\nLet dis fight bring a new age for my people.\n\nCome. It is time.", objectives = "" }
WordHunterWoW_QuestEN[86693] = { title = "De Legend of de Hash'ey", description = "Mor'duun is slain.\n\nDe Twilight's Blade will continue to plague our lands, but of dem only Mor'duun's \"fodder\" is left. Dey will be easy prey for us.\n\nAnd now I will say somethin' my uncle would be proud of. Let us follow de teachin' of Nalorakk, de Loa of War.\n\nDe battle is over. It is time to rest--I can tell by your eyes both my hash'ura need it too.\n\nLet us leave dis place. We can speak again back in Amani'Zar.", objectives = "" }
WordHunterWoW_QuestEN[86697] = { title = "The Cleanup Crew", description = "Even if we got bots out there an' not workers, there are still gonna be monsters out there gettin' in their hair, er, wirin'.\n\nGet out there an' thin out the wildlife. That'll keep our bots from gettin' damaged and voidin' whatever warranty they got left.\n\nThe longer they can stay out there, the longer we can stay right here!", objectives = "" }
WordHunterWoW_QuestEN[86698] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good. {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", objectives = "" }
WordHunterWoW_QuestEN[86699] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", objectives = "" }
WordHunterWoW_QuestEN[86700] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", objectives = "" }
