WordHunterWoW_QuestEN[86704] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", objectives = "" }
WordHunterWoW_QuestEN[86705] = { title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", objectives = "" }
WordHunterWoW_QuestEN[86706] = { title = "Seeking Knowledge of the Past", description = "Greetings, {race}. I must seek your aid. Soridormi and our kin have journeyed to Khaz Algar to help in this fight against the Void's new master.\n\nWe think that we can provide insight and valuable information about past attacks by the Void. \n\nSeek her out near the southern edge of the Coreway.", objectives = "" }
WordHunterWoW_QuestEN[86708] = { title = "The Gates of Zul'Aman", description = "After the Amani surrender, we demanded Zul'jan relinquish our lightwood and return to their lands. Even so, Zul'jan still lingers at the gates of Zul'Aman with his troops.\n\nLady Liadrin and her Blood Knights hold the pass, and Liadrin is trying to remedy the situation with diplomacy, but she reports that aggression may begin anew.\n\nShe requests your assistance in this precarious matter.", objectives = "" }
WordHunterWoW_QuestEN[86710] = { title = "The Line Must Be Drawn Here", description = "I had hoped that Zul'jan would leave the lightwood and return swiftly to his lands after our confrontation with him.\n\nBut dealing with the Amani has never been a simple matter.\n\nDiplomacy is the only way to avoid more bloodshed, but Zul'jan is finished listening to me.\n\nPerhaps he will listen to you?", objectives = "" }
WordHunterWoW_QuestEN[86711] = { title = "Amani Clarion Call", description = "If you want to survive here in Atal'Aman, find and beat de city's battle drums. Dat will rally our remainin' soldiers forward to join de fight.\n\nIt will also bring all de tribes of Zul'Aman--de Witherbark, de Revantusk, and de Shadowpine--to our aid and tell our civilians to retreat to de Altar of Malacrass if we need to evacuate.\n\nUse de drums to spread de word. Find me at de Altar of Malacrass when you are done.", objectives = "" }
WordHunterWoW_QuestEN[86712] = { title = "The Amani Stand Strong", description = "Zul'jarra doesn't think de lightwood is worth de risks I am taking. We will prove her wrong.\n\nI have seen too many warriors discouraged because their weapons don't work against de Twilight's Blade.\n\nDon't just tell them to retreat. Give them de lightwood weapons.\n\nNothing stirs Amani blood like an effective axe in their hands. Let dem fight their way back to de Altar of Malacrass.", objectives = "" }
WordHunterWoW_QuestEN[86715] = { title = "Rituals Cut Short", description = "In our reconnaissance flight around the city, Zul'jarra and I got a look at the Twilight's offensive. They're summoning more Twilight's Blade directly into Atal'Aman.\n\nWe can counter them by disrupting their dark summoning rituals. That will stop the flow of their cultists into the city and give the Amani time to strategize.\n\nKill the ritualists, and any trollbreakers already portaled into the area.", objectives = "" }
WordHunterWoW_QuestEN[86716] = { title = "Armed by Light", description = "You might be good at killing, {class}, but so are we Amani.\n\nAnd even more de better our weapons!\n\nI took an army into Eversong to reclaim de lightwood forests for de Amani. It was against my sister's orders, yes, but lightwood gives us an advantage.\n\nTake back de weapons being stolen by de Twilight's Blade, and I'll show you why it was worth de effort.", objectives = "" }
WordHunterWoW_QuestEN[86717] = { title = "Show Us Your Worth", description = "De Twilight's Blade's general, Mor'duun, has got us by de throat. We're not winnin', and we are too few.\n\nWe've got to evacuate before there's no one left--and hope de other tribes meet us at Amani'Zar.\n\nIn de meantime, I'm glad to use you while we rally de people of Zul'Aman. \n\nDe civilians' lives are my priority. Go to Swiftclaw Terrace and evacuate de people there.\n\nTear through de Twilight's Blade as you go. Find your way to Zul'jan when you're done.", objectives = "" }
WordHunterWoW_QuestEN[86718] = { title = "Twilight Bled", description = "Mor'duun may be de leader of de Twilight's Blade in Zul'Aman, but dat ogre can't be everywhere. De elf found his military commander--a hulkin' pile of armor and flesh named Benvis Bladesplatter.\n\nHe's paradin' 'round like he's already won just because dey seized Firewing Terrace.\n\nMake him pay for his arrogance.", objectives = "" }
WordHunterWoW_QuestEN[86719] = { title = "Important Amani", description = "De drums have sounded. But de elders have not come.\n\nWe cannot lose them. They are our link to our culture--our sages and our best minds.\n\nTorundo helped devise de lightwood weapons. And Doru is our provisioner. We will need both if de battle goes on.\n\nGo find Doru in de market and Torundo in de tribute hall.\n\nDe last one is de old loa speaker--our uncle, Kinduru. He may need... special persuasion to leave. I will go to Talonstrike Terrace to speak to him. Meet me there after you find de others.", objectives = "" }
WordHunterWoW_QuestEN[86720] = { title = "Break the Blade", description = "Zul'jan's ballista is ready. And it had better work after what he has done.\n\nWe lost de army we needed to defend de city, but we can fend off Mor'duun long enough to let our people escape.\n\nHelp my brother man de ballista. Focus on de shadow warders and de pylon. Liadrin and I will distract Mor'duun.\n\nI will kill him if I can, but even then we can't stay here. There's too much void energy. And too much destruction. Atal'Aman is truly lost.", objectives = "" }
WordHunterWoW_QuestEN[86721] = { title = "Everything We Worked For", description = "My blood is boiling! While waiting for Kinduru, de Twilight's Blade was destroying what little stores of lightwood we had left at Ragemaw Terrace!\n\nBut if we act quickly, we can save enough to arm de lightwood ballista--and take a shot at Mor'duun.\n\nAnd without de ballista, we cannot claim victory!", objectives = "" }
WordHunterWoW_QuestEN[86722] = { title = "Heart of the Amani", description = "You and your elf friend amuse me. And you've more than proved yourself in battle.\n\nOur people are headin' to Amani'Zar. We hope dat de other tribes rallied there instead of Atal'Aman. Their representatives will give us council, and then we will mount an attack on de Twilight's Blade.\n\nIf you still wish to fight with de Amani, meet me on de northwest side of de village. Zul'jan will have gone ahead to speak of his deeds--and yours--but do not enter de village without me. Amani kill strangers on sight.", objectives = "" }
WordHunterWoW_QuestEN[86723] = { title = "Isolation", description = "We will speak to Torundo, my war advisor. And if de representatives of de tribes are here, we will have a council meetin' in de Zari Lodge.\n\nTogether, we must agree on a way to defeat de Twilight's Blade.\n\nExplore de village if you want. But keep your weapons where dey can be seen. You are here by my invitation and my word is law, but I can only run so fast if one of my people thinks you looked at dem in de wrong way.\n\n<Zul'jarra smiles a tusky grin as if proud of her people's short fuse.>", objectives = "" }
WordHunterWoW_QuestEN[86728] = { title = "Operation: Floodgate: Disposing of the Garbage", description = "Hey, pal. I've heard murmurs of a real piece of work trying to siphon off energy at the Waterworks in the Ringing Deeps.\n\nStealing from our stone friends ain't good for business, and it certainly ain't something we're willing to let continue.\n\nI know you've made a name for yourself for disposing of the trash, and bad business folks are certainly as trashy as they come.\n\nDo me a favor, will ya? Weapons are optional, but attitude is required... if you catch my drift.", objectives = "" }
WordHunterWoW_QuestEN[86733] = { title = "Silvermoon Negotiations", description = "It would be an understatement to say things between Silvermoon and the Alliance are often tense and uneasy. I thank you for setting aside any prejudices you might have had and lending your strength to the defense of Silvermoon and the Sunwell.\n\nWe have Xal'atath's forces held for now, but this is far from over.\n\nI would include you in our next steps. Meet me at the Sanctum of Light.", objectives = "" }
WordHunterWoW_QuestEN[86734] = { title = "Diplomacy", description = "We shall all weigh in on the situation.\n\n<Lor'themar glances at Umbric and Rommath.>\n\nAs you can see, there are many tensions at play.\n\nPlease give us a moment to discuss.", objectives = "" }
WordHunterWoW_QuestEN[86735] = { title = "Paved in Ash", description = "Now that the matter is settled, you should acquaint yourself with Silvermoon. There are a few key civilians I'd like informed about your presence here--you should check in with them.\n\nShow them my signet ring--they'll know you've my permission to be here. But please take care where you go, and stay in the outer city to avoid any issues.", objectives = "" }
WordHunterWoW_QuestEN[86736] = { title = "Paved in Ash", description = "I've more to review with Turalyon, but in the meantime, the rest of the city should be informed that we will have some temporary guests in the outer perimeter. I'd like you to check in with a few key civilians and deliver the news.\n\nWhile you're out there, take the chance to familiarize yourself with Silvermoon. We've made impressive strides rebuilding it since you've last visited.", objectives = "" }
WordHunterWoW_QuestEN[86737] = { title = "Fair Breeze, Light Bloom", description = "In recent years, small pockets of wild growth we call \"Lightbloom\" have blossomed throughout Eversong. A curiosity for our local botanists, for the most part.\n\nHowever, the Magistrix in Fairbreeze is asking for help with the local Lightbloom. Every capable hand I have is focused on holding back the Voidstorm--but if the Magistrix cannot handle the matter herself, it requires swift attention.\n\nI'd like you to see to the issue. Magister Rommath can provide you with an arcane projector to keep in touch.", objectives = "" }
WordHunterWoW_QuestEN[86738] = { title = "Sharpmaw", description = "These beasts roaming the village are nuisances, but we have a bigger problem.\n\nThere's a feral lynx prowling nearby that we call Sharpmaw. She used to keep her distance from the village, but the current situation has made her more bold. We've plenty of little ones around here, and more than once the guards have caught that beast eyeing them like they were a snack waiting to be snatched. \n\nStop her before she starts attacking my people in earnest!", objectives = "" }
WordHunterWoW_QuestEN[86739] = { title = "Fairbreeze Favors", description = "This is the oddest situation I've ever been in--our village is being overrun!\n\nI like to keep things neat and tidy around here, but these animals... they've come in from the wilds like they own the town. They're attacking our sweet pets, overturning our belongings, and causing havoc. No sooner have I solved one problem than another is rearing its head. I'm only one elf--I can't stop all of this on my own!\n\nLend a hand, won't you? This... elf... troll... person hasn't lifted a finger.", objectives = "" }
WordHunterWoW_QuestEN[86740] = { title = "Displaced Denizens", description = "The wildlife here seems to have been upset by something. Perhaps this is why the world's song bade me here: to discover why and correct it.\n\nStudy the displaced wildlife. Bring me your findings. If there is anything unusual, I wish to know of it. I will speak with the Magistrix. Perhaps together we can uncover this mystery.", objectives = "" }
WordHunterWoW_QuestEN[86741] = { title = "Lightbloom Looming", description = "The wildlife seems to have been displaced from the south. It is there we will surely find answers.\n\nCome--I will use my magic to illuminate the path and we will follow the trail.", objectives = "" }
WordHunterWoW_QuestEN[86742] = { title = "Curious Cultivation", description = "This place is unlike anything I have seen before. The plant growth is unique.\n\n{name}, let us examine the Lightbloom more closely. Perhaps we can uncover the secrets of this place together.", objectives = "" }
WordHunterWoW_QuestEN[86743] = { title = "Trimming the Lightbloom", description = "The creatures of this Lightbloom see us as the intruders. They threaten the surrounding wildlife and inhabitants who are naturally here.\n\nWe should reduce their numbers and end this threat.", objectives = "" }
WordHunterWoW_QuestEN[86744] = { title = "Seeking Truth", description = "I will channel on this strange seed we have collected, and see if I can discover what has happened here.\n\nThis may upset the rutaani. Make sure I am not interrupted. This is why I was called here--I know now. But I must discover what needs to be done.", objectives = "" }
WordHunterWoW_QuestEN[86745] = { title = "Silvermoon Must Know", description = "This growth--Lor'themar needs to know about this. I worry what will happen should it get out of control. \n\nAnd the Light's influence... my father should know, too.", objectives = "" }
WordHunterWoW_QuestEN[86769] = { title = "Last Bastion of the Light", description = "Your arrival has reignited hope.\n\nWe have pushed Xal'atath's forces away from the Sunwell, yet they still infest the Isle of Quel'Danas, and appear to be massing for another attack as they prey upon the sin'dorei.\n\nWe must join up with the Vanguard of Light.", objectives = "" }
WordHunterWoW_QuestEN[86770] = { title = "Champions of Quel'Danas", description = "Lor'themar has formed a rally point at Sunstrider Rise, while the civilians there are evacuated to Silvermoon, but the forces of the Vanguard of Light are scattered throughout the battlefield.\n\nWe need to fight as one to defeat this host. Together, we can defeat Xal'atath and save the Sunwell.", objectives = "" }
WordHunterWoW_QuestEN[86775] = { title = "Urge to Surge", description = "Occasionally we get more jobs than we can handle. You know what that means-- big money. Help out during some Surge Pricing and we'll see to it that you're thanked for your help.", objectives = "" }
WordHunterWoW_QuestEN[86780] = { title = "Where Heroes Hold", description = "We have stopped the Devouring Host's initial attack. This battle will not be won if we go on the defensive, not even to safeguard the innocents of Quel'Danas.\n\nFocus on culling the Voidfront. Without their invading force, the Devouring Host cannot maintain a foothold!\n\nWe will rally at Sunstrider Rise when ready.", objectives = "" }
WordHunterWoW_QuestEN[86781] = { title = "Face the Past", description = "<Umbric scans the Eversong map with grave intent.>\n\nTranquillien was marked, as are a number of other locations. \n\n<Umbric stops, voice tightening.>\n\nWindrunner Village. It's marked.\n\nThe Twilight's Blade retreated to their base in Deatholme, but my home may be in peril. We must make sure my people in Windrunner Village are safe before pursuing them.", objectives = "" }
WordHunterWoW_QuestEN[86782] = { title = "Atrium Hospital", description = "The necrorays have been installed in the Atrium, and Hemet is seeing to them.\n\nHe has requested your presence.", objectives = "" }
WordHunterWoW_QuestEN[86783] = { title = "Rays of Sunshine", description = "Right then. Let's get these rays into Eco-Dome: Primus to the north!", objectives = "" }
WordHunterWoW_QuestEN[86786] = { title = "The Void Hunter", description = "The Void espouses all truths, {name}. And in none of them do I defeat Ramon'ta without some help.\n\nAnd here you are.\n\nMy quarry is a cosmic worm known as Ramon'ta the Insatiable. It started out small enough, but with each void entity it feasts upon, it grows, and its power grows along with it.\n\nIf we can defeat it, I can claim its power. Will you help me?", objectives = "" }
WordHunterWoW_QuestEN[86801] = { title = "Faceless Mask of Multitudes", description = "By our multitudes will the world drown and feed the hunger of our gods. Only by bathing in the blood of our foes may one rise to the exaltation of our masters and unleash their never ending multitudes for themself.", objectives = "" }
WordHunterWoW_QuestEN[86805] = { title = "The Hour of Need", description = "Turalyon is thinking like a battlefield captain and not like a leader! My people, the sin'dorei, have suffered much in these past few wars. How many must die in the name of his victory?\n\nPlease, {name}. Rescue any citizens you can and help guide them safely to the boats at the Silver Landing.\n\nEvery life saved is a victory for the blood elves.", objectives = "" }
WordHunterWoW_QuestEN[86806] = { title = "Luminous Wings", description = "No! Xal'atath's Host has opened portals above the strait. Void creatures spill out and descend upon the refugee's ships. We have to safeguard the civilians!\n\nThose dragonhawks have been empowered by the Light. They should give you enough power to defeat the Void beasts and rescue the fleeing civilians.", objectives = "" }
WordHunterWoW_QuestEN[86807] = { title = "The Gate", description = "The High Exarch commanded us to assemble with his Vanguard of Light and attack the Devouring Host. I do not regret my delay of that order, but he will have noticed my absence.\n\nWe should make haste and assemble with the others.", objectives = "" }
WordHunterWoW_QuestEN[86808] = { title = "The Riddled Speaker", description = "Chief Vun'zarah knew little of Jan'alai, but he did know about their loa speaker.\n\nIf dey are still at de temple, then there is hope we can resurrect de loa.\n\n<Zul'jarra's hand tightens on her axe.>\n\nMakin' Akil'zon flee, woundin' Halazzi, sendin' Nalorakk into a rage, and killin' Jan'alai...\n\nMy grandfather and Malacrass have so much to pay for.", objectives = "" }
WordHunterWoW_QuestEN[86809] = { title = "Test of Conviction", description = "We got her attention. But now what?\n\nI know there is a trial. But Akil'zon is not givin' any hints on what it is.\n\nThink. Think. What did Kinduru teach me as a child? She is de loa of victory. But also of oaths and conviction.\n\nIf only we had made it to de top when I was a child, and I hadn't fallen...", objectives = "" }
WordHunterWoW_QuestEN[86810] = { title = "Harvesting the Void", description = "To effectively counteract the void anomalies present here, we must obtain viable samples of the anomalies.\n\nSearch the area for containment vessels that hold developing anomalies, as well as the Unstable Oozelings created from the contamination.\n\nUse the collection device to make this process easier. Only living Oozelings will provide viable samples.", objectives = "" }
WordHunterWoW_QuestEN[86811] = { title = "Ethereal Eradication", description = "{name}! I have a mission for you. There is a contingent of Shadowguard ethereals to the northeast.\n\nThey appear to be looting the buildings, but that could change in a moment. The Vanguard cannot afford to be flanked as we advance. Take out their leader and decimate their forces while we engage the Host.", objectives = "" }
WordHunterWoW_QuestEN[86820] = { title = "Manaforge Omega: Dimensius Looms", description = "This is it, {name}. We must defeat this Void Lord... no matter what it takes.", objectives = "" }
WordHunterWoW_QuestEN[86822] = { title = "One Final Relic", description = "{name}, I've asked the Sons of Lothar to meet us in the Burning Steppes near Blackrock Mountain. There's one more item we must recover there.\n\nWe can depart as soon as you are ready.", objectives = "" }
WordHunterWoW_QuestEN[86823] = { title = "The Dark Horde", description = "I once served under Blackhand, long ago. His son Rend was a sniveling fool: a coward who bolstered himself in that Spire after Doomhammer was defeated. He made deals with dragons, called himself Warchief, and proclaimed his Dark Horde the \"true\" Horde. Pah!\n\nThis Dark Horde embraces the ideals of a past long gone. Rend died years ago, but there are still orcs and ogres here who cling to the rotting husk that remains.\n\nIf they haven't seen the truth by now, there is little hope for them but death.", objectives = "" }
WordHunterWoW_QuestEN[86824] = { title = "None Left Standing", description = "The one thing worse than seeing this Dark Horde here is their banners.\n\nIt showcases their pride in this accursed mountain as a place of greatness--as a place for their horde to rise. In reality, this banner is little more than a defiled perversion of the ancestral Blackrock sigil.\n\nBurn down every one you find.", objectives = "" }
WordHunterWoW_QuestEN[86825] = { title = "Faithful Servant, Faithless Cause", description = "One of their lieutenants, Mar'kag, appears to be the one barking orders. His father, High Overlord Omokk, followed under Rend Blackhand's banner. Cruel, vicious... no surprise that his son follows in his footsteps.\n\nTaking Mar'kag down will spread chaos among the cowardly remnants of this Dark Horde and perhaps help them realize they are not as strong as they think.\n\nFaol also has us here to look for relic fragments. If Mar'kag has anything of note, bring it back.", objectives = "" }
WordHunterWoW_QuestEN[86826] = { title = "Nagosh the Scarred", description = "The Dark Horde may strut around inside the mountain, but an orc called Nagosh is the one rulin' this roost.\n\nHe barks orders, then charges straight into a fight. Rock-heads in command like that one are what gets everyone on all sides killed. \n\nI'd bet anything that numbskull claimed Faol's shiny relic. Keep an eye out. He may jump ye in the middle of a fight.", objectives = "" }
WordHunterWoW_QuestEN[86827] = { title = "Due Recognition", description = "Blackrock Mountain is where most of the Dark Horde has holed up. All their unit commanders adorn themselves with badges, struttin' around like they won the Second War. Shameful! But it gives me an idea.\n\nDefeat them and take their badges. Can't have new leaders that way--these blowhards like the pomp of command. Who wants the stress of leadership with no fancy badge to wear?\n\nHead on in there with Arator and keep 'em busy. Sky'reen an' I will support ye from the air.", objectives = "" }
WordHunterWoW_QuestEN[86828] = { title = "Not Just a Troll's Bane", description = "As much as I'd love to keep harassing these Dark Horde grunts, we've found the relic piece that Faol wanted us to. We best be getting on.\n\nDanath went looking for the last piece of the relic. You go find him, and I'll tell the mad bishop that his plan is nearly complete. Find me at Lothar's Statue when yer done.", objectives = "" }
WordHunterWoW_QuestEN[86829] = { title = "A Landmark Moment", description = "With their leader defeated and that third relic fragment found, we should regroup with the others back at Lothar's Statue, {name}.\n\nI'll meet you there.", objectives = "" }
WordHunterWoW_QuestEN[86830] = { title = "A True Horde of Dark Horde", description = "The remaining Dark Horde forces are gathered here, {name}. Many of them look to be untrained and new to the cause.\n\nDrive away the forces gathered here, and perhaps we can hope to see some peace in this region--for the first time in decades.", objectives = "" }
WordHunterWoW_QuestEN[86831] = { title = "Warriors Without a Warlord", description = "Despite our work in the area, the Dark Horde continues to battle. Their leader is there, in Blackrock Stronghold, likely bolstering their spirits. \n\nTake them out. Once we do, I suspect this Dark Horde will come to nothing, with much less bloodshed.\n\nAnd Faol thinks there may be a fragment of the relic he's looking for in there. Recover that as well!", objectives = "" }
WordHunterWoW_QuestEN[86832] = { title = "A Worthy Forge", description = "Thank you for all your help, {name}. It's strange to hold what remains of my father's shield and know that, prior to that day, he was such a defender of others.\n\nI feel I've only seen his aggressive side. I realize he means well, but I don't think...\n\nThat is not the path for me.\n\nRegardless, let's return to Silvermoon and get these fragments we've gathered to a worthy forge.", objectives = "" }
WordHunterWoW_QuestEN[86833] = { title = "A Bulwark Remade", description = "{name}, it is time to see what we can do with these fragments of Turalyon's shield.\n\nWhile it did break, it was exceptionally powerful in its day, and it could be a great help to Turalyon against the Void.\n\nPerhaps a moment of healing and letting go, as well.", objectives = "" }
WordHunterWoW_QuestEN[86834] = { title = "Voidborn Banishing", description = "The Devouring Host are composed of horrors from the depths of the Void, but they are still an army, with soldiers and leaders. Amongst that sea of void walkers, I notice there are singular creatures.\n\nWhether commander or mascot to the Host, removing them from the battlefield will help to break their lines.", objectives = "" }
WordHunterWoW_QuestEN[86835] = { title = "Regroup!", description = "We've stabilized most of the city and saved as many as we could, but our job isn't over.\n\nLocus-Walker must still be out there looking for the enemy commander. We've already searched over most of the city, so he must be in the one place we've not yet looked.\n\nCome, {name}. Meet me at Myza's Oasis.", objectives = "" }
WordHunterWoW_QuestEN[86836] = { title = "The Hunter Awaits", description = "I have warned Orweyna of the dangers and madness that lay within the Rift of Aln, but she believes it is her only path forward. I envy her faith.\n\nSomeone can help show her the way: the Shul'ka. The Hunters of Shadows. They have sacrificed everything to protect the haranir from the effects of the rift.\n\nI will let one know that you need help. You will find him in the Vale of Mists.", objectives = "" }
WordHunterWoW_QuestEN[86837] = { title = "Meet at the Sunwell", description = "I have been tasked with bolstering the Vanguard of Light that empower the Sunwell. I need your help, though not just for that simple task.\n\nOur mutual friend, Arator, is... stuck. Stuck in his grief and anger over that tragic conflict between him and his father.\n\nI'm just an old priest that's been raised from the dead, but I've found that a quest is just the thing to set a young paladin back on the right path.\n\nWould you help?", objectives = "" }
WordHunterWoW_QuestEN[86838] = { title = "Renewal for the Weary", description = "The Vanguard of Light are maintaining a difficult ritual at the Sunwell. It requires focus, discipline, and is quite exhausting.\n\nTake my staff. I've had it since I was Archbishop in Stormwind. It is meaningful to me and my faith. The Light responds to meaning and intention. It should renew the Vanguard's spirits so they can maintain the ritual a while longer.\n\nI can't approach any closer to the Sunwell, so you will have to do this for me.", objectives = "" }
WordHunterWoW_QuestEN[86839] = { title = "Relics of Light's Hope", description = "The holy power in my staff has been spent. Forty years of fervent prayers drained away in a few minutes. It was for a good cause, and my staff will recover in time.\n\nThere are other relics, like my staff, that were important to paladins and priests. Light's Hope Chapel has many such relics stored there.\n\nArator trained there as well. Perhaps the solution to his pain could also be found within.", objectives = "" }
WordHunterWoW_QuestEN[86840] = { title = "Flickering Hope", description = "Normally, {name}, paladins from Light's Hope hold back the Scourge in the immediate area around the chapel, but they've all been called to fight the Void.\n\nAs a result, Scourge forces have greatly increased their numbers around the chapel. We've managed to hold the line so far, but only with the help of Darion and the Ebon Blade.\n\nGive us some room to breathe--defeat as many of them as you can.", objectives = "" }
WordHunterWoW_QuestEN[86841] = { title = "Relics of Paladins Past", description = "Alonsus tells me you're looking for relics of holy power, to sustain those performing the ritual holding the Void at bay.\n\nNow that you've beaten back the Scourge, you and Arator are certainly welcome to enter the Sanctum of Light and use what we have for the cause.", objectives = "" }
WordHunterWoW_QuestEN[86842] = { title = "Scarlet Power", description = "These artifacts will help sustain the Vanguard, but they are not enough. I know of a place nearby that would have the rest we need, but... given Arator's state of mind, I'm hesitant to go there.\n\nHmph... No sense in avoiding it. We must all face up to the fact that the Scarlet Crusade calls upon the power of the Light, and has for decades.", objectives = "" }
WordHunterWoW_QuestEN[86843] = { title = "Light Miswielded", description = "The Scarlet Crusade has been wielding the Light for its evil purposes for decades, {name}. I'm disappointed to see how many forces they still have here.\n\nStill, the Light responds to them, just as it does to us.\n\nWe're here to get their relics to help the Sunwell, but while we're here, let's cleanse this place of their dark influence.", objectives = "" }
WordHunterWoW_QuestEN[86844] = { title = "Light Repurposed", description = "Leaders of the Crusade have channeled the Light through their weapons every day for years. \n\nWhile their goals and actions are reprehensible to us, their weapons are no less useful than my own staff, especially in such a time of need.\n\nAs you go through the Scarlet Halls, whenever you find a leader, defeat them and bring back their weapon. We will put it to a righteous use: to aid the Sunwell.", objectives = "" }
WordHunterWoW_QuestEN[86845] = { title = "The Sunwalker Path", description = "I think I have failed Arator. In my attempt to steady him after the incident with his father, I may have shattered his faith with uncomfortable truths of the Light.\n\nI would like to consult with the wisest person I know, Sunwalker Dezco. I did not see him with the Vanguard. Tyrosus told me he may be in Hammerfall providing aid to the displaced.", objectives = "" }
WordHunterWoW_QuestEN[86846] = { title = "Resupplying Our Suppliers", description = "{name}, the people of Hammerfall were attacked not so long ago by saboteurs from a group called the Red Dawn.\n\nI am working to help them recover and rebuild from the attack with my fellow Sunwalkers: Malu and Nadura.\n\nOne thing they have been doing is gathering supplies needed by Hammerfall's crafters from various sources.\n\nIf you could deliver these supplies, it would be a great help.", objectives = "" }
WordHunterWoW_QuestEN[86848] = { title = "Light's Arsenal", description = "The armory here stores legendary weapons and artifacts, blessed with the power of the Light due to their proximity to the Sunwell.\n\nWhile we are pinned down by the Host, the ethereals are looting these treasures.\n\n{name}, secure these holy artifacts. They are our best weapons against the Void. Use them to cut down these invaders if you have the need.", objectives = "" }
WordHunterWoW_QuestEN[86849] = { title = "Wrath Unleashed", description = "{name}, the time has come! We push these fiends to Sun's Reach Harbor! We drive them back into their accursed void portal and drive them from these sacred shores!\n\nFor the Light! For Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[86850] = { title = "Broken Sun", description = "We need to fall back! This is not a battle that we can win. Not like this.\n\nBut there is still hope! The Sunwell. It brought the Vanguard of Light here to defend it. It brought you, {name}. Fall back to the Sunwell chamber and defend it for as long as we can.\n\nI have faith the Light did not intend for us to lose this day.", objectives = "" }
WordHunterWoW_QuestEN[86851] = { title = "The Foundation of Aln", description = "The presence of the goddess reverberates through everything in the Rift of Aln. The voice is too powerful for haranir to resist. In mere minutes, one of our flock would be lost forever.\n\nThere are, however, ways to protect oneself for a short time. Kill the rejects that crawl up from the rift and gather the Alndust from which they are created. I can show Orweyna how to craft a short-term solution for entering the rift.", objectives = "" }
WordHunterWoW_QuestEN[86852] = { title = "Light's Last Stand", description = "Our attempts to fight Xal'atath's Devouring Host have failed. Our only hope is to call upon the Light once more and trust that there was a reason it brought this Vanguard together. \n\n{name}, you and Arator need to protect the Sunwell from the Devouring Host. With so few of us left, we cannot spare any more defenders.\n\nOur faith in the Light will save us.", objectives = "" }
WordHunterWoW_QuestEN[86855] = { title = "Consequences of Our Duty", description = "You must see with your own eyes the effects that the Rift of Aln can have on any haranir. Even those who stand guard over the border are oft affected by its call.\n\nTake this. I use it as an emergency salve to help those who are stricken of the dangers of Aln. Patrol these lands and give aid to those who need it. Perhaps then you will understand the gravity of what you seek to do.", objectives = "" }
WordHunterWoW_QuestEN[86856] = { title = "Dampening the Call", description = "Amarakk told me how to prepare Alndust to create the salve. In small doses, Alndust can strengthen the mind against madness and terror. It offers clarity and peace, but only if expertly employed.\n\nI could use your help to set an anchor to this place, {name}. The ritual is delicate, and failure could be disastrous.", objectives = "" }
WordHunterWoW_QuestEN[86857] = { title = "Descent into the Rift", description = "With this, I will be able to venture down into the Rift of Aln. I will not have long, so we should not dawdle.\n\nLet us find Amarakk and gain his help.", objectives = "" }
WordHunterWoW_QuestEN[86858] = { title = "The Madness Roots Deep", description = "I found you while I was in the middle of one of my duties. Someone has spent too long within the rift and has fallen prey to the call of the goddess. I must rescue him and send him back to where he belongs.\n\nHelp me with this task, and I will help you.", objectives = "" }
WordHunterWoW_QuestEN[86859] = { title = "Grinding Out a Solution", description = "I have been pondering what Hagar could have meant from the moment Orweyna mentioned an answer to your problems. There are no mystical fountains--no weapons. Everything in the rift is created from the same source: Alndust, the distillation of the influence of the goddess. If we hunt a large manifestation, you will have the power of creation in its purest form.\n\nWe cannot defeat it without help. Search the rift and look for fungi large enough to cultivate. I can use them to give us an edge.", objectives = "" }
WordHunterWoW_QuestEN[86860] = { title = "Before They Grow", description = "Within every creature that roams the Rift of Aln thrums a gathering of the foundation of the goddess's influence. This Alndust yearns to merge with others of its ilk. Part of my duties as the Shul'ka is to make sure to keep the number of large manifestations low so they do not overwhelm the Den.\n\nIt is easiest to do that while they are small.\n\nTake this spear. You may use it to shatter the smaller creatures down to... trivial sizes.", objectives = "" }
WordHunterWoW_QuestEN[86861] = { title = "Herding Manifestations", description = "We are preparing to fight a giant manifestation. Let me emphasize this again. We must fight just one.\n\nIf we fight two at a time, we would have no chance of survival. Place these wards around the rift to draw the others away. They will not last long... but we will need every advantage we can gain.", objectives = "" }
WordHunterWoW_QuestEN[86862] = { title = "The Greater They Aln", description = "We have one chance at this only.\n\nI pray we have prepared enough.", objectives = "" }
WordHunterWoW_QuestEN[86864] = { title = "Watch the Den", description = "Finally, we have a moment to breathe. This is where we feel closest to the goddess--we are below the Cradle where she used to rest.\n\nThe elders will not allow us to use any of the Alndust they have gathered over the centuries. They see only what the goddess asked of us before, not what her world needs now.\n\nAlndust is rare, but there are ways to get it. Ask around. I will check... elsewhere.", objectives = "" }
WordHunterWoW_QuestEN[86865] = { title = "In Search of the Problem", description = "We did what Hagar asked us to do. The next step will be to test this on something--or someone--afflicted with the Lightbloom.\n\nIt may be difficult to find the Lightbloom in enough quantities in Harandar, but I believe we will find what we need at Har'alnor. I will meet you there!", objectives = "" }
WordHunterWoW_QuestEN[86866] = { title = "Can We Heal This?", description = "The rutaani have escaped their nearby villages to Har'alnor. The guards have told me that some of them have been afflicted with the Lightbloom, yet have not succumbed to its effects.\n\nThis may be our best opportunity to test the Alndust's powers. Time is of the essence!", objectives = "" }
WordHunterWoW_QuestEN[86867] = { title = "Into the Lightbloom", description = "We've gathered the haranir we have available and distributed the Alndust. We have everything we need, but they need to be able to safely enter the area. Scouts have told us that the creatures spreading the Lightbloom are protected by a shield. We must stop them. We will also need to thin their numbers.\n\nGet on the petalwing, {name}, and let's clear the way.", objectives = "" }
WordHunterWoW_QuestEN[86868] = { title = "Goodwill Tour", description = "The situation here is far worse than I imagined.\n\nThe Twilight's Blade and their leader, Mor'duun, have completely overrun this city.\n\nWe will use this opportunity to show the Amani how efficient we are at eliminating forces of the Void. Perhaps that will help convince them to stall hostilities between our people... at least until the current threat has passed.", objectives = "" }
WordHunterWoW_QuestEN[86877] = { title = "Righteous Pruning", description = "This is a threat that could destroy all of Harandar if left unchecked. That's why we will pull this out at the root.\n\nThe ruutani who did not have the time to escape this place must be fully corrupted by now. Unfortunate, but it makes our plan of attack simple. Their leaders must be spreading the Lightbloom. We must strike them down.", objectives = "" }
WordHunterWoW_QuestEN[86880] = { title = "Our Beloved, Returned", description = "The haranir had a presence by the roots of Shaladrassil, as a sign of goodwill with the cultures that live within our home. When the guards retreated, they left some of our treasured mementos and artifacts.\n\nSince the spread of the Lightbloom has been greater than I ever expected, I do not know when we'll be able to come back. Let's find those artifacts in the Blinding Bloom and bring them home.", objectives = "" }
WordHunterWoW_QuestEN[86881] = { title = "At the Root", description = "The growths that help them spread the Lightbloom so quickly should be vulnerable after your attack from the air, but we still need to destroy them. Return to the Blinding Bloom and uproot the spreaders before they can recover from our attack.", objectives = "" }
WordHunterWoW_QuestEN[86882] = { title = "Alndust in Right Hands", description = "We can now go to the roots of Shaladrassil and stop the Lightbloom spreading even further into Harandar.\n\nWe have enough Alndust to inoculate any haranir who are willing to risk their lives to follow us into battle. Find them, {name}, and give them the Alndust.", objectives = "" }
WordHunterWoW_QuestEN[86883] = { title = "The Frenzied March", description = "Halduron's news is dire. If the Lightbloom is frenzying on the surface, then the danger has grown far more quickly than we were prepared to reckon with.\n\nWe must make for Eversong at once. I will stand against any threat to Aln'hara's creation, be it here or in the world above... and I will do it alone, if I must.", objectives = "" }
WordHunterWoW_QuestEN[86884] = { title = "Cull and Burn", description = "Simply culling these creatures is not sufficient. If their bodies are left unattended, the Light will seep from their remains and spread through the soil to the surrounding foliage.\n\nWe must take more drastic measures. Gather the bones of the creatures you slay. If we burn them, perhaps we can prevent their further spread through the roots of this forest.", objectives = "" }
WordHunterWoW_QuestEN[86885] = { title = "Stem the Tides", description = "When the Farstriders first discovered the Lightbloom, we thought it to be merely an aesthetic change--a small quirk of the Sunwell's influence. Would that we knew then what we know now.\n\nThese Light-frenzied rootways must lead all the way back to Harandar. If we don't close them, it won't matter how many of these damned things I bring down. Close the rootways and we might have a fighting chance.", objectives = "" }
WordHunterWoW_QuestEN[86887] = { title = "Expeditious Retreat", description = "I have a way to stop the Lightbloom from spreading further through the forest, but it isn't exactly a delicate touch. Normally, I'd never dream of resorting to a controlled burn in such a healthy portion of Eversong... but the frenzy is spreading too quickly, and we are running out of options.\n\nI've sounded the retreat to my Farstriders, but some of them haven't responded. I need you to find any rangers in particularly sticky situations, and lend your aid in securing their escape.", objectives = "" }
WordHunterWoW_QuestEN[86890] = { title = "Tell the People What You Have Seen", description = "We may have stemmed the malignant growth, but we have so many more questions than answers. How did this happen? How did this grow so much? How did Ruia not understand the extent of the calamity?\n\n{name}, we must return to the Cradle immediately. The elders must know what happened today.", objectives = "" }
WordHunterWoW_QuestEN[86891] = { title = "A Last Resort", description = "With our ground forces pulled back, our position will be overwhelmed in a matter of minutes. It's time to execute our gambit.\n\nRommath and the Magisters have provided us a mana gem that can be used to overload Lash'ra's runestones. Take it, and infuse the stones with the mana contained therein. That will set the stage for the Magisters' ritual: to detonate the runestones and burn the entirety of Lash'ra to the ground.\n\nWe just have to hope the Lightbloom cannot survive in an inferno.", objectives = "" }
WordHunterWoW_QuestEN[86892] = { title = "Survive", description = "Our retreat to safer ground has not gone unnoticed. The rutaani mark us at every turn, and now they mean to cross the river.\n\nWe have to buy Rommath and the Magisters as much time as we can. If we fail here, the whole of Eversong could be lost.\n\nStand tall. Do not falter. And do your best not to die.", objectives = "" }
WordHunterWoW_QuestEN[86894] = { title = "The Gift of Aln'hara", description = "Ruia has always been a zealous advocate, but this behavior is beyond the pale. The Lightbloom must be affecting him, driving him to these dangerous lengths.\n\nBut we do not have to be like him. This forest need not fall to the bloom like Shaladrassil's roots did.\n\nThe Hara'ti brought enough Alndust to bolster our allies against corruption, and prevent the frenzy from spreading further. Together, you and I shall spread Aln'hara's gift across the forest. This frenzy shall advance no further.", objectives = "" }
WordHunterWoW_QuestEN[86896] = { title = "Light Finds a Way", description = "I am an expert in the fauna of Eversong, and I can say with certainty that the vast majority of the wildlife here tend to be of fairly average size.\n\nBut these Light-frenzied saptors are decidedly, unequivocally not. One bite from those thorny jaws could claim the lives of half a dozen Farstriders, if they are caught unawares.\n\nMy rangers have their quivers full culling the chaff alongside the haranir. See to it that those towering tyrannosaptors don't catch them unawares.", objectives = "" }
WordHunterWoW_QuestEN[86897] = { title = "Quelling the Frenzy", description = "The day is nearly won. The sin'dorei cull every new sprout that blooms, and the Hara'ti ward the surrounding wilds against the frenzy's influence. All that yet remains is to remove this lightbound serpent's misguided head.\n\nRootwarden Ruia has opposed our every action and shouted down our every word. But he is still a Rootwarden, and one with the power of a frenzying Lightbloom host at his beck and call.\n\nHe is strong. But he does not walk with Aln'hara.\n\nIt is time to end this.", objectives = "" }
WordHunterWoW_QuestEN[86898] = { title = "Rise of the Haranir", description = "It is done. The frenzy is routed, the Rootwarden has fled, and the sin'dorei have reclaimed control of their forests.\n\nI can scarcely believe it, but... we succeeded, {name}. By Aln'hara's grace, we found a path forward.\n\nNow Halduron's people invite us to their den. I am not fond of your surface-cities, but...\n\nYou have aided me so many times, my friend. It is time that the Hara'ti reached out hands of our own.", objectives = "" }
WordHunterWoW_QuestEN[86899] = { title = "The Root Cause", description = "The rutaani who attacked Silvermoon come from my homeland, Harandar. This Lightbloom infection is new, however.\n\nThe time has come for me to return to my people. I will face their judgement, and explain my actions.\n\nIf the Lightbloom has spread, I must warn my people of the danger. If you're willing to join me, I will take you and your insistent friend through the rootways to Harandar.\n\nLet me know when you are ready to go.", objectives = "" }
WordHunterWoW_QuestEN[86900] = { title = "To Har'athir", description = "All of the world's roots grow toward our homeland. The ones above you are mighty, but new--born of a fledgling World Tree you call Amirdrassil.\n\nAs far as World Trees go, it is a strange one. But its nature matters less than its reach. Any roots that seek to protect our world from harm are worth protecting.\n\nLet us follow the road down to Har'athir and check in with the Rootwarden. We will ask if he's noticed signs of Lightbloom yet.", objectives = "" }
WordHunterWoW_QuestEN[86901] = { title = "The Rift and the Den", description = "As I suspected, the elders are quite upset with my actions. Now that I have seen the children and Ku'paal to safety, I am ready to face the Council.\n\nI will do what I can to make them see that the Lightbloom is a threat, and to enable your ability to move freely through Harandar.\n\nPetalvane will carry you safely to the Den. Let us make haste.", objectives = "" }
WordHunterWoW_QuestEN[86902] = { title = "Relinquishing Relics", description = "My staff bought us time in the effort to hold back the Void, but these relics will be a more powerful aid. Let us hope it will be enough.\n\nQuickly, deliver these relics to our friends.", objectives = "" }
WordHunterWoW_QuestEN[86903] = { title = "The Arcantina", description = "{name}, there's a place that we used during the Second War, when we missed our homes an' needed to remember Azeroth. Somethin' of a retreat an' a sanctuary for those who've seen too much fighting--too much pain.\n\nOver time, we've brought friends and allies there. In recent years, members o' the Horde have been invited as well. We call it the Arcantina.\n\nI believe Arator, and you, would benefit from some respite there. Use this key to make a portal.", objectives = "" }
WordHunterWoW_QuestEN[86905] = { title = "No More Sick Days", description = "When we started clearin' out this forest we expected some trouble from the local wildlife but we never expected to be set upon by diseased animals! My work crew keeps gettin' sick and takin' time off to recover. Obviously this is messin' with our bottom line, so perhaps you could clear out some of the creatures so we can start work again?\n\nWhen you're done see my assistant for payment.", objectives = "" }
WordHunterWoW_QuestEN[86907] = { title = "The Den of Echoes", description = "Greetings, stranger. I am Elder Hagar. You have been granted permission to stay, as long as you pass through the trials of the Den of Echoes. \n\nAln'hara will determine your fate, and you will learn about our people and customs.\n\nLet us meet at the caves.", objectives = "" }
WordHunterWoW_QuestEN[86909] = { title = "Unrestful Spirits", description = "", objectives = "" }
WordHunterWoW_QuestEN[86910] = { title = "Koozat's Trample", description = "Koozat is usually very docile. This isn't like him at all. Please, find out what happened.", objectives = "" }
WordHunterWoW_QuestEN[86911] = { title = "Echoes and Memories", description = "The history of the haranir has been recorded for tens of thousands of years in the caves within. The memories of our people are painted on the stone, that we might never forget where we came from and what our purpose is.\n\nYou are the first outsiders to ever witness the Den of Echoes. When you touch the paintings, our ancestors will share our stories and struggles.\n\nZur'ashar Kassameh awaits you within. He will guide you and Halduron on your journeys. I wish you luck.", objectives = "" }
WordHunterWoW_QuestEN[86912] = { title = "Down the Rootways", description = "You have gained a glimpse into our history. There is one trial yet remaining.\n\nIf you survive, the goddess's blessing will be upon you, and the Council will not be able to deny your presence here.\n\nDescend now into the earth and follow in our ancestors' footsteps.", objectives = "" }
WordHunterWoW_QuestEN[86913] = { title = "A Hut in Har'mara", description = "The others have gathered downstairs. Come. Orweyna is eager to see that you are in one piece.", objectives = "" }
WordHunterWoW_QuestEN[86914] = { title = "Tending to Har'mara", description = "Har'mara has long been a refuge for those who have removed themselves from the conflicts that often arise between the rutaani and the fungarians. \n\nHere, they learn how to live with one another. They work, play, and live together--balanced.\n\nYou have learned much about the past of the haranir, including our deepest shame. Now you will see our current work: harmony.", objectives = "" }
WordHunterWoW_QuestEN[86921] = { title = "This is a repro test", description = "Some sickly looking wolves have descended upon the neighborhood and are wrecking havoc with property values! \n\nWe'll never attract new residents at this rate! Could you please get rid of them?", objectives = "" }
WordHunterWoW_QuestEN[86929] = { title = "The Council Assembles", description = "Guards collected Orweyna and took her to get ready to meet the Council. When you are ready, we should attend the gathering.", objectives = "" }
WordHunterWoW_QuestEN[86930] = { title = "To Sow the Seed", description = "Eonka's seed from Rift of Aln is the clue we were looking for. The inhabitants and plants there seem immune to the Lightbloom!\n\nWe must investigate the rift for ourselves. Let us return to the Den and plan our next moves.", objectives = "" }
WordHunterWoW_QuestEN[86934] = { title = "Trash to Profit", description = "Ey! I heard you've been cleanin' up some of the trash around Undermine. Good on ya.\n\nAny interest in takin' that more literally?\n\nIt's a dirty job, but lots of gold to be made if you're good at it. If that sounds up your alley, go talk to the boss man Carlo back at Undermine Sanitation.\n\nTell him I sent ya so I get my recruitment bonus!", objectives = "" }
WordHunterWoW_QuestEN[86935] = { title = "On-the-Job Training", description = "If you're lookin' for work, S.C.R.A.P. is always hirin'. That's short for \"Salvage, Cleanup, and Recl-Amation Patrol.\"\n\nWe go around Undermine shovelin' up trash and pickin' out the good bits. Valuables get brought back here, cleaned up, and resold to whoever's buyin'.\n\nFind somethin' useful and my man Angelo will trade you for it. Go check out what he's got in stock, then find me out in the field and I'll show you the ropes.\n\nBut I mean, it's trash shovelin', not rocket surgery.", objectives = "" }
WordHunterWoW_QuestEN[86936] = { title = "Warped Wood", description = "Our shredders were cuttin' down trees in this area to make room for new homes when they suddenly uprooted and started causin' all kinds of havoc! As if all these diseased animals weren't bad enough, those trees seem hell bent on preventing us from completing this job.  \n\nIf you could clear out a few it would really help speed up our construction efforts.", objectives = "" }
WordHunterWoW_QuestEN[86937] = { title = "Healthy Home Certified", description = "We think we've found the source for all this disease nonsense and wouldn't ya believe it -- a blasted satyr. I hate these guys, always showin' up in places I want to harvest for precious resources.  Do us a favor and get rid of him?\n\nAs always, see my assistant for payment.", objectives = "" }
WordHunterWoW_QuestEN[86942] = { title = "Culling the Spread", description = "Powdercap said that the visiting travelers were the first to show signs of the Lightbloom infection--right after you questioned them!\n\nSadly, it seems Koozat has also fallen to the sickness. Take out the merchants and see to Koozat as well. He's far too dangerous a creature to be trampling around here.", objectives = "" }
WordHunterWoW_QuestEN[86944] = { title = "Seeds of the Rift", description = "The situation is stabilizing, but let's make sure we're in the clear. I will see how Hagar is faring.\n\nCheck on Eonka again and be sure that she's not showing any signs of Lightbloom. She is on an upper level in Hagar's Hut.", objectives = "" }
WordHunterWoW_QuestEN[86946] = { title = "Unwrapped and Unraveled", description = "Seeing you two on the battlefield was beautiful. It really is wonderful watching you work. If only your so-called friends had trusted you with the truth of their actions so long ago. Locus-Walker hasn't tried to deceive you with his actions in the present, though his actions in the past that led us to this point... he has been less than forthcoming about.\n\nIn all good conscience, I cannot continue hiding the truth from you or Alleria.", objectives = "" }
WordHunterWoW_QuestEN[86956] = { title = "The Traveling Flowers", description = "Orweyna mentioned that there are rutaani who are visiting from other villages. This is an opportunity for us to get to know what they're like when they're not Light-crazed.\n\nI will stay here to speak with Meeka. You should speak with the visiting rutaani to determine whether the Lightbloom has reached their homes.", objectives = "" }
WordHunterWoW_QuestEN[86960] = { title = "The Key to Good Health", description = "I'm supposed to be the assigned health advisor for this job but somehow I'm the one who ended up getting sick! I have antidotes in this chest but I lost the key and I suspect one of the local wildlife ate it in the aftermath of being attacked. Be a pal and see if you can find it?", objectives = "" }
WordHunterWoW_QuestEN[86961] = { title = "Diversified Investments", description = "<The letter is simply addressed to \"The {class} who took down Gallywix.\" It takes you a frustrating amount of time to rip open the multiple layers of duct tape sealing the envelope shut.>\n\nHey bud,\n\nYou've been gettin' a reputation for yourself. Not afraid to roll up your sleeves and get down to business. Certain people really value that kind of thing.\n\nLet's talk shop. Meet me in my warehouse and maybe we can agree on a business partnership.", objectives = "" }
WordHunterWoW_QuestEN[86962] = { title = "Blood in the Wound", description = "", objectives = "" }
WordHunterWoW_QuestEN[86973] = { title = "Halting Harm in Har'mara", description = "Lightbloom-infected rutaani are attacking the village! Rizam and Teetem both succumbed to the infection. It looks like Eonka hasn't been affected, but we must handle the others.\n\nI will stay here and keep an eye on her. I need you to do what you can to protect Har'mara. Take out Rizam and Teetem as well.", objectives = "" }
WordHunterWoW_QuestEN[86997] = { title = "Spellbook Scuffle", description = "You there!\n\nI've heard whispers of your so-called \"heroics,\" but I'm convinced they must be false. For if they were true, it would mean you would have achieved more than I, Tytalor Goldenblade--the finest, smartest, and most handsome mage at this academy.\n\nTherefore, I challenge you to prove your worth, if you are not a coward. The arcane tomes will make a fine warm-up for you... if you survive. Tear out their pages and prove you're not a complete fraud.", objectives = "" }
WordHunterWoW_QuestEN[86998] = { title = "Training Arc", description = "Hah! You actually managed to defeat the spell books? I suppose even a blind squirrel finds a nut once in a while.\n\nDon't get too proud of yourself though! My followers ahead won't be so easily dismantled by your flailing. When you inevitably fail, I'll be sure to remember this as the moment your arrogance got the better of you.", objectives = "" }
WordHunterWoW_QuestEN[87000] = { title = "No Wood Left Behind", description = "When we were attacked by the local fauna we had to leave behind much of the wood we already harvested. While we are waitin' for you to take care of our little animal problem, we could be turnin' those logs into planks to get a head start on our buildin' efforts. If you can bring me back any I'd sure appreciate it pal.", objectives = "" }
WordHunterWoW_QuestEN[87001] = { title = "Warrant: Shatterpulse", description = "The horrifying monstrosity known as  Shatterpulse lies hidden in a stasis cell at Shadowpoint. It is not kept as a prisoner, but as a weapon to be unleashed upon us when we are least prepared.\n\nCreate a key to open Shatterpulse's stasis cell revealing this threat to everyone.", objectives = "" }
WordHunterWoW_QuestEN[87002] = { title = "Academic Aspirations", description = "How charming. You've actually made it this far thinking you've proven something. Let me make it clear--nothing you've done compares to my prowess. You've struggled through the simplest of challenges, but now you'll face me. Meet me at the top of this tower and I'll show you exactly how far beneath me you really are.", objectives = "" }
WordHunterWoW_QuestEN[87008] = { title = "Ad-Hoc Wedding Planner", description = "Eeey, now that was a wedding worth talkin' about!\n\nYou did okay. Everything went right and the only hitch was the one my little girl got. So we're good.\n\nI know the bride an' groom wanna say their thanks so go chat with them.", objectives = "" }
WordHunterWoW_QuestEN[87254] = { title = "Curse Cleanse", description = "Warlord Akutu could die at any moment, and you brought no pango liver? Bah!\n\nEach day I scream at Kulzi to tell me how to cure him. I say, \"you force me to use de forbidden liver ritual!\" But de loa says nothin'.\n\n<Loa Speaker Sij'ta's eyes seem angry but also afraid.>\n\nIf he won't tell us what is wrong, then we will have to use de pango liver ritual. It is rumored to be a potent but forbidden ritual.\n\nGet de largest pango liver you can find. There is no time to waste.", objectives = "" }
WordHunterWoW_QuestEN[87256] = { title = "Alternative Medicine", description = "I can't leave de warlord's side. I swore an oath to Zul'jin himself to save de Amani warlords at any cost. If I leave, he is sure to die. He is already cold as death! If he weren't movin' and talkin', I'd swear he was already dead.\n\nThere are things we can do without de loa's diagnosis. Bring me de bloodweed branches dat grow below de shrine. They're very important to de healin' rituals we can still do.\n\nGather me a heap of dem.", objectives = "" }
WordHunterWoW_QuestEN[87267] = { title = "Demands Unmet", description = "Good, we have de branches. We will use them! Above us are de altars where we bring de injured to Kulzi for healin'...\n\n<Sij'ta looks very disoriented.>\n\nWait. I already did this. I brought Akutu up there, an' laid him upon one of de altars. Dat is where he held my hand, made me swear to...\n\nWhat? Why can't I remember?\n\nYou--you're here for a reason. Go get answers. If de loa appears, tell him he's gotta fix dis--or else!", objectives = "" }
WordHunterWoW_QuestEN[87268] = { title = "Required Repentance", description = "I remember dis staff. And I remember dat day.\n\nWe are... dead, then.\n\n<Sij'ta seems to take in the realization with a sort of relief.>\n\nAkutu was near death from a battle in de city. He had some serious wounds. Kulzi said he could not heal dem. Akutu would not accept dis. He wanted me to use de staff--a hexlord staff--on Kulzi to force him to heal.\n\nAnd then... I think I broke it.\n\nShow de other spirits here dis staff. Maybe we can piece together what happened from their memories.", objectives = "" }
WordHunterWoW_QuestEN[87284] = { title = "A Radiant Echo", description = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", objectives = "" }
WordHunterWoW_QuestEN[87289] = { title = "Barreling Down", description = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the dracthyr folk would hurry up and bring the rest of the barrels down here.\n\nSome o' the dracthyr folk have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew!\n\nMind lending a hand to bring those barrels over to Kharanos? And try not to break 'em!", objectives = "" }
WordHunterWoW_QuestEN[87290] = { title = "The Oasis", description = "Hello again, {name}. \n\nVe'nari asked me to find you. She asked that you meet her in the Oasis.\n\nI shall join you shortly. I have some errands to run here first.", objectives = "" }
WordHunterWoW_QuestEN[87291] = { title = "Salad Bar", description = "Hemet, Om'talad, and I have been working together to see what we can do to help the lapbugs. It seems their original food source didn't make it through the collapse of K'aresh!\n\nDo you think you might be able to gather some prickleblooms and lustrous conkers, and put together a little platter for them?", objectives = "" }
WordHunterWoW_QuestEN[87292] = { title = "Rooting for Trouble", description = "Our bees have been marvelous at cultivating the local flora. Some of the plants have seen almost explosive growth.\n\nHowever, the lapbugs have become entangled in their roots. I've been untangling them all morning. Would you lend a hand?", objectives = "" }
WordHunterWoW_QuestEN[87293] = { title = "Shameless Hawking", description = "Lapbugs were once a highly sought after pet here on K'aresh. \n\nI suspect we could use them to attract interested parties in Tazavesh, increasing both support and donations for the Oasis.\n\nI would like you to test this theory.", objectives = "" }
WordHunterWoW_QuestEN[87294] = { title = "A Truth Universally Acknowledged", description = "I have an idea, {name}. Everyone seems to love the lapbugs, so I have enlarged them, given them hats, and placed them in picturesque locations. Take this camera and take some photos with the lapbugs. \n\nIf I am correct, this will go a long way toward increasing support for our efforts.", objectives = "" }
WordHunterWoW_QuestEN[87297] = { title = "Cashing the Check", description = "We got one more thing to set straight.\n\nCome on. Grimla's waitin' for us back in the hotel lobby.", objectives = "" }
WordHunterWoW_QuestEN[87299] = { title = "How Old Are These Things?", description = "Marran tried to declare herself the new ruler of Stromgarde. While some in the army are complicit in her coup, there are still a lot of us who are loyal to Lord Danath Trollbane.\n\nBut when we broke ranks, Marran was ready for us. She has an army of soldiers I've never seen before. They call themselves the Red Dawn, but I think they're just the bandits wearing uniforms they took from our supplies!\n\nHelp us take out her goons and collect any evidence that shows what they really are!", objectives = "" }
WordHunterWoW_QuestEN[87308] = { title = "Twilight's Dawn", description = "The remnants of the Twilight's Hammer are reforming under a new banner, crawling from their holes to pledge allegiance to the Twilight's Blade and their new mistress: Xal'atath.\n\nWe cannot allow this to occur.\n\nStamp them out. The only mercy those who tamper with the Void deserve is a swift death.\n\n<Rommath looks pointedly at Magister Umbric as he says this.>", objectives = "" }
WordHunterWoW_QuestEN[87317] = { title = "Denial Denied", description = "So, I broke de staff. And everybody died.\n\nMaybe dis is my mistake. Sometimes it's too hard to say we made a mistake. And den we made even more mistakes. We in this deep, now.\n\nWhile you were talkin' to the others, I tried to get through to Akutu that we're dead. But he's not listenin'. All he does is blame others. Maybe I deserve it.\n\nShow Warlord Akutu de staff. Den take him to Kulzi. We need to try to talk to de loa.\n\nDe pieces of dis puzzle are fallin' into place.", objectives = "" }
WordHunterWoW_QuestEN[87321] = { title = "Things Left Undone", description = "Hey pal, I can't thank you enough for what you've done for me... and for Undermine.\n\n<Marin glances over at Sprinkle before looking back at you.>\n\nI know you've been busy since Renzik and Gazlowe brought you here, and you keep doing what we've asked of you. But there's one more thing that needs doing.\n\nMeet up with Gazlowe at the hotel. I'm sure he'd appreciate you being there to help.", objectives = "" }
WordHunterWoW_QuestEN[87326] = { title = "deprecates", description = "", objectives = "" }
WordHunterWoW_QuestEN[87327] = { title = "A Challenger's Resilience", description = "Wow {name}, you've taken on some unbelievably scary dungeons AND lived to tell me about it!\n \nCome speak with me and I'll see about making your most challenging Keystones more Resilient.", objectives = "" }
WordHunterWoW_QuestEN[87328] = { title = "Truly Horrific to Behold", description = "{name}, we have much to discuss. The new threat of the Void is one that puts us all at risk. But this is not our first time. There are clues in our past encounters. \n\nSo is the case for the Black Blood. In the past, N'Zoth used it to induce visions. \n\nPerhaps we can figure out how to counter its effects by returning to these moments. \n\nCome, help me set up the portal.", objectives = "" }
WordHunterWoW_QuestEN[87329] = { title = "Into the Darkest Memories", description = "Are you prepared? \n\nThe path through the timeways has been opened to where we last entered the visions. \n\nExpect your sanity to be tested. You probably will not last long on this first attempt. \n\nThe portal is ready for you, {name}. Journey forth.", objectives = "" }
WordHunterWoW_QuestEN[87332] = { title = "A Collection of Variables", description = "My assistant Augermu has been monitoring you and the timeways while you were in the past. He has a way for you to replicate gaining some of the boons adventurers used the first time they faced these visions.  \n\nGive him some of the displaced corrupted mementos you gleaned from your experience for further analysis.", objectives = "" }
WordHunterWoW_QuestEN[87335] = { title = "Echoing Lessons", description = "We can use your displaced corrupted mementos to create Echoes of N'Zoth. \n\nI don't want to bore you with the details unless you want to hear. \n\nNo? Oh well. \n\n<Augermu appears slightly disappointed.> \n\nThe more echoes you have, the closer we can get you to a version of yourself that's more prepared for the visions. \n\nSo, let's get started.", objectives = "" }
WordHunterWoW_QuestEN[87336] = { title = "Remembering Again and Again", description = "Now that we have the hourglass calibrated to you, you can re-enter Horrific Visions whenever you like. No need for keys when traveling back in time!\n\nThat said, we do face one limitation. The hourglass is still fragile, and I must harden it week to week to support additional Echoes of N'Zoth. Who knew that memories of an Old God were so dangerous...?\n\nWell, you should report back to Soridormi and get back to it!", objectives = "" }
WordHunterWoW_QuestEN[87337] = { title = "Custodian Duties", description = "Ve'nari is very busy. While both her and Om'talad are away, I will give you your orders.\n\nWe have many creatures here in the Oasis. They make messes. Go clean them up.", objectives = "" }
WordHunterWoW_QuestEN[87338] = { title = "Day One Orientation", description = "We've taken some of the native species we saved out of stasis. We will need to recreate their habitats.\n\nThere are two primary species here, as well as this console to monitor species in the Oasis. I recommend acquainting yourself with these creatures before we begin.", objectives = "" }
WordHunterWoW_QuestEN[87339] = { title = "Ongoing Activities", description = "While you will be on assignments that befit your skill set, there are also additional tasks that need to be done in the Oasis on a regular basis.\n\nWhile these are typically done by the custodians, if you are in the area I would not say no to your assistance with them. Now, and in the future.", objectives = "" }
WordHunterWoW_QuestEN[87340] = { title = "Junk Mail", description = "One final item before we begin--a special task suited to your unique capabilities. \n\nNo, not killing. Flying. The Oasis requires donations. Donations come from advertising. \n\nTake these stacks of fliers and distribute them around Tazavesh.", objectives = "" }
WordHunterWoW_QuestEN[87341] = { title = "Barreling Down", description = "If it's ale you're looking for, we've got plenty to sample! Or at least we would if the Dracthyr folk would hurry up and bring the rest of the barrels down here.\n\nSome of the Dracthyr have come to celebrate here with us and decided to help transport the ale. Rolling barrels? That's no way to treat a good brew!\n\nMind lending a hand to bring those barrels over to Razor Hill? And try not to break them.", objectives = "" }
WordHunterWoW_QuestEN[87342] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[87343] = { title = "Warrant: Hollowbane", description = "Shadowguard forces in Shadow Point have rallied around an enigmatic champion know as Hollowbane.\n\nThough the Hollowbane's existence is unconfirmed, we have located a travel portal supposedly used by the champion.\n\nUnlock the portal and expose Hollowbane so they may be confronted and eliminated.", objectives = "" }
WordHunterWoW_QuestEN[87344] = { title = "A Key Threat", description = "Tazavesh is a city rife with turmoil, beset by countless dangers. We could always use your help.\n\nCheck our warrant board, and see if you have what it takes to eliminate our most wanted threats.", objectives = "" }
WordHunterWoW_QuestEN[87345] = { title = "Warrant: Xy'vox the Twisted", description = "Xy'vox the Twisted the former constable of Tazavesh, hailed from a powerful cartel family.\n\nUnknown to most, the family's power was obtained from illegal crimes, all conveniently overlooked by Xy'vox.\n\nWhen the truth came out, Xy'vox went into hiding. I believe the constable never left town, instead hides here in plain sight, continuing criminal activities.\n\nCreate a Refuge Dampener to reveal Xy'vox to all of Tazavesh.", objectives = "" }
WordHunterWoW_QuestEN[87347] = { title = "Bubbling Brews", description = "Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it!\n\nTake a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", objectives = "" }
WordHunterWoW_QuestEN[87349] = { title = "Bubbling Brews", description = "I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews and crashing them all over the place! Well, we shouldn't let the brew go to waste if we can help it!\n\nTake a barrel and take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", objectives = "" }
WordHunterWoW_QuestEN[87355] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[87356] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[87357] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "" }
WordHunterWoW_QuestEN[87374] = { title = "C.H.E.T.T.ing In", description = "<You notice your bags feeling slightly heavier just as you catch a glimpse of a shadow moving away from you.\n\nA quick search uncovers a card you don't recognize.\n\nOne side has, simply, \"C.H.E.T.T.!\". The other is a condensed map of The Undermine with directions to The Incontinental's second floor.>", objectives = "" }
WordHunterWoW_QuestEN[87388] = { title = "A Bigger Beast", description = "Return to Umbric? But we're on the brink of deeper understandings!\n\nHypothesis: there exists an apex predator amongst these creatures that might hold immense power! And this predator's relationship with the Void could further our own understanding of the infinite darkness.\n\nEradicate some of the smaller creatures and see if such a beast answers the call of violence!", objectives = "" }
WordHunterWoW_QuestEN[87391] = { title = "Sampling the Local Fare", description = "This place is a food chain of ferocity and far too many teeth.\n\nOur studies grow more dangerous by the minute, but if Matrean insists on staying, we may as well assist him.\n\nWe're studying a link between the nature of these creatures and the Void's accumulation here. \n\nDispatch some of the beasts below and bring samples of their tissue back to me. We can study them to learn more of their connection with the Void.", objectives = "" }
WordHunterWoW_QuestEN[87392] = { title = "Cargo Conspiracy", description = "The Sunwell's radiance may shine, but its Light has not purged the filth that festers within this city. Smugglers scuttle through the streets like vermin, preying upon the desperate and enriching the spineless.\n\nYet, there are whispers of something fouler still--trade in wares so vile that even the Venture Company would recoil. I require someone to spy on each shipping company and find out which cloaks a smuggling ring.\n\nWill you stand with me, or will you turn away as the rot spreads?", objectives = "" }
WordHunterWoW_QuestEN[87393] = { title = "Warranted Search", description = "Tideborne Freight, is it? A name far too polished, like an ornate blade designed to distract from the blood it has shed. Smuggling through the port... but I suspect this venture involves something far more perilous than we think.\n\nWe must act with haste before they set sail and vanish into the mists. Keep your weapons honed and your senses sharper. Make them understand that crossing me was a grave miscalculation.", objectives = "" }
WordHunterWoW_QuestEN[87394] = { title = "Supplier Surveillance", description = "This note all but drips with guilt, but mere words alone will not bring down Tideborne Freight. I require undeniable proof--evidence so damning that not even their well-bribed magistrates can turn a blind eye. That is where you come in.\n\nTake this arcane recorder and make your way to the docks. Document their shipments, their crew--anything that reeks of smuggling.\n\nA single image can speak volumes, and I intend to make every word count.", objectives = "" }
WordHunterWoW_QuestEN[87395] = { title = "Below the Brine", description = "Discarding crates into the ocean? How utterly desperate.\n\nWhatever they seek to conceal must be damning--sufficient enough to unravel their entire operation, should we recover it.\n\nTake a deep breath and retrieve it before the current sweeps it away. Every thread we pull unravels their scheme further. Soon there will be nothing left but the ruin of their own making.", objectives = "" }
WordHunterWoW_QuestEN[87396] = { title = "Dead to Rights", description = "Tideborne's decision to discard crates into the ocean was no mere error. It was a calculated delivery.\n\nPursue them, and ensure the naga are reminded of the grave consequences they face when they dare to cross us.", objectives = "" }
WordHunterWoW_QuestEN[87397] = { title = "Cargo Collateral", description = "If the naga manage to siphon the remaining arcane energy from those unstable arcana, they will gain the very power they seek.\n\nDestroy, incinerate, shatter them--do whatever is necessary. Ensure not a single shard remains for the naga or Tideborne to exploit. I do not wish to see even the faintest trace of arcane energy linger.", objectives = "" }
WordHunterWoW_QuestEN[87398] = { title = "Smuggler Showdown", description = "The naga acted out of desperation. Tideborne's crew, however, is driven by arrogance. They sit smugly aboard their ship, convinced of their invulnerability and counting their ill-gotten wealth. It is time we put an end to that.\n\nCaptain Bloodwake shall be made to answer for every crate, every transaction, and every transgression. Are you prepared to extract the truth?", objectives = "" }
WordHunterWoW_QuestEN[87399] = { title = "Facing the Sun", description = "This sanctum was studying the Lightbloom well before the incident at Fairbreeze. We had no reason to be concerned over their research up until that point.\n\nHowever, the last message we attempted to send never received a reply. And this doesn't look good now that we're here.\n\nWe need to clear out some of the wildlife first, though. We cannot risk any contamination.", objectives = "" }
WordHunterWoW_QuestEN[87400] = { title = "Scattered in Sunbeams", description = "We've given the garden tenders some space to continue their work unimpeded. Hopefully they can keep this place pristine until Silvermoon has the chance to fix it up.\n\nBut now we need to figure out where the missing scholars are. They were studying mana influence on plants in the gardens toward the back. Perhaps we'll find a sign of them there.", objectives = "" }
WordHunterWoW_QuestEN[87401] = { title = "Gardener Mishap", description = "The sanctum door seems to be locked. Probably from the inside.\n\nI believe an arcane construct is used for heavy lifting and general upkeep alongside the treants. The core of it should override the lock on the door and work as a master key. I doubt it will just let us take it, so be careful.", objectives = "" }
WordHunterWoW_QuestEN[87402] = { title = "The Light Provides", description = "We need to get into the Sanctum. Now.\n\nBurn away the roots on that door! And be prepared--nothing good can be behind it.", objectives = "" }
WordHunterWoW_QuestEN[87405] = { title = "Warrant: Grubber", description = "A massive worm has been spotted lurking in the Scrapdrift Sands east of town. The locals have nicknamed it Grubber.\n\nTragically, we lost deputy Zo'wie when he went out to investigate.  The creature pulled him under the sand.\n\nDevise a method to lure the worm into revealing itself, so it may be eliminated once and for all.", objectives = "" }
WordHunterWoW_QuestEN[87406] = { title = "Inoperative Mega-Mecha Gorilla", description = "<Despite your best efforts, the machine remains silent.\n\nMaybe a local expert could get it working.>", objectives = "" }
WordHunterWoW_QuestEN[87408] = { title = "Being Spiritual", description = "We have perfected creating existing creatures, but I would like to go one step further. I would like to try this process with a creature that did not survive the Devouring. \n\nThis world once had a creature called a k'arroc. Locate its essence and gather it for me.", objectives = "" }
WordHunterWoW_QuestEN[87409] = { title = "From Death, Life", description = "We have only to let the machine do its work now. \n\nI will let you do the honors. If it fails, I will place the blame on you...\n\n... I jest, my friend. Mostly.", objectives = "" }
WordHunterWoW_QuestEN[87410] = { title = "Percussive Negotiation", description = "The k'arrocs are big and they're going to need tae stretch their wings sooner or later. Let's plan for it, eh? \n\nThe Shadowguard have all sorts of void shielding going on. I bet you could get parts from them using your usual method of negotiatin' with enemies. Take the parts to Ve'nari when you're done.", objectives = "" }
WordHunterWoW_QuestEN[87411] = { title = "Making Stuff to Look Tough", description = "I suppose we can construct the void shield Hemet imagined, but these parts are not ideal. Meet me outside the Oasis to the east and we shall see if we can craft a workable solution.", objectives = "" }
WordHunterWoW_QuestEN[87412] = { title = "K'arrocing Photos", description = "We must keep our documentation updated. That means I require your services once more. \n\nTake this camera and gather more photos of the k'arrocs. You'll find them on the rocks around the area.", objectives = "" }
WordHunterWoW_QuestEN[87413] = { title = "Bird Bath", description = "{name}--just the person I needed! The k'arrocs are gettin' so dirty that it's covering up their natural smell. There's not enough water here for them to bathe!\n\nTake this anima vacuum. It'll take that dirt straight off 'em, but you're gonna have to stick to the ones on the ground. Try looking on top of the rocks to the north!", objectives = "" }
WordHunterWoW_QuestEN[87414] = { title = "Medical Maneuvers", description = "It would be good to get a solid medical checkup on the k'arrocs. \n\nWould you shrink them down and bring them to me?", objectives = "" }
WordHunterWoW_QuestEN[87415] = { title = "The Skies of K'aresh", description = "The shielding device you helped with has been tested. It is ready for its first flight, if you will forgive the turn of phrase.\n\nSpeak with Om'torid. They have a course picked out for you and the k'arroc to soar along.", objectives = "" }
WordHunterWoW_QuestEN[87417] = { title = "Worldsoul: Dungeons", description = "The enemies of Khaz Algar rise up, unified in the suffering they inflict on those who do not believe in their causes.\n\n<Faerin pauses, then takes a quick glance at the table in front of her before returning her gaze to you.>\n\nShow these people the light, {name}. If they cannot see the error of their ways, please show them a merciful conclusion to their beliefs.", objectives = "" }
WordHunterWoW_QuestEN[87419] = { title = "Worldsoul: Delves", description = "These lands house many deep crevices, leaving shadows where our enemies believe they are safe. Explore these hidden places and leave our enemies no sanctuary.", objectives = "" }
WordHunterWoW_QuestEN[87422] = { title = "Worldsoul: Undermine World Quests", description = "Undermine may be a place I do not understand, but they too are in need of aid. Our conflicts inflame their situation, it would do good to help them move forward.\n\nGo there and help them. See what you can do to bring these... cartels closer together, and to us.", objectives = "" }
WordHunterWoW_QuestEN[87423] = { title = "Worldsoul: Undermine Explorer", description = "Undermine is held together by an intricate design of innovation, hard work, allegiance, and it seems like the sheer will of the goblins. Rather than cower in their sunless cave, the goblins have built a city that thrives on motion and activity. We can learn much from that.\n\nAfter not seeing new faces for years, they bring a new light to our lands. Go help them in whatever ways seem fitting.", objectives = "" }
WordHunterWoW_QuestEN[87424] = { title = "Worldsoul: World Bosses", description = "Hallowfall is not the only land beset by enemies. \n\nGreat monsters threaten our allies. Wherever the shadows of our war have fallen, savage beasts and cunning fiends rise up. They murder Arathi, earthen, and the others who stand with us. Innocent farmers to great warriors. \n\nI know the Sacred Flame burns in you. You are our best hope to hunt these great evils.", objectives = "" }
WordHunterWoW_QuestEN[87455] = { title = "Trials and Tabulations", description = "In hindsight, we should have gone drinking in neutral territory.\n\nGidwin and I were here in Silvermoon on vacation when the Fourth War broke out. We escaped the city but left behind a... rather large bar tab.\n\nGidwin's run off to the place we were staying to find an expensive item we'd left behind, but he's late. Would you go find him while I keep this debt collector busy? He should have been back by now.", objectives = "" }
WordHunterWoW_QuestEN[87456] = { title = "Souvenirs Scattered", description = "When Tarenar and I escaped the city before, we left some things behind.\n\nAn open bar tab, sure. But we'd also bought souvenirs for some of our friends.\n\nCould you look around for them? They're somewhere in this mess.", objectives = "" }
WordHunterWoW_QuestEN[87457] = { title = "What We Do Best", description = "That spider! It blasted me right as I walked in the door. I've been gooped by one spider too many, what with all the nerubians we've been punching lately!\n\nI saw something around its neck out of the corner of my eye. It's an artifact we found while fighting the Legion. It ought to fetch a good price.\n\nYou just have to tear that spider's head off!", objectives = "" }
WordHunterWoW_QuestEN[87458] = { title = "Debts Paid", description = "That's everything, I think. Can't believe it's been so long since the Fourth War. We left in such a rush.\n\nLet's get that necklace to Tarenar. He's been waiting long enough.", objectives = "" }
WordHunterWoW_QuestEN[87475] = { title = "Sureki Incursion: Hold the Wall", description = "Flames! Those chitinous vermin are relentless!\n\nWe've received reports from Auralia Steelstrike that a small force of nerubians are harassing the outer perimeter of the city.\n \nRegroup with our allies on the outskirts of Mereldar and join the fight!", objectives = "" }
WordHunterWoW_QuestEN[87476] = { title = "Midsummer", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87477] = { title = "Sureki Incursion: Southern Swarm", description = "The Sureki aren't known to give up their assaults so easily.\n\nReports from our southern holdings have warned of a swarm stirring along the mountain range. \n\nI don't know whether they plan to hit Tenir's Ascent or Beledar's Bounty, but we cannot wait for them to make the first move.\n\nJoin our allies and intercept the swarm!", objectives = "" }
WordHunterWoW_QuestEN[87478] = { title = "[DNT] Repeatable - Camp 005", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87479] = { title = "[DNT] Repeatable - Camp 006", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87480] = { title = "Sureki Incursion: The Eastern Assault", description = "There's no time to rest, {name}!\n\nOur earthen allies in eastern Hallowfall have spotted a Sureki battalion preparing to attack Dunelle's Kindness--they must be targeting the Dawntower!\n\nFlame's Radiance reinforcements are securing the town and Lothar's Landing as we speak.\n\nHead east and lend what aid you can!", objectives = "" }
WordHunterWoW_QuestEN[87481] = { title = "[DNT] Repeatable - Camp 008", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87482] = { title = "[DNT] Repeatable - Camp 009", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87485] = { title = "[DNT] Repeatable - Camp 010", description = "[DNT] Default Description", objectives = "" }
WordHunterWoW_QuestEN[87496] = { title = "Benefit Packages", description = "Times are rough, so the cartels have been tryin' out this new business strategy called \"employee retention.\" Never heard of it before, but it sounds fancy.\n\nAnyway, I'm pretty sure it means givin' employees the privilege of buyin' stuff from the company stores after you work for 'em long enough.\n\nGo check out what the cartels got for sale. See if anything catches your eye before you start workin'.", objectives = "" }
WordHunterWoW_QuestEN[87546] = { title = "Warrant: Purple Peat", description = "In restoring the eco domes, much of the contaminated plant life was removed, allowing the soil to heal. \n\nHowever, one corrupted lasher escaped our notice. Nicknamed \"Purple Peat\" by the dome technicians, it continues to spread its roots and seeds into Eco-Dome: Primus.\n\nThe plant hides safely in an old stasis cell outside the dome. Construct a device to remove the protective cell and expose the plant so it can be eliminated.", objectives = "" }
WordHunterWoW_QuestEN[87547] = { title = "What's Your Specialty?", description = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared.\n\nYou're strong enough now that you should choose a combat specialization.\n\nThis will unlock a new array of abilities for you to face the dangers within the Dragon Isles.\n\nGo ahead and choose your combat specialization.", objectives = "" }
WordHunterWoW_QuestEN[87550] = { title = "Week 2: We're Really Taking Off", description = "It's Dastardly Duos' second week! Twice the brutality, twice the fun! Win a match this week for even more rewards!", objectives = "" }
WordHunterWoW_QuestEN[87551] = { title = "Week 3: Spread the Word", description = "Hey, you wanna help out the organization? you know, spread the word? Next time you're in a match, throw your Dastardly Banner down in the arena. Show support!\n\nBut be careful -- your opponents might take offense and come straight after you...", objectives = "" }
WordHunterWoW_QuestEN[87552] = { title = "Week 4: They've Heard of You", description = "You're making a name for yourself, {race}. You keep the victories coming and I'll keep the tickets selling.", objectives = "" }
WordHunterWoW_QuestEN[87553] = { title = "Week 5: Another Amazing Week!", description = "<Vinnie is busy counting money>\n\nWhat? Oh, hey {name}. Here to fill more seats-- I mean... here for another match? Great!", objectives = "" }
WordHunterWoW_QuestEN[87554] = { title = "Week 6: It's the Finale!", description = "This is it, the end of the event. Let's go out with a roar!\n\nPut on one last good show and we can count our money together!", objectives = "" }
WordHunterWoW_QuestEN[87555] = { title = "Home Is Where the Hearth Is", description = "Before you head off, you'll want to get yourself a Hearthstone. \n\nThis little stone will return you to the inn where you last bound it to.\n\nIt's not much of an \"inn\", but the explorer's have a tent set up. \n\nTest out that new mount of yours and ride over to Happy Hal. He'll get you sorted out with a Hearthstone.", objectives = "" }
WordHunterWoW_QuestEN[87562] = { title = "Aiding the Dragon Isles", description = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span.\n\nToddy Whiskers of the Dragonscale Expedition could use your help.\n\nSafe travels, {name}. I look forward to our next meeting!", objectives = "" }
WordHunterWoW_QuestEN[87581] = { title = "No More Walkin' Here", description = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at Shipping and Handling and see if she'll lend you some wheels.", objectives = "" }
WordHunterWoW_QuestEN[87582] = { title = "Delves: Site of Madness", description = "Hey, pal. Some real weird stuff has been happening south of Gutterville.\n\nSome of my friends have gone missing, and their family's worried about them. How about you take that can-do attitude of yours down there and see if you can figure out what happened?\n\n<Paks scratches his chin before looking back at you.>\n\nI'm sure there will be some compensation to make it up to you too. Trust me.", objectives = "" }
WordHunterWoW_QuestEN[87583] = { title = "Delves: The Sluice Contains the Juice", description = "Buddy, pal, {class}. Some Darkfuse have taken root down in the sewers here in Undermine. They're shaking down hard-working goblins for cash, stealing their lunches, and sometimes even destroying their flamingo lawn ornaments!\n\nThose Darkfuse suffer from a real lack of decorum, let me tell you.\n\nI know you'll do the right thing and help us out, especially after such a tearjerker of a story.", objectives = "" }
WordHunterWoW_QuestEN[87672] = { title = "Void is in the Air", description = "We void elves all face the same risk... that should our resilience falter, madness awaits.\n\n<Kelia frowns in Matrean's direction.>\n\nThe caves below are steeped in Void's vile touch. Void Surges erupt from the earth, creating a miasma of filth that fills the nesting grounds.\n\n<She hands you a magical device.>\n\nTake this. It will capture the surges of dark energy bursting from the soil. We will study them safely back at the Ingress.", objectives = "" }
WordHunterWoW_QuestEN[88652] = { title = "Faceless Mask of the Nemesis", description = "There are those enemies that you will battle or come into conflict over and over. Thought defeated they return from the shadows to attack you again and again. This is is the heart of a true nemesis. And, these are the enemies that will live on forever no matter what you do.", objectives = "" }
WordHunterWoW_QuestEN[88653] = { title = "Yolks on You", description = "Our research has proven fruitful. I can feel the promise of power beckoning. Do you hear it, {name}? The apex predator calls to us. The beast must be nearby.\n\nWe must gather tribute. Yes... we must offer it a gift of vitality! We must meet it bathed in the essence of the young...\n\nSome of the smaller creatures are nesting in the tunnels below. Break a few eggs and bathe in their juices. Then, perhaps, the beast will be drawn to the smell!", objectives = "" }
WordHunterWoW_QuestEN[88655] = { title = "Outbound for Outland", description = "Snakes! Why'd it have to be snakes?\n\nVe'nari says they used to have snake-like things on K'aresh before the Devouring. None of 'em survived. They still got worms, but that's nae what we're after.\n\nI know just the place--my ol' stomping grounds in Nagrand on Outland.\n\nLet's use this infernal contraption of a portal to get there.", objectives = "" }
WordHunterWoW_QuestEN[88656] = { title = "Comfort Stones", description = "Right then. We're gonna need tae collect things tae make the snakes comfortable on K'aresh. Let's get 'em some bedding.\n\nSome of the most important things are rocks! Snakes can sun themselves atop a rock or hide under it.\n\nThose nearby earth elementals were always a pain in our side. See if you can get some rocks from 'em.", objectives = "" }
WordHunterWoW_QuestEN[88657] = { title = "Zangarmoss", description = "Next up, we'll be needin' some moss for their beds. Sorry to say, but we need to go into the slimy marsh for 'em.\n\nThe naga control that place. It grows on their mushroom trees. They're also fond o' munching on it or something foul.\n\nFastest way to Zangarmarsh is through the pass to the north. If it were me, I'd look around the Darkcrest Shore.", objectives = "" }
WordHunterWoW_QuestEN[88658] = { title = "Sneks and Things", description = "O' course, we also need some snakes. That's the whole point o' why we came out here in the first place.\n\nYou can find the small ones we want down in the Telaari Basin to the south. Just rustle their dens an' they'll come slitherin' out. That's where the plants they like grow.\n\nSpeaking of which, make sure to get some o' them fragrant plants while you're at it. Ye might not know this, but snakes have a keen sense o' smell.", objectives = "" }
WordHunterWoW_QuestEN[88659] = { title = "More Cozy Beds", description = "We need all sorts o' replacements for things--stones and moss for the beds, and more o' them stinky flowers.\n\nRemember, ye can get the stone from the earth elementals in Nagrand. The flowers are down in the Telaari Basin there in Nagrand as well. An' the moss is over at the Darkcrest Shore in Zangarmarsh.\n\nIt'll be a good excuse for me tae go see the gang again. Meet ye on the other side o' the portal.", objectives = "" }
WordHunterWoW_QuestEN[88660] = { title = "Snakes on a Plane", description = "Last, but certainly not least, we need to get those two snakes off o' me plane!\n\nI dunno how long snakes normally live, but it seems like those two have been there forever. And they always look at me funny if I come near.\n\nMaybe you could go get 'em?", objectives = "" }
WordHunterWoW_QuestEN[88661] = { title = "To the Atrium", description = "We got what we're after. Time to head back.\n\nBefore we can introduce the snakes to the ecology in the Oasis, we need to test 'em out. There are a few o' these place they call eco-domes where that's done on K'aresh.\n\nVe'nari's portal will take us to one called the Atrium. I wish I could fly me plane there instead.", objectives = "" }
WordHunterWoW_QuestEN[88662] = { title = "What's in a Name?", description = "Though they clearly don't like me, I think the two snakes from me crashed plane have taken a liking to you.\n\nYe want to name 'em?", objectives = "" }
WordHunterWoW_QuestEN[88663] = { title = "Scales and Measures", description = "Now to get some vital statistics. Ve'nari and her people have all sorts o' contraptions for doing things around here.\n\nThis li'l robot is gonna use the thing the snakes are on to take some measurements. Just speak with it when you're ready.\n\nI can get readings for the rest o' the snakes while you're off doing other things.", objectives = "" }
WordHunterWoW_QuestEN[88664] = { title = "Nagrandification", description = "Remember all those stinky plants ye gathered up in Nagrand? Would ye mind replanting 'em?\n\nWe don't have to plant 'em all right now. Just enough to test and ensure they'll take to the soil of K'aresh.\n\nWe'll be needin' a lot more plants than this eventually.", objectives = "" }
WordHunterWoW_QuestEN[88665] = { title = "Follow Your Tongue", description = "Now it's time to move north into Eco-Dome: Primus. That's a mouthful.\n\nTake one o' the remaining stinky flowers an' lead the snakes there.", objectives = "" }
WordHunterWoW_QuestEN[88666] = { title = "Mossy Beds", description = "I've put together the rocks an' the moss that ye collected in Nagrand. Now it's time to see if the snakes like 'em.\n\nI spread 'em out around the eco-dome so you could test 'em out for differences.\n\nWhile you're doing that, I'll make preparations for getting 'em all to the Oasis.", objectives = "" }
WordHunterWoW_QuestEN[88667] = { title = "Water Snakes", description = "Oh no! Some o' the snakes are having trouble adapting. They aren't drinkin' as much as they should an' are dehydrated.\n\nQuick, {name}. Take this waterin' can and give 'em a good dousing.", objectives = "" }
WordHunterWoW_QuestEN[88668] = { title = "Ophidian Portation", description = "Our tests are successful! Time to move to the Oasis.\n\nVe'nari gave me these \"portation\" devices to quickly get the snakes o'er there.\n\nWhy don't you take care o' Ember and Indigo, and I'll take care o' the rest? They've been giving me the side-eye ever since I moved 'em here.", objectives = "" }
WordHunterWoW_QuestEN[88669] = { title = "Nesting Time", description = "We need to set up a nice home for these two, especially since Ember's expectin'.\n\nI took a look around an' spotted a shady place under a tree not far from here.\n\nThere's all sorts o' things to make 'em comfortable an' safe. Use Ve'nari's portation tags again to summon in everything ye need.", objectives = "" }
WordHunterWoW_QuestEN[88670] = { title = "Soothing Serpents", description = "Most o' the snakes did not like Ve'nari's teleport. Others were cloned by Om'talad, an' they don't like that either. They're clearly agitated an' I'm afraid they're gonna hurt themselves.\n\nI've got this flute. Don't ask. I can't even play the darned thing.\n\nWould ye take it out there an' soothe the snakes with some calming melodies?", objectives = "" }
WordHunterWoW_QuestEN[88671] = { title = "Eggstra Eggs", description = "I've been talkin' with the others about food for the snakes, an' we think we have a solution.\n\nThe k'arrocs have been prospering a wee bit too much for the ecology o' the Oasis. If ye get some o' their eggs, that should be enough for now so we can feed the snakes.", objectives = "" }
WordHunterWoW_QuestEN[88672] = { title = "Snakelets!", description = "Speaking o' eggs--I checked, an' Ember has laid her clutch. It's almost time to hatch us some babies!\n\nMeet me back at the nest an' we can welcome our first snakelets to K'aresh.", objectives = "" }
WordHunterWoW_QuestEN[88696] = { title = "The Devouring Citadel", description = "I must return to Silvermoon, but Turalyon has commanded all able-bodied champions of the Light to meet him at the muster point outside the Voidspire.\n\nThe forces of the Devouring Host will fall, {class}.\n\nOne way, or the other.", objectives = "" }
WordHunterWoW_QuestEN[88697] = { title = "Clarity of Purpose", description = "The ethereals on the nearby plateau are forcing us to ground our heavier weapons. We'll need to neutralize their turrets before we can begin our assault on the Voidspire.\n\nSpeak to Umbric and he'll help you gain a tactical understanding of the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[88698] = { title = "Master of Mayhem", description = "{name}, ethereals have been striking out from the Ethereum Overcroft, harassing our Vanguard forces where they find them. If you can bring the fight to them, it'll take the pressure off our muster.\n\nCan you do that for us?", objectives = "" }
WordHunterWoW_QuestEN[88699] = { title = "Powerless", description = "Their very life force is being siphoned to power the ethereals' guns, {name}! This cannot be allowed to continue.\n\nHead into the Ethereum Overcroft and free my fellow void elves from the ethereals' clutches. With their freedom, the turrets will have no power, and Turalyon will be able to launch his warframes.", objectives = "" }
WordHunterWoW_QuestEN[88700] = { title = "Two Tons of Metal and Holy Fire", description = "Finally, the might of our warframes can be brought to bear.\n\nWith the Overcroft's air batteries silenced, our powerful warframes will be able to perform strafing runs along the spire ramparts, softening the opposition to our siege.\n\nIf you'd like, you may have the honor of piloting one of these warframes for the glory of the Light!", objectives = "" }
WordHunterWoW_QuestEN[88701] = { title = "The Memory Remains", description = "Our Vanguard forces have been harrying the Devouring Host, probing for weaknesses and gathering intelligence.\n\nUnfortunately, nearly all of them have succumbed to the Host. We are too late to help those who have fallen, but perhaps we can gather something to remember them by.\n\nWill you do this, {name}? Recover mementos of the fallen so they can be returned to those they fought to protect.", objectives = "" }
WordHunterWoW_QuestEN[88702] = { title = "Aegis of the Redeemer", description = "We're more than just an army, {name}, even if my father doesn't see that.\n\nWe're a fellowship, joined by a desire to protect those that matter to us, and those that don't have a protector of their own.\n\nAnd now, that protection extends to those wounded on the battlefield.", objectives = "" }
WordHunterWoW_QuestEN[88703] = { title = "The Night Before", description = "Vicious voidbeasts have been snatching our officers, {name}. I've been told that you saw one from afar, through Umbric's void scryer.\n\nThose beasts are steeped in void energy, using their instinctual mastery of teleportation to strike at our most vulnerable before melting back into the shadows.\n\nAlleria has gone after them, and sent a request for another pair of eyes. You can find her at a campsite at the mouth of the gorge to the east. I'll mark it on your map.", objectives = "" }
WordHunterWoW_QuestEN[88704] = { title = "The Patient Hunter", description = "These void beasts are elusive, able to open temporary void portals that they can use to move short distances instantaneously.\n\nThey may be beneath Turalyon's notice, but they're having devastating effects on the Vanguard's morale.\n\nBetween the two of us, I'm confident we can outmaneuver them.", objectives = "" }
WordHunterWoW_QuestEN[88705] = { title = "Killing Blow", description = "I heard about these beasts, but I thought it was a rumor. Void creatures appearing out of void portals, kidnapping and eating our officers... sounds like a load of bunk. I never thought it'd happen to me.\n\nThere was a big one that got me, but he ran off. Please, let's get out of here before it comes back!", objectives = "" }
WordHunterWoW_QuestEN[88706] = { title = "Nothing Stands Forever", description = "With the Patriarch defeated, these cunning creatures should no longer pose a serious threat.\n\nReturn to Turalyon and report on our success. I will join you all shortly.", objectives = "" }
WordHunterWoW_QuestEN[88708] = { title = "Violent Conclusions", description = "Our research here is complete.\n\nConclusion: the Void is attracted to this realm due to its violent nature! The Voidstorm is a melting pot of torment and savagery. The Void was drawn to this aura of endless suffering.\n\nThis place is a dire threat to the ren'dorei. However, our mission here is important. Let us take our findings back to the others.\n\nCan you help me snap Matrean out of it?", objectives = "" }
WordHunterWoW_QuestEN[88709] = { title = "The Voidspire", description = "At long last, we will ride to glory and dispense justice upon this vile creature who would levy the very Void itself against us. \n\nToday is the day Xal'atath's forces will face our judgement.\n\nNow is the hour we strike back!\n\nCome, let us make an end of this enemy.", objectives = "" }
WordHunterWoW_QuestEN[88710] = { title = "March on Quel'Danas", description = "Champion... friend... this is it. \n\nWe must wrest the Darkwell from L'ura, or fall to the Void. We do not have the forces available for a second chance. \n\nStrike hard, and strike true. Watch your allies' flanks, and we will see this day won.", objectives = "" }
WordHunterWoW_QuestEN[88711] = { title = "Radiant Incursion: Toxins and Pheromones", description = "Our allies in Azj-Kahet have identified a strategic location to strike at the Sureki.\n\nAccording to reports, our enemies are gathering toxins to fuel their war machines.\n \nLet's take this opportunity to cut off their supplies, and perhaps better our own understanding of their alchemy.", objectives = "" }
WordHunterWoW_QuestEN[88719] = { title = "A Voice from the Light", description = "{name}, you have been chosen.\n\nXal'atath's army of the Void has descended upon the Sunwell. We have put our faith in the Light, and in turn, the Light has called upon the greatest champions of Azeroth.\n\nAnswer this summons and stand against the Devouring Host! The fate of Quel'Danas and the world rests in your hands.", objectives = "" }
WordHunterWoW_QuestEN[88750] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[88752] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[88755] = { title = "Scholarly Pursuits", description = "{name}... a favor.\n\nMy research partner Matrean and I are studying the local wildlife and their relationship to the Void.\n\nI've concluded my findings, but Matrean--reckless and obsessive as ever--insists there is more to discover.\n\nCan you help convince him to return here?", objectives = "" }
WordHunterWoW_QuestEN[88768] = { title = "Agents of Darkness", description = "When that shield goes down, Xal'atath's forces will be upon us in droves. If I'm going to detonate those manacells from afar, I'll need an opening. Thin the Devouring Host of their strongest, and the rest of Xal'atath's lackeys will be easier to fight off.\n\nWe will make sure the shield goes down in the meantime. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[88769] = { title = "The Battle of the Bridge", description = "Our elven allies have arrived. It is time to take the fight to the Darkwell.\n\nXal'atath's forces hold the bridge and recently pushed into the harbor to reinforce their position. We must retake the harbor, launch our naval forces, and use a combined assault to take the bridge.\n\nAre you ready, {name}?", objectives = "" }
WordHunterWoW_QuestEN[88803] = { title = "Timely Assistance", description = "Hello, Champion.\n\nI have found a way that I may further assist you in the visions. Should you require it, you can call upon my assistance using this hourglass.\n\nI will form a construct that will assist you in the vision.", objectives = "" }
WordHunterWoW_QuestEN[88808] = { title = "A Scarred Journey Through Time", description = "Azeroth calls out in need, champion. She bleeds still from wounds of war. Go forth among Zandalar and Kul Tiras to reveal those who would prolong her suffering.\n\nVanquish foes in her name and defend Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[88903] = { title = "Faceless Mask of Vengeance", description = "Blood begets blood, and the weight of the fallen lingers in the air like a whispered curse. Those who stand witness to your wrath feel it creeping into their bones, driving them to strike harder, desperation masquerading as courage. Vengeance does not end violence. It only feeds the storm.", objectives = "" }
WordHunterWoW_QuestEN[88916] = { title = "Radiant Incursion: Sureki's End", description = "Credible intel has revealed the Sureki are regrouping for another assault. Now we take the fight to them!\n\nThe Flame's Radiance have rallied at Faerin's Advance, and prepare to strike at the Sureki forces amassing in northern Azj-Kahet.\n\nBe warned, soldier. The Sureki in \"Arathi's End\" are greater in number and power. \n\nShould you require aid, our Sacredites in the field should be equipped with potions to assist you.", objectives = "" }
WordHunterWoW_QuestEN[88919] = { title = "Into the Darkway", description = "Ulen's imposter may have escaped, but I suspect I know what the cult has been doing. \n\nThe Twilight's Blade must be redirecting Suramar's mana flow. Without it being sent to the correct places, our awareness dulls, our golems wilt, and our entire society risks a mana withdrawal.\n\nThere is only one place they would be able to exert control over our ley lines like this, and that would be the Arcway. \n\nGo. Find them and crush them. \n\nWe will meet in Silvermoon when you are done.", objectives = "" }
WordHunterWoW_QuestEN[88920] = { title = "The Kaldorei", description = "We must retake the Darkwell and defeat L'ura before the world is torn asunder.\n\nWe will need an army. No. Many armies.\n\nWe need to reach out to the other elves. We should start with the kaldorei at Bel'ameth. Oculeth can teleport a small envoy there and we can present our request.\n\nStill... there has been much blood spilt among the elves. Vendettas that go far and strike deep. Hold on to hope, {name}. It is all we have left.", objectives = "" }
WordHunterWoW_QuestEN[88922] = { title = "The Quel'dorei", description = "{name}, while the kaldorei are mustering, I could use your help as a witness as I ask another group for aid.\n\nWe will need the quel'dorei for what is to come, no matter how much some of the sin'dorei will protest. \n\nOculeth has agreed to open a portal for the two of us to reach my aunt, Vereesa Windrunner, where she awaits us in Eversong.\n\nThe sin'dorei will not come with me. Will you?", objectives = "" }
WordHunterWoW_QuestEN[88923] = { title = "Children of the Stars", description = "You have traveled far to ask my people to march to yet another war.\n\nMaiev's fervor is blunt but not misplaced. While Silvermoon is under threat, let us not forget how many of my people burned when the sin'dorei failed to aid us at Teldrassil.\n\nHowever, Bel'ameth stands tall thanks to their aid. Let each present their reasoning and I shall then make my decision.", objectives = "" }
WordHunterWoW_QuestEN[88925] = { title = "Awaken the Ancient of War", description = "If we are to muster for war, then there is an ancient we must bring with us or they will never forgive us.\n\nThey are a mentor to myself and nearly every sentinel who serves the kaldorei. They are skilled in war, tactics, and rallying our greatest forces.\n\nAnd they fell asleep again. If history is any lesson, they will only awaken with the aid of someone who has known war.\n\nWill you seek out their grove keeper to learn how to awaken them?", objectives = "" }
WordHunterWoW_QuestEN[88926] = { title = "Return to Belanaar", description = "This has been most productive. I suspected the kaldorei might be our the most difficult to convince, but Shandris has turned a new leaf of leadership for her people.\n\nLet this be the first of many successful partnerships between our people.\n\nNow swiftly, {name}. Let us return home and prepare our defense.", objectives = "" }
WordHunterWoW_QuestEN[88927] = { title = "Awaken the Ancient Protector", description = "The enemy we face is a vast host with many capabilities. We will need to match their strength and versatility on the battlefield.\n\nTo that end, I ask that you seek out Elder Verdantbark--an ancient protector who has long kept our people safe in times of war.\n\nThey are stubborn and may require you to entice them in some fashion, but their grove keeper will know best how to do so.", objectives = "" }
WordHunterWoW_QuestEN[88928] = { title = "The Shal'dorei", description = "Champion, your timing is fortuitous. I sent the call for the armies of Suramar to muster, but they have not arrived yet.\n\nMy seneschal should have alerted me if anything went wrong, but I have heard nothing.\n\nI plan to go to Suramar to investigate what is amiss. Would you join me? I may have need of your skills.", objectives = "" }
WordHunterWoW_QuestEN[88929] = { title = "An Illusion!", description = "The mana of Suramar is carefully cultivated, regulated, and controlled. It does not just randomly \"stop.\"\n\nSomeone or something must be interfering with it.\n\nAs you investigate the mana drain, I want you to occasionally dispel illusions in the area. Focus on those gathered here. I suspect not everyone is what they appear to be.", objectives = "" }
WordHunterWoW_QuestEN[88930] = { title = "Drained Mana", description = "I have received no word from High Arcanist Thalyssra for days!\n\nWe have had many mana problems lately, so there is a chance her message spells were simply not able to be received.", objectives = "" }
WordHunterWoW_QuestEN[88931] = { title = "Children of Shadow", description = "[DNT] We cannot leave the children here unguarded.\nThalyssra summons some mechs. Take this and arcanocharge them so they can be big and strong.", objectives = "" }
WordHunterWoW_QuestEN[88932] = { title = "With the Shal'dorei", description = "Our reinforcements will be arriving shortly. Some will stay behind to defend Suramar. The rest will join us in Silvermoon.\n\nThank you for joining me in this journey, {name}. Hold on to the memory of this place in the battles to come. It will shield you from any doubt the void plants within you.\n\nAccompany me back to Silvermoon. We have many allies to find yet if we are to prevail against this force.", objectives = "" }
WordHunterWoW_QuestEN[88937] = { title = "Awaken the Ancient of Lore", description = "While our forces gather, I would like you to have the honor of awakening our ancients.\n\nThere is a particular ancient of lore we will need awakened.\n\nThey are a master of magic, a teacher of our druids, and a force that has walked alongside us across many battlefields.\n\nFind their grove keeper to learn what is needed to wake the ancient.", objectives = "" }
WordHunterWoW_QuestEN[88938] = { title = "Symbols of the Past", description = "Arator's warning is poignant. There will be no small amount of grief or even threats when we return to Silvermoon. \n\nI suspect Aethas and his Sunreavers will bar our passage if we enter without preparations.\n\nTo that end, I have saved some precious remnants of our shared history from before the demise of Dalaran. Would you please gather them for me, {name}?", objectives = "" }
WordHunterWoW_QuestEN[88939] = { title = "Rest for the Restless", description = "Before we are able to make amends with the living, we must lay the dead to rest.\n\nYears ago, I purged Dalaran of all elves allied with the Horde. I blamed them for the actions of the warchief at the time that resulted in the death of my husband.\n\nNow, years later, those ghosts still haunt me. Will you put them to rest and gather their remains? I'll perform some small atonement by bringing these remains to Silvermoon. They deserve to be returned home.", objectives = "" }
WordHunterWoW_QuestEN[88941] = { title = "For Quel'Thalas", description = "It is time for us to return to Silvermoon. I have no doubt we will be greeted as traitors and murderers.\n\nI do not care how we are seen. I care that Quel'Thalas survives.\n\nWill you join us, {name}? \n\nFrom what Arator has said, you have earned more than a measure of respect from Silvermoon. I would be honored if you would assist us in entering the city without incident.", objectives = "" }
WordHunterWoW_QuestEN[88942] = { title = "The Elves are Going to War", description = "We have learned much about the forces we will be facing in the battle to come.\n\nSuramar remembers the debt we owe the sin'dorei for their aid in our time of need. Now that our forces are assembled and our golems prepared, we are ready to defend this city as if it were our own.\n\nCome, {name}. Let us return to Lor'themar. It is time to discuss battle strategy.", objectives = "" }
WordHunterWoW_QuestEN[88945] = { title = "Radiant Incursion: Rak-Zakaz", description = "The nerubian allies you and Lady Faerin made in Azj-Kahet have proven resourceful... for now.\n\nAccording to their intel, Sureki sympathizers have begun to rally at Rak-Zakaz and aid their fallen queen's loyalists in their renewed assaults.\n\nRegroup with our forces at Faerin's Advance and cut off their reinforcements!", objectives = "" }
WordHunterWoW_QuestEN[88947] = { title = "Undermined Delves", description = "There's more tae do in delves, {name}! \n\nMeet me in Dornogal. There's loads to discuss!", objectives = "" }
WordHunterWoW_QuestEN[88974] = { title = "Eco-Stability", description = "Speakin' o' eggs, I checked an' Ember has laid her clutch. It's almost time ta hatch some babies!\n\nMeet me back at tha nest an' we can welcome our first snakelets ta K'aresh.", objectives = "" }
WordHunterWoW_QuestEN[88975] = { title = "Spooked Slitherin' Snakes", description = "Somethin' has the snakes agitated again. Spooked even.\n\nHow would ye feel about taking me flute back out there and calming 'em down?", objectives = "" }
WordHunterWoW_QuestEN[88976] = { title = "The Hope of K'aresh", description = "It is finished. By all measurements, the eco-system in the Oasis is fully stable. While there will always be things we can help with, it would survive if we left it alone. \n\nTake some time and speak with everyone. Congratulate them. Good work should be properly acknowledged.\n\nSpeak with me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[88977] = { title = "Reenact the Crime", description = "Ah, you there! You appear to have the wisdom to assist me, unlike a certain bow-wielding simpleton who thinks sniffing dirt will solve our problem.\n\nWe've accidentally misplaced a very important journal--the sort my mentor would transmogrify me to have lost!\n\nPlease use my arcane timepiece to summon echoes of the past and investigate these moments. That should allow us to find my journal properly, without indulging Vardis's primitive methods.", objectives = "" }
WordHunterWoW_QuestEN[88978] = { title = "Tracking the Trail", description = "While a certain wyrm-brained mage wastes time with his inept magic, we'll actually solve this case.\n\nThe local wildlife has likely eaten the journal. Time to gut them and see if we can recover it.\n\nIf the journal's inside, we'll find it... unlike someone who couldn't track his own insipid ego if it were carved into the ground.", objectives = "" }
WordHunterWoW_QuestEN[88979] = { title = "Caught Red-Handed", description = "A dog, of all creatures? This is the thief we've been chasing?\n\nAnd now we must save it from a lynx? Truly, this day has taken a most... irritating turn.\n\nNo matter, we shall retrieve the journal... though I do wonder if this canine truly understands the gravity of its actions.", objectives = "" }
WordHunterWoW_QuestEN[88980] = { title = "Who You Gonna Call?", description = "We could do with more slateback essence. \n\nI imagine that the opportunity to keep the sand of K'aresh safe would be right up your alley, yes? \n\nJust bring me back what you find after you are done.", objectives = "" }
WordHunterWoW_QuestEN[88981] = { title = "Nesting Upkeep", description = "It's time to refresh Ember, Indigo, an' the snakelet's nest. Gotta keep our K'areshi snakes comfy.\n\nDon't worry 'bout carrying anything down there. Just like last time, we'll use one o' Ve'nari's portation tags for that.", objectives = "" }
WordHunterWoW_QuestEN[88982] = { title = "Prey Contract: Renegade Magister", description = "A RENEGADE MAGISTER has been spotted in Voidstorm!\n\nDifficulty: Normal\n\nAffixes: 0", objectives = "" }
WordHunterWoW_QuestEN[88985] = { title = "Recuperating Returns", description = "One of our lightwood loggin' outposts is late with their weapon shipments. Dey used to be punctual, but now we are lacking crucial supplies.\n\nGo check on de camp. Somethin' must be goin' on.", objectives = "" }
WordHunterWoW_QuestEN[88986] = { title = "Blind the Bandits", description = "Dis elf showed up here seekin' revenge, thinkin' we were responsible for de death of his sister.\n\nBut instead of killin' him, I'm gonna set de boy straight.\n\nDe Amani got no business with some farm!\n\nHe don't understand de Twilight's Blade is attackin' on both sides of de Zul'Aman border!\n\nI don't blame de child. He don't know dat de Twilight's Blade can hide demselves with their void powers.\n\nTake some lightwood splinters. Throw 'em on de shrouded Twilight's Blade. Show him who de real enemy is!", objectives = "" }
WordHunterWoW_QuestEN[88987] = { title = "Salvaged Sabotage", description = "Rakani overreacted when de boy came crashin' into camp, but we all have been on edge.\n\nDe Twilight's Blade had already snuck into our camp and sabotaged our work.\n\nIt has already been challengin' to keep up with de demand for weapons. And our people need de weapons to defend themselves!\n\nIf we can get de broken weapons back, we can maybe make up for what we lost.\n\nWhile you deal with dem, see if you can get any of our weapons back--whatever condition dey are in.", objectives = "" }
WordHunterWoW_QuestEN[88988] = { title = "The Artisan's Apprentice", description = "Looks like de boy has realized there is more in dis world than his family farm an' de big bad trolls of Zul'Aman.\n\nBut I'm not done with him yet. He gonna learn hard work too. De boy needs to make up for de disruption he caused and de work we lost.\n\nIt'll be a learnin' opportunity--for de both of you.\n\nYou are goin' to make somethin' for us.\n\nPay attention. One wrong move can destroy de lightwood. With de Twilight's Blade sabotagin' our equipment, our resources are too limited already.", objectives = "" }
WordHunterWoW_QuestEN[88989] = { title = "Another One Bites the Sawdust", description = "Dat boy is a fool.\n\nBut he's a courageous fool.\n\nIt's time to test dis weapon you crafted.\n\nHe'll be goin' after their commander. He's killed many of my crafters, but revenge is not worth his life or dat of anyone else.\n\nGo after him before he gets himself killed.\n\nI did not go through all dis trouble just for him to die now, eh?", objectives = "" }
WordHunterWoW_QuestEN[88993] = { title = "Wey'nan's Ward", description = "To claim this relic, travel to the Vale of Secrets. Seek the Visionstone. Its surface bears sacred paintings, with a hand print aglow at the center.\n\nPress your hand upon it and let your spirit be known. Your body will falter into trance, and your soul will walk visions of the past.\n\nBe warned: these visions are no mere dreams, and the dangers within may strike true.\n\nReturn to me with the wisdom you uncover.", objectives = "" }
WordHunterWoW_QuestEN[88994] = { title = "The Cauldron of Echoes", description = "For untold eons, the Cauldron of Echoes has rested in shadow, its purpose obscured by time.\n\nWhen I first walked the path of the Zur'ashar, my master spoke of its significance--a relic tied to the very origins of our kind. Yet its secrets eluded even them... a mystery left unanswered.\n\nNow, it calls to us once more.\n\nWill you uncover what has been forgotten? The truth waits within, and I would be forever grateful for your discovery.", objectives = "" }
WordHunterWoW_QuestEN[88995] = { title = "Aln'hara's Bloom", description = "When I was young in the path of a Zur'ashar, I heard a tale of a gift from Aln'hara: \"A sign of the goddess, felt in the stillness.\"\n\nUnfortunately, all those who were there to experience the event eventually passed on before we learned the secrets of our special paint.\n\nWould you walk the memory that surrounds the bloom and find out if this theory is true?", objectives = "" }
WordHunterWoW_QuestEN[88996] = { title = "The Echoless Flame", description = "The Echoless Flame's fate is lost to time. Down through the ages, it was whispered that the lantern contained the power of Aln'hara herself. But now, it lies dormant--a shell without even a flicker left within.\n\nPerhaps you can uncover its secrets where others have failed?\n\nRetrace the steps of Obayo, the first of the Shul'ka, and bear witness to the glory of the relic and its true purpose.", objectives = "" }
WordHunterWoW_QuestEN[88997] = { title = "Russula's Outreach", description = "A weather-worn spear haft, laced with pale mushroom threads, rests in silent vigil. The elders name it Russula's Outreach, yet no tale agrees on what that outreach was, or whom it spared.\n\nWas this weapon raised in fury, or lowered in mercy?\n\nThe relic offers no answers here, only a lingering pull toward the old culling grounds.\n\nFollow that pull. Trace the footsteps lost to rot and rumor, and let the visions speak of what history forgot.", objectives = "" }
WordHunterWoW_QuestEN[88998] = { title = "Root of the World", description = "The Root of the World is the first gift of the land to the haranir, or so it has been said. We have forgotten much about how the staff came to be in the possession of my people. But the root of the story, if you will permit, begins at a time not long after the haranir first came to Harandar.\n\nI trust that together, we can uncover its lost past.\n\nIt is known that Ruilla the Huntress was a pivotal figure in the events that led to the creation of the staff. Go and see history through her eyes.", objectives = "" }
WordHunterWoW_QuestEN[88999] = { title = "Sky's Hope", description = "Sky's Hope: the stone that legend says fell from the sky. Little is known about it besides it being considered a symbol of hope.\n\nBut why?\n\nFollowing in the path of our ancient ancestor, Awe'ohna, might shed some light on the matter.", objectives = "" }
WordHunterWoW_QuestEN[89012] = { title = "A Safe Path", description = "We must rescue the civilians and get them to the ships, yet the path to the docks is barred by a vile, hungering creature.\n\nIf we are to save my people, then we need to clear an evacuation path. We cannot leave them to fend for themselves.", objectives = "" }
WordHunterWoW_QuestEN[89016] = { title = "Members Only", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89018] = { title = "Loyal Customer: Silver", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89019] = { title = "Loyal Customer: Gold", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89020] = { title = "Loyal Customer: Platinum", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89021] = { title = "Loyal Customer: Black", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89022] = { title = "Loyal Customer: Diamond", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89023] = { title = "Loyal Customer: GOLDEN LEGENDARY!!!", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89024] = { title = "Time is Money!", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89025] = { title = "Time is Money!!", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89026] = { title = "Time is Money!!!", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89027] = { title = "Fast Food", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89028] = { title = "Chip Service", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89029] = { title = "Chip Service", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89034] = { title = "Burning Bitterblooms", description = "Lightbloom-infested rutaani are working to spread the contamination through the village. This plant showed significant signs of the disease.\n\nDestroy any of the plants they've come into contact with. We must contain this!", objectives = "" }
WordHunterWoW_QuestEN[89056] = { title = "Ray-ket Ball, Redux", description = "Time again to test the reflexes of our newborn. \n\nPerhaps you could play more ray-ket ball?", objectives = "" }
WordHunterWoW_QuestEN[89057] = { title = "Pee-Yew de Foxy", description = "{name}! Are you ready for a repeat adventure in olfactory excellence?\n\nI've whipped up another concoction for the thorntails. This one's definitely an improvement over the last batch.\n\nWould you be the best and go give it a try?", objectives = "" }
WordHunterWoW_QuestEN[89061] = { title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", objectives = "" }
WordHunterWoW_QuestEN[89062] = { title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", objectives = "" }
WordHunterWoW_QuestEN[89063] = { title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", objectives = "" }
WordHunterWoW_QuestEN[89065] = { title = "Ray-cing for the Future", description = "Looks like we've got another feisty necroray on our hands! Want to tire it out?", objectives = "" }
WordHunterWoW_QuestEN[89192] = { title = "A Hard Day's Work", description = "We are running low on void shields. Your assistance is required to make a new one. \n\nMeet me outside the dome to the east. We shall craft it together.", objectives = "" }
WordHunterWoW_QuestEN[89193] = { title = "Arator", description = "Archbishop Alonsus Faol has left a message asking to speak with you in regards to a project to help Arator and the Vanguard of Light.", objectives = "" }
WordHunterWoW_QuestEN[89194] = { title = "Shake your Bee-hind", description = "{name}--just the {race} I wanted to see! I need you to go dance for m--I mean, bees. \n\nI shall just watch you leave now.", objectives = "" }
WordHunterWoW_QuestEN[89195] = { title = "Funny Buzzness", description = "I seem to bee running low on bee puns at the moment, but I do need more bees from Stormsong Valley. Would you bee a dear and collect them for me?", objectives = "" }
WordHunterWoW_QuestEN[89197] = { title = "Ray Ranching", description = "Ah, there you are. I need to perform medical checkups on the necrorays, and I could use some assistance in capturing them. Perhaps you could help?", objectives = "" }
WordHunterWoW_QuestEN[89198] = { title = "Dry Cleaning", description = "Aw heck! The k'arrocs are acting all feisty again. \n\nMind giving them a good clean so their natural aroma can rise to the top?", objectives = "" }
WordHunterWoW_QuestEN[89199] = { title = "A Small Task", description = "You will forgive the lack of pleasantries, as this situation requires prompt remediation.\n\nAll you need know is that I am Aradis, wardsmith of Silvermoon. We are an order of Magisters who maintain the city's defenses.\n\nI am recovering from a... minor battle injury, and require aid charging my wardbreaker staff. You will be compensated, and perhaps provided additional opportunities to aid me.\n\nI can furnish the details as you work, so long as you are not terribly slow.", objectives = "" }
WordHunterWoW_QuestEN[89200] = { title = "Unraveling Wards", description = "Dawnblaze is keeping the blackmail documents in her study. It is highly warded, naturally.\n\nThe wards themselves are pitifully made. However, she is supplying additional power to them using arcane conduits placed throughout the city. I found the first link in the chain and brought it here to study.\n\nIt is also warded, but weakly. I theorize that if the conduits are broken in sequence, then the shields on Dawnblaze's study will be vulnerable.\n\nSabotage them, then recover the documents. Understood?", objectives = "" }
WordHunterWoW_QuestEN[89201] = { title = "Outschemed", description = "The entrance to Dawnblaze's study is in the terrace just beneath us.\n\nSince my magic can project this close to her wards, that means the magic guarding this place has been weakened... as I predicted.\n\nBreak the larger ward sealing the entrance and find the documents she forged to slander me. I will expect your expedient return to my office thereafter.", objectives = "" }
WordHunterWoW_QuestEN[89202] = { title = "Stir the Nest", description = "Aradis told you the blackmail was false? Of course. He is vying for my position. These receipts would ruin him.\n\nHe is a warlock, and we have rules about fel magic. It is not banned, but it must be used discreetly. Aradis is not discreet. Magic misuse, unsanctioned demons, fel smuggling, bribery... His list of crimes is long.\n\nBut you need not take my word for it. Aradis has earned many enemies in the city. If you can find him in the Row, a man named Jaeth could tell you all about our dear warlock.", objectives = "" }
WordHunterWoW_QuestEN[89203] = { title = "Mutual Benefit", description = "<Jaeth waves a hand to cut you off as you explain.>\n\nAll right, Dawnblaze sent you. That means there's a job. Not surprised she doesn't want to dirty her robes coming to the Row herself. The types who hire us never do.\n\nEveryone that high up in Silvermoon backstabs each other. When it's literal, they pay us to do it for them. They get whatever power they're chasing, and we get enough coin to live another week.\n\nWhose back is getting a knife this time?", objectives = "" }
WordHunterWoW_QuestEN[89204] = { title = "Five Finger Discount", description = "Aradis gave you his wardbreaker? What an idiot. Those get sold on the black market as skeleton keys. Expensive, but you have to attune them to the magic you're breaking, which isn't easy.\n\nLooks like yours is empty. We can fix that. If we pocket a few magic valuables around the city, my buddy upstairs can disenchant them and get that wardbreaker juiced with fel magic.\n\nAradis won't have anywhere to hide then.", objectives = "" }
WordHunterWoW_QuestEN[89205] = { title = "Cutting a Key", description = "I told Zanien here the whole story. He's been training warlocks for a long time--and if anyone hates sloppy ones, it's him.\n\nHe's confident he can get the wardbreaker recharged. Follow his instructions and we should be good to head out afterward.", objectives = "" }
WordHunterWoW_QuestEN[89206] = { title = "Break and Enter", description = "Can you hear that? It sounds like it's coming from downstairs. Like someone's in pain.\n\nThe last kidnapping from the Row was pretty recent. This could be where he's been keeping the people he took.\n\nMy people. My friends.\n\nEven if Aradis doesn't show his face, we're not letting him keep them here. Bring this ward down. We're going in.", objectives = "" }
WordHunterWoW_QuestEN[89207] = { title = "Rats Can Bite", description = "I know all of these people. They're workers, not fighters. Aradis went after the ones who couldn't fend him off. That's why he ran when he tried to take me and realized he picked the wrong target.\n\nAfter the trouble we've made, there's no way he doesn't know we're here.\n\nBe on guard. Once he shows his face, he's dead.", objectives = "" }
WordHunterWoW_QuestEN[89208] = { title = "What We're Owed", description = "Everyone out here should be fine. Sarvi... I'll get her back to the Row. If we leave her here, the guards will just have the body tossed.\n\nI hope they do the same to Aradis, but I'm sure they won't.\n\nCome on. Let's go talk to Dawnblaze and get our payment. I remember where her office is.", objectives = "" }
WordHunterWoW_QuestEN[89209] = { title = "Bu-zzz", description = "These bees are absolute workhorses--workbees? They are worker bees so I suppose... ah, apologies for my distraction.\n\nSeveral of the bees have tired themselves out. Can you return them to the hive?", objectives = "" }
WordHunterWoW_QuestEN[89210] = { title = "Photography is the Bee's Knees", description = "All right, {name}. Take this camera and this film. You've done this before. It's time for documentation!\n\nI know you are practically buzzing to get out there, but it's time to bee focused.", objectives = "" }
WordHunterWoW_QuestEN[89212] = { title = "Royal Photographer", description = "<Om'talad is intently taking several photos of himself.>\n\nAh! {name}! We need to update our documentation of the thorntails. \n\nThis camera I was... testing appears to be functioning correctly. Please go update our documentation.", objectives = "" }
WordHunterWoW_QuestEN[89213] = { title = "Flights of Fancy", description = "We are in need of new photos of the k'arrocs for our records. Please take some for us while you are out in the eco-dome.", objectives = "" }
WordHunterWoW_QuestEN[89221] = { title = "Leafing Things on the Ground", description = "I woke up today and thought to myself, \"That platter of food {name} put out for the lapbugs was excellent. I suspect the lapbugs would like it if {name} did that again.\"\n\nWhy don't you make that happen, hmm?", objectives = "" }
WordHunterWoW_QuestEN[89222] = { title = "Remnant of Azeroth", description = "Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt.\n\nKul Tiras calls out to you.", objectives = "" }
WordHunterWoW_QuestEN[89223] = { title = "Remnant of Azeroth", description = "Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt.\n\nZandalar calls out to you.", objectives = "" }
WordHunterWoW_QuestEN[89230] = { title = "A Lover Not a Fighter", description = "De elders are plannin' a festival to give thanks to de loa. I wanna ask Namaji to accompany me but....\n\nIt is tradition that a suitor give a gift that proves their prowess as a warrior. But I am a poor fighter and de others laugh at me because of it.\n\n<Kagara hangs his head dejectedly.>\n\nPerhaps you can help me? I know Namaji has always wanted a threshadon tooth necklace. De gnarldin make dem, but only de strongest have one.\n\nCould you find one for me and deliver it to her on my behalf?", objectives = "" }
WordHunterWoW_QuestEN[89231] = { title = "A Fighter Not a Lover", description = "You goin' to de loa festival? Young trolls like me are expected to ask someone dey like to go wit' dem. And to give a gift to show their worthiness.\n\nI wanna go wit' Namaji. I'm a great fighter, but I'm sure there are many other warriors dat wanna go wit' her!\n\nThey'll gift her trophies and spoils. But I'll be different.\n\nI think she'd like a headdress, but I have no idea how to make one. Could you make a feathered headdress for me and give it to her?\n\nYou can find feathers at Akil'zon's Reach.", objectives = "" }
WordHunterWoW_QuestEN[89233] = { title = "Love Triangle", description = "It seems we have a problem: Kagara and Zak'kash both wanna go wit' me to de festival! Which one do I choose?\n\nI like both of dem well enough. Please {name}, you need to help me! What do you think?", objectives = "" }
WordHunterWoW_QuestEN[89238] = { title = "Follow-up Appointment", description = "There is much medical data to be gleaned in the evaluation of the k'arrocs.\n\nPlease take the condenser disc to shrink them and then pick the little ones up for easy transport.", objectives = "" }
WordHunterWoW_QuestEN[89240] = { title = "Dream-Dream-Dream-Dream-Dreameringeding!", description = "We need to check how the thorntails are progressing. Would you be so kind as to gather more blood samples?\n\nAs before, use the darts to put them to sleep and then retrieve the dart with the blood on it.", objectives = "" }
WordHunterWoW_QuestEN[89242] = { title = "I Want a Golden Ooze!", description = "It seems our custodians have been lax in their duties once again.\n\nTake the vacuum device. Clean up the lumps. I will cut you a percentage of the returns.", objectives = "" }
WordHunterWoW_QuestEN[89249] = { title = "Overwhelmed", description = "We were too late. All of the strength between us wasn't enough.\n\n<Arator looks over his shoulder, wary. Then, he crouches and places his hand on Alleria's shoulder. She responds only with a ragged exhale.>\n\nLet's fall back. The ren'dorei have been exploring the wilds while we've been following Lothraxion. We might be able to find their encampment nearby.", objectives = "" }
WordHunterWoW_QuestEN[89250] = { title = "Burning Rubber", description = "<Few things are as exhilarating as unbridled speed, and few things are as respected as the G-99 Breakneck in Nanny Talullah's garage.\n\nMobber will certainly know how to tune your ride with the new part.>", objectives = "" }
WordHunterWoW_QuestEN[89251] = { title = "Running Hot!", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89252] = { title = "Need a Jump?", description = "What can I do you for?", objectives = "" }
WordHunterWoW_QuestEN[89254] = { title = "Shutterbug", description = "The pictures with the lapbugs were a smash hit. We need more of them for marketing.\n\nSorry, {name}. In this case, the lapbugs with hats are more in-demand than you. Do not be sad though. At least you're getting paid while also getting your face out there, yes?\n\nNow, get clicking.", objectives = "" }
WordHunterWoW_QuestEN[89263] = { title = "Your Cut of the Spoils", description = "You {name}? Got something for you.", objectives = "" }
WordHunterWoW_QuestEN[89268] = { title = "Lost Legends", description = "Among these walls lie relics, silent and forgotten, their stories obscured by time.\n\nThe path to reclaiming our past is clear: take a relic to the sacred shrines and step into the echoes of its history. The visions will guide you, letting you walk the tale firsthand and breathe life into memory once more.\n\nIf you would lend your spirit to this cause, choose a relic to reawaken its story.", objectives = "" }
WordHunterWoW_QuestEN[89271] = { title = "My Son", description = "One moment, {name}. I have a personal matter. I would like you to find my son, Arator. He is a member of the Silver Hand, an accomplished paladin. \n\nI know he must have been called. His faith is strong. The Light would want him here fighting against Xal'atath.", objectives = "" }
WordHunterWoW_QuestEN[89276] = { title = "Light Snacks", description = "Classics are classic for a reason, darling. One simply cannot host a worthwhile soiree without a fine selection of mana for one's guests to indulge in.\n\nThe Magisters could bring some, but mana is best when freshly siphoned. The mana wyrms in southern Eversong have a decadent brightness to them that I find particularly lovely.\n\nBe a dear and gather some for us.", objectives = "" }
WordHunterWoW_QuestEN[89277] = { title = "Illuminate the Space", description = "I share our dear Saltheril's love for vintage fixtures, but the lighting enchantment he is using is far too common for such an auspicious occasion.\n\nMy Magisters can create a far more stunning enchantment. Simply gather some fibers from the Lightbloom for me and I can have them broken down into spell reagents.\n\nThe effect will be marvelous.", objectives = "" }
WordHunterWoW_QuestEN[89278] = { title = "Minding Our Duty", description = "While the court does demand our consideration, we cannot forget duties. Our guests will enjoy themselves more freely if they are assured of the solidity of Eversong's defenses.\n\nThe Magisters are tasked with maintaining the runestone wards throughout Eversong. Please survey them for us and let us know if any wards need our attention.", objectives = "" }
WordHunterWoW_QuestEN[89285] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89286] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89287] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89289] = { title = "Favor of the Court", description = "Ah, {name}, my favorite {class}! I am delighted to see you in attendance once more.\n\nYou have quite the natural talent for these sorts of affairs. The nobles are pleased with your presence and your favor has been swaying their coffers.\n\nLet us not stop a good thing, shall we? Help me choose an ally of our representatives to invite to the Haven this week. I'm ever curious to see the drama you will stir up.\n\nAs my personal guest of honor, your favor will be seen as an extension of my favor.", objectives = "" }
WordHunterWoW_QuestEN[89295] = { title = "The Flame Burns Eternal", description = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades.\n\nCan we count on your continued support in the battles ahead?", objectives = "" }
WordHunterWoW_QuestEN[89297] = { title = "Not as Cute When They Are Bigger and Angrier", description = "It seems there are some who are looking to adopt lapbugs. Adoptions mean more revenue.\n\nUltimately, this benefits the Oasis. Please acquire more essence for me.", objectives = "" }
WordHunterWoW_QuestEN[89307] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89308] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89309] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89311] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89312] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89313] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89314] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89315] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89316] = { title = "Saltheril's Favor", description = "To what do I owe the pleasure?", objectives = "" }
WordHunterWoW_QuestEN[89317] = { title = "Children's Week in Dornogal", description = "Oh, hello! You must be {name}. I can't thank you enough for stopping by to help with these little ones. \n\nSince we earthen don't have children of our own, I thought it would be fun to help some of our allies out for the week, but it turns out children are quite... energetic. I also don't have a good grasp of what children find \"fun\" yet.  \n\nIf you could take the kobold youngling with you that would be helpful. They seem to have somewhere they want to visit.  \n\nTake this whistle to call them to you.", objectives = "" }
WordHunterWoW_QuestEN[89318] = { title = "Bold for a Kobold", description = "Big-Tall! Nice Talk-Rock tell Skibbles that she get to do whatever she want today! \n\nWell, me have big dream. One so big, me get in trouble for it. A lot. \n\n<Skibbles takes a deep breath.> \n\nMe want to be brave candle knight, like shiny humans with floaty boats! \n\nA-and me hear there is crystal that's brighter than any candle! \n\n<Skibbles pauses, seemingly anticipating rejection.> \n\nWould...would you take Skibbles to see candle knights with big kitties?", objectives = "" }
WordHunterWoW_QuestEN[89319] = { title = "The Wondrous Weave", description = "<Destien looks at his feet as you approach.>\n\nH-hello! I'm Destien. Earthen Matron Ullna told me about you, and said you are an adventurer! You must have seen all kinds of spooky and awesome things, right?\n\nT-there is one thing I would like to do, but I'm worried it will scare people.\n\n<Destien looks around nervously and lowers his voice.>\n\n I've heard there are good nerubians and that you've met them! I've always wanted to talk to one but they scare me.\n\nWould you come with me to meet them?", objectives = "" }
WordHunterWoW_QuestEN[89320] = { title = "The Eager Engineer", description = "<Threadis looks up at you nervously. \n\nThey hold up what appears to be a drawing of a goblin rocket, similar to the rocket drill going to Undermine. \n\nPerhaps they would like to ride the rocket drill to Undermine located in the Ringing Deeps?>", objectives = "" }
WordHunterWoW_QuestEN[89321] = { title = "Recreation for Rooks", description = "Hey! You're {name}, ain't ya? My name's Kitzy! Man am I sure glad to see you. \n\nLook, I really wanna go back up to the surface to the stone city. The air is so clean and the sun is so bright!\n\nI also saw a giant blue bird fly overhead, except it had lots of legs! Ullna said it was called a...ruk? Rock? Somethin' like that.\n\nAnyway, I wanna see one! I ain't never seen anything so pretty before. Do you think I can pet one?\n\n<Kitzy gasps, her eyes shining in excitement.>\n\nDo you think I could RIDE one?", objectives = "" }
WordHunterWoW_QuestEN[89322] = { title = "A Brighter Tomorrow", description = "{name}, look at this! All of these people are here to discuss the children's futures. \n\nThey expressed a desire to speak with you as well.", objectives = "" }
WordHunterWoW_QuestEN[89323] = { title = "Wasted Lands", description = "Illidan taught us that if we are to fight threats that acknowledge no limits, we must be willing to do the same. With his rage he tamed the power of the fel, and so will I, with the void.\n\nA fragment from this world, touched by the All-Devouring, is held deep in the heart of North Sufaad. With the void essence Leona collected, and this fragment as a vessel, I will yoke the power of the void to my will.\n\nCombining the strength of the illidari and the secrets of the ren'dorei will make me unstoppable.", objectives = "" }
WordHunterWoW_QuestEN[89324] = { title = "A Piece of Something Greater", description = "Seek out the Relictors. They comb through these wastes like carrion feeders, sifting through proof of their people's weakness in a misguided attempt to find strength.\n\n<Adarus spits contemptuously onto the sand.>\n\nThe only object of real value is here in front of us, and they keep it contained out of fear. I will not make that mistake.\n\nGo, find these Relictors, unburden them of their keys, and return.", objectives = "" }
WordHunterWoW_QuestEN[89325] = { title = "The Void Confluence", description = "At last, {name}. With the promise of this fragment's power, and my mastery over the illidari ways, I will be ready to fight the shadowguard and any other threats the void throws at us.\n\nLeona spoke of a cave near Shan'dorah where the void energies suffusing K'aresh converge.\n\nMeet us there, and play a part in my ascension.", objectives = "" }
WordHunterWoW_QuestEN[89326] = { title = "Distilled Darkness", description = "Adarus is preparing his mind and body for the ritual.\n\nOur task is to place the fragment at two points within this cavern, which will both align the crystal to the void energy in the area and attract any void entities that reside nearby.\n\nDefeat those entities and their essence will be absorbed into the fragment, empowering it further.", objectives = "" }
WordHunterWoW_QuestEN[89327] = { title = "Chaos", description = "This is it, {name}. Place the K'areshi fragment above Adarus, and I will channel the void lure containing Ramon'ta's void essence into the shard.\n\nAdarus is powerful and determined, but we're attempting something both experimental and dangerous.\n\nI'll ask you to be vigilant.", objectives = "" }
WordHunterWoW_QuestEN[89331] = { title = "Flame Fortification", description = "Sureki forces are gathering all over Hallowfall and Azj-Kahet--but we're certain they're just distractions. We think the main attack will come from the west.\n\nWhen the time comes we'll need all the help we can get to push them back and defend Mereldar.\n\nCan Flame's Radiance count on your support?", objectives = "" }
WordHunterWoW_QuestEN[89332] = { title = "Boot Camp", description = "The Sureki gather across Hallowfall and Azj-Kahet while we prepare for their attack on Mereldar. They want to split our forces, but we cannot ignore their activities elsewhere.\n\nThe Flame's Radiance forces are defending against their incursions in Hallowfall while we run incursions of our own into Azj-Kahet.\n\nRendezvous with the Flame's Radiance in the field and assist their efforts.", objectives = "" }
WordHunterWoW_QuestEN[89334] = { title = "Ahead of the Issue", description = "I do not know de loa Akil'zon, but she cannot be happy with de gnarldin defilin' de hash'ey shrines and makin' meals of her eagle kin.\n\nWe gotta let dem know dis is a sacred place and dat we will not take kindly to their presence here.\n\nI may not know Akil'zon, but I know de giants. All dey understand is strength--de language of Zul'Aman.\n\nOur strongest message we can send is to take de heads of their fiercest warriors.", objectives = "" }
WordHunterWoW_QuestEN[89338] = { title = "Gathering Plowshares", description = "{name}, now that Hammerfall can expect peace with Stromgarde, there's a lot more use in being able to farm and craft than in fighting. \n\nSo, we've been gathering old weapons from past skirmishes to make into tools for the people of Hammerfall.\n\nWould you and Arator be willing to give me a hand?", objectives = "" }
WordHunterWoW_QuestEN[89343] = { title = "The Untethered Void", description = "The Reshii Wraps that the Harbinger gave you allow you to briefly transform into energy and fall into Untethered Space. This is a nightmare for all ethereals--a natural result of losing our wraps and radiating away our energy. \n\nWe can control the process by properly attuning with the Phase Conduit, letting us visit this sub-realm and return intact. That is the theory. We have tested it with K'areshi Phase Divers, but not with one of your kind.\n\nAre you willing to risk the journey to Untethered Space?", objectives = "" }
WordHunterWoW_QuestEN[89344] = { title = "What Doesn't See You", description = "Untethered Space is an arcane phenomenon twisted by creatures of the Void that feed on its energy. Should we ethereals damage our wraps or the brokers their suits, our energy cannot remain intact for long. Then, we fall into this layer of reality, possibly never to return.\n\nThe upside of this nightmare is that all the energy that falls out of phase is valuable. Use the Phase Conduit to enter Untethered Space, and fight the observers that scavenge phase energy there.", objectives = "" }
WordHunterWoW_QuestEN[89345] = { title = "The Untethered Horror", description = "Void predators that have recently invaded Untethered Space are a mere annoyance compared to the ancient creatures that traveled here long ago. These primal predators feed on the energies of the remnants of old K'aresh, as well as the unfortunate K'areshi who have fallen into this state of being.\n\nThere is one such creature we call Netherdeath that haunts this rock. We have only been able to drive it away. Perhaps you have the skill to end its reign of terror?", objectives = "" }
WordHunterWoW_QuestEN[89348] = { title = "Let There Bee Love", description = "All right. I'll get these bees over to the Oasis and meet you there.", objectives = "" }
WordHunterWoW_QuestEN[89349] = { title = "Flame's Radiance Stipend", description = "", objectives = "" }
WordHunterWoW_QuestEN[89351] = { title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", objectives = "" }
WordHunterWoW_QuestEN[89352] = { title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", objectives = "" }
WordHunterWoW_QuestEN[89353] = { title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", objectives = "" }
WordHunterWoW_QuestEN[89354] = { title = "Preparing for Battle", description = "Void creatures have been multiplying throughout Slayer's Rise. Go help clear some out and return to me for a prize. \n\nThere are turrets that are normally used in battle that can be used to make this task easier for you.", objectives = "" }
WordHunterWoW_QuestEN[89380] = { title = "Another World", description = "I represent a group within the Trust tasked with a dangerous but vital job--Phase Diving. I was at Overlook Zo'Shuul when the Harbinger transformed you into energy. It is similar to that, but more profitable.\n\nThe Trust embarks on Phase Dives to help replenish our energy reserves. On K'aresh, energy is power--and now we must compete with the Shadowguard. We desperately need the help of someone like you.\n\nMeet me at Overlook Zo'Shuul if you are interested. We will, of course, compensate you.", objectives = "" }
WordHunterWoW_QuestEN[89383] = { title = "One Adventurous Hatchling", description = "One of my hatchlings was frightened off when that giant construct marched past the ranch. He bolted right through the fence and into the woods before I could stop him!\n\nHe's small, fast, and probably hiding somewhere nearby. Please find him before something else does, and return him to me.", objectives = "" }
WordHunterWoW_QuestEN[89384] = { title = "A Hungry Flock", description = "Some think that raising hawkstriders is an easy task, but it most certainly is not. Hawkstrider appetites tend to be notoriously fussy!\n\nMore often than not they'll turn their beaks up at anything I offer. But this time of year? Frog legs. They love the slimy little things. They can't get enough of them!\n\nThere's a pond just down the hill just swarming with the leggy little morsels. Could you gather some for me, please?", objectives = "" }
WordHunterWoW_QuestEN[89385] = { title = "First Step Into Parenthood", description = "", objectives = "" }
WordHunterWoW_QuestEN[89386] = { title = "A Roost-ed Development", description = "A comfortable hawkstrider is a happy hawkstrider. We don't expect them to stand all day. They need someplace cozy to roost!\n\nThere's a plant called golden sunleaf that sprouts just beyond the ridge. It makes the softest bedding--the hawkstriders love it. Could you gather some for me?", objectives = "" }
WordHunterWoW_QuestEN[89388] = { title = "Voidstorm", description = "Magister Umbric has a plan to infiltrate the Voidstorm and take the fight to the Devouring Host directly.\n\nThis will be no easy task, and he is assembling a small but powerful team to strike at the enemy's heart.", objectives = "" }
