WordHunterWoW_QuestEN[89402] = { title = "Harandar", description = "With the Devouring Host occupying much of our attention and time, we leave our backs exposed to other threats that wait in the wings. This Lightbloom that has afflicted Eversong grows worse by the day. If it gets out of control, then we might find ourselves fighting a two-front conflict--or worse, having our home consumed completely while we busy ourselves with the Void.\n\nThe strange woman who you found poking about the Lightbloom... You seem to be familiar with her. Seek her out. She may have answers.", objectives = "" }
